-- Six original TEF Canada Reading papers, immutable attempts, strict publication checks.
-- Apply after 20261120173000_tef_reading_stable_current_catalog.sql.
begin;

-- Database layer blocks exact cross-paper source/question/graph duplicates and identical
-- semantic intent labels even if a caller bypasses GitHub CI. Near-duplicate fuzzy checks
-- remain in the content-authoring gate because SQL text matching alone is insufficient.
create or replace function academy_tef_reading.reject_repeat_papers() returns trigger
language plpgsql security invoker set search_path='' as $body$
begin
 if jsonb_typeof(new.content->'questions')<>'array' or jsonb_array_length(new.content->'questions')<>40 then
  raise exception 'TEF Reading papers require 40 questions';
 end if;
 if exists(
  select 1 from academy_tef_reading.papers p,
      lateral jsonb_array_elements(p.content->'questions') previous,
      lateral jsonb_array_elements(new.content->'questions') candidate
  where p.id<>new.id and (
   (nullif(previous->>'passage','') is not null and
       lower(regexp_replace(previous->>'passage','[[:digit:][:space:][:punct:]]+','','g'))=
       lower(regexp_replace(candidate->>'passage','[[:digit:][:space:][:punct:]]+','','g')))
    or (previous->>'question'=candidate->>'question' and previous->'options'=candidate->'options')
    or (nullif(previous->'semantic'->>'concept','') is not null and
        previous->'semantic'->>'concept'=candidate->'semantic'->>'concept' and
        previous->'semantic'->>'evidence'=candidate->'semantic'->>'evidence')
    or (previous->'media'->>'kind'='chart-grid' and candidate->'media'->>'kind'='chart-grid'
        and previous->'media'->'series'=candidate->'media'->'series')
  )
 ) then raise exception 'Duplicate or semantically repeated TEF Reading bank content is prohibited';end if;
 return new;
end $body$;
drop trigger if exists tef_reading_prevent_repeat on academy_tef_reading.papers;
create trigger tef_reading_prevent_repeat before insert or update on academy_tef_reading.papers
for each row execute function academy_tef_reading.reject_repeat_papers();
revoke all on function academy_tef_reading.reject_repeat_papers() from public,anon,authenticated,service_role;

-- All answer-bearing banks remain in the protected schema, never returned in catalog.
do $publish$
declare paper jsonb;
begin

 paper := $bank1${"id":"tef-reading-01","version":"tef-reading-2026-11-original-01-v2","title":"TEF Canada · Compréhension écrite · Test 01","seconds":3600,"maxPoints":40,"questions":[{"number":1,"points":1,"passage":"🏛️ MÉDIATHÈQUE DES RIVES\nLa salle de lecture fermera jeudi de 9 h à 12 h pour l'installation de nouveaux postes informatiques. Le prêt et le retour des livres restent possibles au comptoir du rez-de-chaussée.","question":"Que pourront faire les usagers jeudi matin ?","options":["Consulter sur place les livres de la salle temporaire","Utiliser les ordinateurs pendant les travaux","Accéder à une salle de lecture du premier étage","Emprunter ou rendre des livres au comptoir maintenu"],"correct":"D","explanation":"Seule la salle de lecture est fermée : le comptoir reste disponible pour les prêts et retours.","media":{"kind":"notice","icon":"📚","heading":"Information aux lecteurs","accent":"#28609b"},"semantic":{"concept":"library-reading-room-closed-counter-open","evidence":"borrow-returns-ground-floor"}},{"number":2,"points":1,"passage":"🚉 INFORMATION VOYAGEURS\nEn raison de travaux sur la ligne C, les trains ne desserviront pas la station Université dimanche entre 7 h et 13 h. Une navette gratuite reliera les stations Parc et Université toutes les quinze minutes.","question":"Quelle solution est proposée pendant les travaux ?","options":["Une correspondance par train régional sur un autre quai","Une navette payante assurée uniquement le matin","Un transport gratuit entre les deux stations annoncées","Un accès à la station fermée par une sortie secondaire"],"correct":"C","explanation":"Une navette gratuite assurera la liaison vers la station Université pendant la suspension des trains.","media":{"kind":"notice","icon":"🚉","heading":"Ligne C · Service adapté","accent":"#0e7490"},"semantic":{"concept":"rail-closure-shuttle-replacement","evidence":"complimentary-shuttle-four-times-hourly"}},{"number":3,"points":1,"passage":"🌿 ATELIER DU JARDIN PARTAGÉ\nSamedi 21 mai, de 10 h à 12 h, apprenez à préparer des semis avec les bénévoles du quartier. Matériel fourni ; participation gratuite sur inscription avant jeudi. Rendez-vous devant la serre municipale.","question":"Que faut-il faire pour participer ?","options":["Réserver ses outils de jardinage avant le samedi","Payer une participation lors de l'accueil","Confirmer son inscription avant la date indiquée","Présenter une attestation de participation antérieure"],"correct":"C","explanation":"L'atelier est gratuit et le matériel fourni, mais l'inscription doit être faite avant jeudi.","media":{"kind":"illustration","scene":"garden","heading":"Atelier de jardinage"},"semantic":{"concept":"garden-workshop-register-by-deadline","evidence":"registration-required-before-thursday"}},{"number":4,"points":1,"passage":"🎭 FORUM DES ASSOCIATIONS\nDécouvrez les activités du quartier le samedi 10 septembre, de 14 h à 18 h, à la Maison des fêtes. Rencontrez les bénévoles, assistez à des démonstrations et renseignez-vous sur les inscriptions pour l'année.","question":"Quel est l'objectif principal de ce forum ?","options":["Faire connaître les associations et leurs activités","Recruter des professionnels pour des postes salariés","Vendre les billets des spectacles des associations","Organiser un concours entre les associations du quartier"],"correct":"A","explanation":"Le forum met les visiteurs en contact avec plusieurs associations et leurs activités.","media":{"kind":"illustration","scene":"fair","heading":"Forum des associations"},"semantic":{"concept":"neighborhood-associations-forum-purpose","evidence":"association-discovery-not-performance"}},{"number":5,"points":1,"passage":"🎨 APPEL À CONTRIBUTIONS\nAidez de jeunes illustrateurs à présenter leurs œuvres dans les écoles du département. Chaque don finance l'impression et l'accrochage d'une planche. L'exposition est gratuite pour les établissements ; un reçu est envoyé aux donateurs.","question":"Ce message invite principalement le public à : ","options":["Acheter une illustration pour financer un atelier","Contribuer aux frais de présentation des œuvres","S'inscrire à un stage animé par les illustrateurs","Proposer des dessins destinés à la même exposition"],"correct":"B","explanation":"L'appel à contributions sert à payer l'impression et l'installation des œuvres.","media":{"kind":"notice","icon":"🎨","heading":"Soutenez les jeunes créateurs","accent":"#8b5cf6"},"semantic":{"concept":"illustrator-exhibition-donation-funding","evidence":"funding-print-and-display"}},{"number":6,"points":1,"passage":"🚲 NOUVEAU SERVICE MUNICIPAL\nQuatre stations de vélos en libre-service viennent d'ouvrir près de la gare. Les abonnés peuvent retirer un vélo dans une station et le rendre dans une autre, sans passer par le guichet.","question":"Quel avantage ce service propose-t-il ?","options":["Réserver à distance une place pour son propre vélo","Utiliser les vélos sur les quais de la gare","Déposer le vélo emprunté dans une autre station","Bénéficier de trajets illimités sur les lignes de train"],"correct":"C","explanation":"Les abonnés peuvent emprunter un vélo dans une station et le déposer dans une autre.","media":{"kind":"notice","icon":"🚲","heading":"Vélos en libre-service","accent":"#16a34a"},"semantic":{"concept":"bike-share-return-different-dock","evidence":"different-docking-site"}},{"number":7,"points":1,"passage":"🧪 SEMAINE DES SCIENCES\nDes collégiens ont présenté des expériences sur la qualité de l'eau et la consommation d'énergie. Les familles ont visité les ateliers et discuté avec les élèves des résultats observés.","question":"Ce texte présente : ","options":["Une compétition organisée autour des matières scientifiques","Une vente de matériel présenté aux familles d'élèves","Une séance de formation réservée aux laborantins","Une présentation d'expériences réalisées par les élèves"],"correct":"D","explanation":"Les élèves présentent leurs expériences et expliquent leurs résultats aux familles.","media":{"kind":"notice","icon":"🧪","heading":"La science à l'école","accent":"#d97706"},"semantic":{"concept":"school-science-family-demonstrations","evidence":"pupils-present-experiments"}},{"number":8,"points":1,"passage":"Pour consulter vos résultats, saisissez votre ________ personnel, qui permet de reconnaître votre compte sans révéler votre mot de passe.","question":"Quel mot complète la phrase ?","options":["identifiant","justificatif","numéro de facture","certificat"],"correct":"A","explanation":"L'identifiant sert à désigner le compte ; le mot de passe reste une information différente.","section":"cloze","semantic":{"concept":"platform-user-id-distinguished-from-password","evidence":"login-identifier-not-secret"}},{"number":9,"points":1,"passage":"Les demandes seront examinées dans l'ordre de réception : votre dossier sera traité ________ ceux déposés la semaine précédente.","question":"Quel mot complète la phrase ?","options":["avec","après","avant","malgré"],"correct":"B","explanation":"Le traitement suit l'ordre d'arrivée : les dossiers déjà reçus passent avant celui-ci.","section":"cloze","semantic":{"concept":"service-application-first-come-order","evidence":"no-priority-after-earlier-applications"}},{"number":10,"points":1,"passage":"Avant de monter à bord, il faut ________ le billet imprimé dans la borne mécanique qui appose une date et une heure.","question":"Quel verbe complète la phrase ?","options":["présenter","préparer","composter","prolonger"],"correct":"C","explanation":"La borne mécanique composte le billet en y imprimant sa validation.","section":"cloze","semantic":{"concept":"rail-paper-ticket-mechanical-stamping","evidence":"stamp-date-time-at-machine"}},{"number":11,"points":1,"passage":"Les dates figurant dans le programme sont communiquées à titre ________ : elles peuvent encore être modifiées.","question":"Quel mot complète la phrase ?","options":["indicatif","officiel","obligatoire","contractuel"],"correct":"A","explanation":"« À titre indicatif » signifie que ces dates sont données comme informations provisoires.","section":"cloze","semantic":{"concept":"meeting-date-provisional-indication","evidence":"dates-not-definitively-agreed"}},{"number":12,"points":1,"passage":"UN LOGEMENT PLUS ÉCONOME\nAfin de limiter les pertes de chaleur, les habitants ont commencé par mieux ________ (1) les fenêtres pendant l'hiver. Ils ont ensuite comparé leurs factures afin d'évaluer les ________ (2) réalisées.","question":"Quel mot convient à l'espace (1) ?","options":["réparer","resserrer","ouvrir","isoler"],"correct":"D","explanation":"Isoler les fenêtres réduit les pertes de chaleur en hiver.","section":"paired-cloze","group":"Un logement plus économe","semantic":{"concept":"energy-loss-window-insulation","evidence":"reduces-winter-heat-loss"}},{"number":13,"points":1,"passage":"UN LOGEMENT PLUS ÉCONOME\nAfin de limiter les pertes de chaleur, les habitants ont commencé par mieux ________ (1) les fenêtres pendant l'hiver. Ils ont ensuite comparé leurs factures afin d'évaluer les ________ (2) réalisées.","question":"Quel mot convient à l'espace (2) ?","options":["dépenses","factures","économies","consommations"],"correct":"C","explanation":"La comparaison des factures permet d'évaluer les économies d'énergie réalisées.","section":"paired-cloze","group":"Un logement plus économe","semantic":{"concept":"household-cost-savings","evidence":"compare-energy-bills"}},{"number":14,"points":1,"passage":"PARTAGER SES COMPÉTENCES\nUne association propose un échange de services : chacun peut consacrer quelques heures à ________ (1) un voisin dans une démarche. Sans rémunération, le fonctionnement repose sur la ________ (2) entre membres.","question":"Quel mot convient à l'espace (1) ?","options":["accompagner","remplacer","représenter","superviser"],"correct":"A","explanation":"Accompagner un voisin dans une démarche correspond à une aide bénévole.","section":"paired-cloze","group":"Partager ses compétences","semantic":{"concept":"neighbor-help-volunteer-companionship","evidence":"assist-neighbor-voluntarily"}},{"number":15,"points":1,"passage":"PARTAGER SES COMPÉTENCES\nUne association propose un échange de services : chacun peut consacrer quelques heures à ________ (1) un voisin dans une démarche. Sans rémunération, le fonctionnement repose sur la ________ (2) entre membres.","question":"Quel mot convient à l'espace (2) ?","options":["collaboration","disponibilité","bienveillance","réciprocité"],"correct":"D","explanation":"La réciprocité permet aux participants de s'entraider sans paiement.","section":"paired-cloze","group":"Partager ses compétences","semantic":{"concept":"reciprocal-skill-exchange-nonmonetary","evidence":"mutual-help-not-pay"}},{"number":16,"points":1,"passage":"DÉCOUVRIR UNE RÉGION\nL'office de tourisme invite les voyageurs à privilégier les déplacements en ________ (1) pour rejoindre les villages desservis par le réseau ferroviaire régional. Le service cherche aussi à ________ (2) la circulation automobile en été.","question":"Quel mot convient à l'espace (1) ?","options":["train","minibus","voiture","taxi"],"correct":"A","explanation":"Le train permet de rejoindre les villages desservis par le réseau régional.","section":"paired-cloze","group":"Découvrir une région","semantic":{"concept":"regional-rail-tourism-interconnected-villages","evidence":"rail-connects-villages"}},{"number":17,"points":1,"passage":"DÉCOUVRIR UNE RÉGION\nL'office de tourisme invite les voyageurs à privilégier les déplacements en ________ (1) pour rejoindre les villages desservis par le réseau ferroviaire régional. Le service cherche aussi à ________ (2) la circulation automobile en été.","question":"Quel mot convient à l'espace (2) ?","options":["fluidifier","réduire","détourner","mesurer"],"correct":"B","explanation":"Le recours au train peut réduire la circulation des voitures.","section":"paired-cloze","group":"Découvrir une région","semantic":{"concept":"transport-less-congestion","evidence":"reduces-car-journeys"}},{"number":18,"points":1,"passage":"","question":"Quelle offre correspond à un emploi qui se déroule essentiellement en plein air ?","options":["Offre 1","Offre 2","Offre 3","Offre 4"],"correct":"D","explanation":"La quatrième offre concerne l'entretien des sentiers forestiers, une activité extérieure.","section":"offers","media":{"kind":"offers","heading":"Offres d'emploi · Conditions et environnement","items":["Centre aquatique — entretien intérieur des bassins, sorties ponctuelles sur les espaces extérieurs","Centre de découverte — accueil principalement en salle, quelques animations dans le parc","Entreprise horticole — gestion des stocks en serre, tâches saisonnières autour des serres","Parc naturel — entretien quotidien des sentiers forestiers et du balisage en plein air"]},"semantic":{"concept":"outdoor-path-maintenance-main-duty","evidence":"park-trail-work-outdoors"}},{"number":19,"points":1,"passage":"","question":"Quelle annonce précise que l'employeur fournit un uniforme professionnel ?","options":["Offre 1","Offre 2","Offre 3","Offre 4"],"correct":"B","explanation":"L'offre 2 indique explicitement qu'une tenue de service est fournie.","section":"offers","media":{"kind":"offers","heading":"Offres d'emploi · Tenue professionnelle","items":["Librairie — tenue personnelle soignée recommandée, sans uniforme imposé","Hôtel — uniforme professionnel fourni et entretenu par l'employeur","Accueil municipal — tenue à acheter, remboursement après validation de la période d'essai","Atelier de cuisine — chaussures adaptées exigées, à apporter par le salarié"]},"semantic":{"concept":"uniform-issued-by-employer","evidence":"service-uniform-supplied"}},{"number":20,"points":1,"passage":"ÉVOLUTION DE LA FRÉQUENTATION DES ACTIVITÉS CULTURELLES\nLes quatre graphiques représentent des séries de cinq années. Choisissez celui qui correspond au commentaire.","question":"Quel graphique montre une baisse initiale, une période de stabilité, puis un retour au niveau de départ ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"A","explanation":"Le graphique 1 commence à 24, descend à 15, reste stable pendant trois années intermédiaires et revient à 24.","section":"charts","media":{"kind":"chart-grid","heading":"Inscriptions aux ateliers culturels","unit":"en milliers de personnes","years":["N−4","N−3","N−2","N−1","N"],"series":[[24,15,15,15,24],[12,18,13,25,20],[9,9,9,9,9],[12,19,28,17,8]]},"semantic":{"concept":"chart-dip-plateau-return-to-start","evidence":"drop-flat-then-baseline"}},{"number":21,"points":1,"passage":"PARTICIPATION AUX ACTIONS LOCALES\nComparez le début et la fin de chaque courbe, en tenant compte du creux intermédiaire.","question":"Quel graphique montre une baisse suivie d'une reprise qui dépasse nettement la valeur initiale ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"C","explanation":"La troisième courbe part de 23, chute à 10, puis monte progressivement jusqu'à 34, au-dessus du niveau initial.","section":"charts","media":{"kind":"chart-grid","heading":"Participants aux projets citoyens","unit":"en milliers de personnes","years":["N−4","N−3","N−2","N−1","N"],"series":[[10,14,18,21,25],[20,20,20,28,28],[23,10,17,26,34],[15,24,16,20,13]]},"semantic":{"concept":"chart-fall-rebound-above-baseline","evidence":"bottom-then-over-initial"}},{"number":22,"points":1,"passage":"FRÉQUENTATION DES STAGES\nLes variations indiquées sont comparées sur cinq années consécutives.","question":"Quel graphique illustre une baisse progressive puis un retour exact à la valeur de départ ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"B","explanation":"Le graphique 2 montre une diminution de 27 à 17, puis une progression jusqu'à 27, soit exactement la valeur initiale.","section":"charts","media":{"kind":"chart-grid","heading":"Participation aux stages en entreprise","unit":"en milliers de personnes","years":["N−4","N−3","N−2","N−1","N"],"series":[[10,10,10,10,16],[27,22,17,22,27],[11,15,20,25,25],[28,28,12,12,28]]},"semantic":{"concept":"chart-fall-recover-exact-baseline","evidence":"return-exact-to-start"}},{"number":23,"points":1,"passage":"Objet : Changement de dates de votre atelier\nMadame,\nÀ votre demande, nous avons recherché des places pour reporter l'atelier initialement prévu les 6 et 7 avril. Des places sont disponibles les 20 et 21 avril, au même tarif. Merci de confirmer ce nouveau créneau avant le 1er avril. Après cette date, toute modification devra être examinée selon les conditions générales, qui prévoient des frais dans certains cas.\nBien cordialement,\nService des inscriptions.","question":"Quelle proposition est faite à la cliente ?","options":["Un autre atelier soumis à des frais de dossier","Un report aux nouvelles dates sans supplément","Une session plus courte contre un avoir partiel","Une formation équivalente avec tarif préférentiel"],"correct":"B","explanation":"Le service propose les 20 et 21 avril au même tarif que le séjour initial.","section":"email","group":"Modification d'inscription","semantic":{"concept":"training-rescheduled-with-same-fee","evidence":"new-workshop-dates-no-price-change"}},{"number":24,"points":1,"passage":"Objet : Changement de dates de votre atelier\nMadame,\nÀ votre demande, nous avons recherché des places pour reporter l'atelier initialement prévu les 6 et 7 avril. Des places sont disponibles les 20 et 21 avril, au même tarif. Merci de confirmer ce nouveau créneau avant le 1er avril. Après cette date, toute modification devra être examinée selon les conditions générales, qui prévoient des frais dans certains cas.\nBien cordialement,\nService des inscriptions.","question":"Que se passera-t-il pour une modification demandée après le 1er avril ?","options":["Le report conservera son tarif sans nouvel examen","Toute demande tardive sera rejetée avant lecture","Une autre date sera attribuée sans condition","Les règles générales pourront entraîner des frais"],"correct":"D","explanation":"Après le 1er avril, les conditions générales s'appliquent et des frais sont possibles.","section":"email","group":"Modification d'inscription","semantic":{"concept":"training-changes-after-deadline-potential-fees","evidence":"late-changes-under-general-conditions"}},{"number":25,"points":1,"passage":"COMMUNIQUÉ MUNICIPAL — ATELIERS DE PRÉVENTION\nLa ville organise des séances gratuites pour apprendre à réagir aux risques domestiques. Elles s'adressent prioritairement aux familles de jeunes enfants et aux personnes âgées, mais restent ouvertes dans la limite des places disponibles. Les rencontres auront lieu du 3 au 12 juin à la Maison de quartier, sans inscription préalable. Les participants sont invités à apporter un document permettant de confirmer leur adresse.","question":"Comment peut-on participer aux séances ?","options":["Sur présentation d'une réservation au centre","Après une inscription en ligne à la mairie","En recevant une invitation avant la séance","En se présentant librement selon les places"],"correct":"D","explanation":"Les rencontres sont gratuites et organisées sans inscription préalable.","section":"email","group":"Prévention municipale","semantic":{"concept":"municipal-safety-free-dropin","evidence":"walkin-within-available-places"}},{"number":26,"points":1,"passage":"COMMUNIQUÉ MUNICIPAL — ATELIERS DE PRÉVENTION\nLa ville organise des séances gratuites pour apprendre à réagir aux risques domestiques. Elles s'adressent prioritairement aux familles de jeunes enfants et aux personnes âgées, mais restent ouvertes dans la limite des places disponibles. Les rencontres auront lieu du 3 au 12 juin à la Maison de quartier, sans inscription préalable. Les participants sont invités à apporter un document permettant de confirmer leur adresse.","question":"Quel document est conseillé aux participants ?","options":["Un justificatif permettant de confirmer leur domicile","Un document attestant du statut d'emploi des participants","Une attestation d'assurance du logement concerné","Une preuve d'inscription délivrée par le centre"],"correct":"A","explanation":"Le communiqué demande un document permettant de confirmer l'adresse des participants.","section":"email","group":"Prévention municipale","semantic":{"concept":"municipal-safety-proof-of-address","evidence":"bring-home-address-proof"}},{"number":27,"points":1,"passage":"Information importante — Sécurisation de votre espace client\nÀ compter du 15 septembre, la consultation des relevés et la modification de vos coordonnées exigeront une seconde vérification après la saisie du mot de passe. Un code sera envoyé sur le téléphone déjà associé à votre compte. Le tarif de votre abonnement et les modalités de règlement restent inchangés. Une démonstration est disponible sur le site du service.","question":"Quel aspect du service sera modifié ?","options":["Les montants facturés aux clients déjà abonnés","Le mode de vérification lors de la connexion","Le calendrier de transmission des relevés","La manière de mettre à jour son abonnement"],"correct":"B","explanation":"Une seconde vérification sera demandée lors de la connexion aux services concernés.","section":"email","group":"Sécurité du compte","semantic":{"concept":"banking-login-two-factor-only","evidence":"second-factor-password-unchanged"}},{"number":28,"points":1,"passage":"Information importante — Sécurisation de votre espace client\nÀ compter du 15 septembre, la consultation des relevés et la modification de vos coordonnées exigeront une seconde vérification après la saisie du mot de passe. Un code sera envoyé sur le téléphone déjà associé à votre compte. Le tarif de votre abonnement et les modalités de règlement restent inchangés. Une démonstration est disponible sur le site du service.","question":"Que faudra-t-il faire à partir du 15 septembre ?","options":["Valider l'accès avec un code reçu par téléphone","Créer un nouvel identifiant lors de chaque visite","Mettre à jour l'adresse postale avant chaque accès","Installer une autre application de facturation"],"correct":"A","explanation":"Le service enverra un code sur le téléphone associé au compte.","section":"email","group":"Sécurité du compte","semantic":{"concept":"banking-phone-code-not-new-fee","evidence":"code-sent-on-registered-phone"}},{"number":29,"points":1,"passage":"Avis de maintenance\nNotre accueil téléphonique sera suspendu le vendredi 4 novembre de 8 h à 16 h pour la mise à jour du logiciel de réservation. Le formulaire de contact et la messagerie électronique resteront accessibles pendant toute l'intervention. Les demandes reçues seront traitées à partir de 16 h. La ligne téléphonique rouvrira le lendemain selon les horaires habituels.","question":"Par quel moyen sera-t-il possible d'envoyer une demande vendredi à 10 h ?","options":["En laissant un message vocal au standard suspendu","En venant déposer une demande directement au guichet","En transmettant le formulaire ou un courriel","En sollicitant un rappel immédiat par téléphone"],"correct":"C","explanation":"Le formulaire de contact et le courriel restent disponibles pendant la suspension téléphonique.","section":"email","group":"Maintenance du service","semantic":{"concept":"phone-maintenance-email-contact-still-works","evidence":"form-and-email-during-outage"}},{"number":30,"points":1,"passage":"Avis de maintenance\nNotre accueil téléphonique sera suspendu le vendredi 4 novembre de 8 h à 16 h pour la mise à jour du logiciel de réservation. Le formulaire de contact et la messagerie électronique resteront accessibles pendant toute l'intervention. Les demandes reçues seront traitées à partir de 16 h. La ligne téléphonique rouvrira le lendemain selon les horaires habituels.","question":"Pourquoi l'accueil téléphonique sera-t-il suspendu ?","options":["À cause du remplacement des équipes d'accueil","Pour permettre la mise à jour de l'outil de réservation","En raison du transfert des appels vers une autre agence","Pour organiser une rencontre avec les usagers"],"correct":"B","explanation":"La suspension est liée à une mise à jour du logiciel de réservation.","section":"email","group":"Maintenance du service","semantic":{"concept":"phone-maintenance-booking-system-update","evidence":"reservation-software-update"}},{"number":31,"points":1,"passage":"Confirmation de formation\nBonjour Madame Martin,\nVotre inscription à la formation « Gestion de projets collaboratifs » a été acceptée. Les cours se tiendront du 5 au 9 décembre, de 9 h à 16 h, dans nos locaux au 18 avenue du Port. Votre entreprise finance la totalité de la formation. Pensez à apporter votre ordinateur et à nous confirmer votre présence avant le 25 novembre. Une attestation vous sera délivrée en fin de session.","question":"Qui prend en charge le coût de la formation ?","options":["Le centre de formation qui organise les séances","La personne inscrite, par versements successifs","Une caisse de financement propre à l'organisme","L'entreprise qui emploie la personne inscrite"],"correct":"D","explanation":"Le message précise que l'entreprise finance la totalité de la formation.","section":"email","group":"Formation professionnelle","semantic":{"concept":"employer-funds-training","evidence":"company-covers-whole-fee"}},{"number":32,"points":1,"passage":"Confirmation de formation\nBonjour Madame Martin,\nVotre inscription à la formation « Gestion de projets collaboratifs » a été acceptée. Les cours se tiendront du 5 au 9 décembre, de 9 h à 16 h, dans nos locaux au 18 avenue du Port. Votre entreprise finance la totalité de la formation. Pensez à apporter votre ordinateur et à nous confirmer votre présence avant le 25 novembre. Une attestation vous sera délivrée en fin de session.","question":"Quelle démarche est attendue avant le 25 novembre ?","options":["Transmettre ses pièces d'identité pour validation","Confirmer sa présence avant l'échéance annoncée","Préciser le matériel qu'elle compte emprunter","Régler la part de frais non prise en charge"],"correct":"B","explanation":"La participante doit confirmer sa présence avant le 25 novembre.","section":"email","group":"Formation professionnelle","semantic":{"concept":"training-attendance-confirmation-deadline","evidence":"attendance-confirm-before-november"}},{"number":33,"points":1,"passage":"TRAVAIL HYBRIDE : ORGANISER LA SOUPLESSE\nDe plus en plus d'organisations combinent présence au bureau et travail à distance. Cette organisation peut réduire les trajets et permettre de réserver certaines journées aux tâches qui demandent une concentration soutenue. Elle exige toutefois des règles communes pour coordonner les réunions et éviter que le travail ne déborde sur les soirées. Un même dispositif ne convient pas à tous les métiers : les postes de contact avec la clientèle demandent souvent une présence collective plus prévisible.\n\nUne enquête interne indique que les salariés apprécient de choisir certains jours de travail à domicile, mais que plusieurs d'entre eux peinent à couper les notifications après les heures habituelles. L'entreprise a d'abord envisagé de limiter les réunions à quelques créneaux fixes. Les responsables ont finalement proposé des plages de disponibilité communes et un droit explicite à la déconnexion, afin de préserver à la fois l'autonomie et les échanges nécessaires. Ils recommandent d'évaluer la qualité des résultats plutôt que de compter seulement les heures passées au bureau. Une difficulté demeure : les équipes dont les tâches sont très interdépendantes n'obtiennent pas forcément les mêmes gains que celles travaillant sur des projets autonomes.","question":"Pourquoi l'entreprise associe-t-elle souplesse des horaires et plages communes ?","options":["Pour remplacer la coordination par le suivi des heures","Pour bénéficier d'autonomie sans perdre les échanges indispensables","Pour imposer un emploi du temps identique à chaque métier","Pour réserver le travail à domicile aux postes sans clients"],"correct":"B","explanation":"Les plages partagées servent à organiser les échanges tout en maintenant une partie de la flexibilité.","section":"long","group":"Travail hybride","semantic":{"concept":"hybrid-work-structured-flexibility","evidence":"flexible-days-and-common-meeting-window"}},{"number":34,"points":1,"passage":"TRAVAIL HYBRIDE : ORGANISER LA SOUPLESSE\nDe plus en plus d'organisations combinent présence au bureau et travail à distance. Cette organisation peut réduire les trajets et permettre de réserver certaines journées aux tâches qui demandent une concentration soutenue. Elle exige toutefois des règles communes pour coordonner les réunions et éviter que le travail ne déborde sur les soirées. Un même dispositif ne convient pas à tous les métiers : les postes de contact avec la clientèle demandent souvent une présence collective plus prévisible.\n\nUne enquête interne indique que les salariés apprécient de choisir certains jours de travail à domicile, mais que plusieurs d'entre eux peinent à couper les notifications après les heures habituelles. L'entreprise a d'abord envisagé de limiter les réunions à quelques créneaux fixes. Les responsables ont finalement proposé des plages de disponibilité communes et un droit explicite à la déconnexion, afin de préserver à la fois l'autonomie et les échanges nécessaires. Ils recommandent d'évaluer la qualité des résultats plutôt que de compter seulement les heures passées au bureau. Une difficulté demeure : les équipes dont les tâches sont très interdépendantes n'obtiennent pas forcément les mêmes gains que celles travaillant sur des projets autonomes.","question":"Quelle limite du travail hybride les nouvelles règles cherchent-elles surtout à prévenir ?","options":["Le manque d'évaluation de la qualité des projets","La difficulté à réserver des bureaux individuels","La disponibilité professionnelle attendue après les horaires","Le temps nécessaire pour parcourir les trajets domicile-travail"],"correct":"C","explanation":"Le droit à la déconnexion vise à limiter les sollicitations et notifications tardives.","section":"long","group":"Travail hybride","semantic":{"concept":"hybrid-work-after-hours-disconnection","evidence":"notifications-after-hours"}},{"number":35,"points":1,"passage":"LES ATELIERS DE RÉPARATION SOLIDAIRES\nDans plusieurs quartiers, des ateliers associatifs invitent les habitants à réparer un petit appareil plutôt que de le jeter. Les bénévoles ne travaillent pas à la place du propriétaire : ils lui prêtent des outils et l'accompagnent dans le diagnostic. Cette démarche prend souvent plus de temps qu'une réparation effectuée directement par un professionnel. Les organisateurs considèrent toutefois que l'apprentissage d'un geste technique peut rendre les participants plus autonomes lors d'une panne future.\n\nLes dons servent à acheter des pièces et à renouveler les outils communs. L'association ne garantit pas la remise en état de tous les appareils ; elle préfère expliquer les limites de l'intervention. Certaines pannes électriques exigent notamment l'avis d'un spécialiste, car l'utilisation d'un appareil mal réparé présente un risque. Les animateurs cherchent aussi à favoriser des rencontres entre voisins de générations et d'expériences différentes. Leur bilan ne comptabilise donc pas uniquement les appareils remis en service, mais aussi les participants ayant appris à identifier une panne simple ou à reconnaître une situation nécessitant un professionnel.","question":"Pourquoi les bénévoles laissent-ils les habitants participer eux-mêmes à la réparation ?","options":["Pour rendre la réparation systématiquement plus rapide","Pour remplacer progressivement les professionnels du quartier","Pour transmettre des compétences et favoriser l'autonomie","Pour réserver les outils aux bénévoles expérimentés"],"correct":"C","explanation":"Le but est l'apprentissage et l'autonomie, pas seulement la remise en marche de l'appareil.","section":"long","group":"Réparation solidaire","semantic":{"concept":"repair-cafe-community-guided-learning","evidence":"learner-repairs-with-volunteers"}},{"number":36,"points":1,"passage":"LES ATELIERS DE RÉPARATION SOLIDAIRES\nDans plusieurs quartiers, des ateliers associatifs invitent les habitants à réparer un petit appareil plutôt que de le jeter. Les bénévoles ne travaillent pas à la place du propriétaire : ils lui prêtent des outils et l'accompagnent dans le diagnostic. Cette démarche prend souvent plus de temps qu'une réparation effectuée directement par un professionnel. Les organisateurs considèrent toutefois que l'apprentissage d'un geste technique peut rendre les participants plus autonomes lors d'une panne future.\n\nLes dons servent à acheter des pièces et à renouveler les outils communs. L'association ne garantit pas la remise en état de tous les appareils ; elle préfère expliquer les limites de l'intervention. Certaines pannes électriques exigent notamment l'avis d'un spécialiste, car l'utilisation d'un appareil mal réparé présente un risque. Les animateurs cherchent aussi à favoriser des rencontres entre voisins de générations et d'expériences différentes. Leur bilan ne comptabilise donc pas uniquement les appareils remis en service, mais aussi les participants ayant appris à identifier une panne simple ou à reconnaître une situation nécessitant un professionnel.","question":"Quelle source permet de renouveler les outils et de financer certaines pièces ?","options":["Les contributions volontaires reçues par l'association","Les abonnements prélevés sur chaque propriétaire","Les remboursements imposés aux fabricants d'appareils","Les recettes commerciales de vente d'équipements"],"correct":"A","explanation":"Les dons financent explicitement l'achat des pièces et le renouvellement du matériel.","section":"long","group":"Réparation solidaire","semantic":{"concept":"repair-cafe-voluntary-donation-equipment","evidence":"donations-buy-parts-and-tools"}},{"number":37,"points":1,"passage":"LE RENOUVEAU DES HALLES DE QUARTIER\nAprès plusieurs années de déclin, certaines petites halles alimentaires attirent de nouveaux habitants. Les acheteurs y trouvent des produits de saison et peuvent demander directement aux commerçants des précisions sur leur provenance. Cette relation intéresse les personnes qui souhaitent mieux comprendre leur alimentation, mais elle ne garantit pas que tous les produits soient moins chers qu'en grande surface. Les commerçants défendent plutôt une meilleure information et la possibilité d'adapter leurs achats aux arrivages.\n\nPour soutenir ces lieux, des municipalités rénovent les bâtiments, facilitent l'installation de jeunes producteurs et rendent les horaires d'ouverture plus lisibles. Les vendeurs restent néanmoins soumis à la hausse des coûts de transport, aux exigences de conservation et à la concurrence de la livraison rapide. La fréquentation en progression ne signifie donc pas automatiquement que chaque stand est rentable. Des gestionnaires envisagent de partager certains frais de stockage, mais tous les commerçants n'acceptent pas de mutualiser leurs activités. Les responsables municipaux indiquent qu'un soutien durable ne peut se limiter à la rénovation d'un bâtiment : il doit être accompagné d'une offre suffisamment attractive pour les habitants.","question":"Quel facteur contribue le plus à l'intérêt renouvelé pour les halles ?","options":["La possibilité de comparer uniquement des produits importés","La garantie de tarifs inférieurs à ceux de la grande distribution","Le remplacement des commerces par une livraison plus rapide","Les échanges directs sur l'origine et la qualité des produits"],"correct":"D","explanation":"Les consommateurs recherchent notamment la relation directe avec les vendeurs et l'information sur la provenance.","section":"long","group":"Halles de quartier","semantic":{"concept":"local-food-halls-direct-sourcing","evidence":"producer-dialogue-provenance"}},{"number":38,"points":1,"passage":"LE RENOUVEAU DES HALLES DE QUARTIER\nAprès plusieurs années de déclin, certaines petites halles alimentaires attirent de nouveaux habitants. Les acheteurs y trouvent des produits de saison et peuvent demander directement aux commerçants des précisions sur leur provenance. Cette relation intéresse les personnes qui souhaitent mieux comprendre leur alimentation, mais elle ne garantit pas que tous les produits soient moins chers qu'en grande surface. Les commerçants défendent plutôt une meilleure information et la possibilité d'adapter leurs achats aux arrivages.\n\nPour soutenir ces lieux, des municipalités rénovent les bâtiments, facilitent l'installation de jeunes producteurs et rendent les horaires d'ouverture plus lisibles. Les vendeurs restent néanmoins soumis à la hausse des coûts de transport, aux exigences de conservation et à la concurrence de la livraison rapide. La fréquentation en progression ne signifie donc pas automatiquement que chaque stand est rentable. Des gestionnaires envisagent de partager certains frais de stockage, mais tous les commerçants n'acceptent pas de mutualiser leurs activités. Les responsables municipaux indiquent qu'un soutien durable ne peut se limiter à la rénovation d'un bâtiment : il doit être accompagné d'une offre suffisamment attractive pour les habitants.","question":"Quelle mesure municipale est explicitement décrite ?","options":["Rénover les locaux et faciliter l'installation de producteurs","Prendre en charge toutes les dépenses liées au stockage","Obliger l'ensemble des stands à partager leur activité","Imposer un même prix pour chaque produit de saison"],"correct":"A","explanation":"La rénovation et la simplification de l'installation sont citées parmi les actions municipales.","section":"long","group":"Halles de quartier","semantic":{"concept":"local-food-halls-municipal-building-support","evidence":"renovation-and-easier-installation"}},{"number":39,"points":1,"passage":"DES SÉJOURS D'APPRENTISSAGE À LA CAMPAGNE\nCertaines familles passent quelques jours dans une exploitation agricole pour comprendre comment sont produits les aliments. Les enfants peuvent nourrir les animaux, observer la préparation du pain ou participer à des récoltes adaptées à leur âge. Les hôtes expliquent les étapes de leur travail et les contraintes liées aux saisons. Contrairement à une visite de ferme limitée à quelques heures, le séjour permet d'observer les activités à plusieurs moments de la journée.\n\nCe tourisme apporte un complément de revenu aux exploitants, mais il demande aussi du temps d'accueil et une organisation des activités. Les programmes affichés restent parfois sujets à modification : la pluie peut retarder une récolte, et certains soins aux animaux doivent primer sur les animations prévues. Plusieurs familles apprécient justement cette souplesse, à condition qu'elle ait été annoncée clairement. D'autres regrettent l'absence d'équipements comparables à ceux d'un hôtel. Les exploitants rappellent que le séjour ne vise pas à reproduire les services d'un établissement touristique classique ; il propose une participation encadrée à une activité agricole réelle, avec ses horaires et ses imprévus.","question":"Quel apprentissage ces séjours peuvent-ils apporter aux enfants ?","options":["Une formation théorique réservée aux futurs agriculteurs","Une initiation à la gestion financière d'un établissement","Une observation concrète du travail dans une exploitation","Un enseignement scolaire sans participation à la ferme"],"correct":"C","explanation":"La participation à certaines tâches et l'observation du quotidien rendent le travail agricole concret.","section":"long","group":"Séjours à la campagne","semantic":{"concept":"farm-stay-child-learning-experience","evidence":"age-adapted-farm-tasks"}},{"number":40,"points":1,"passage":"DES SÉJOURS D'APPRENTISSAGE À LA CAMPAGNE\nCertaines familles passent quelques jours dans une exploitation agricole pour comprendre comment sont produits les aliments. Les enfants peuvent nourrir les animaux, observer la préparation du pain ou participer à des récoltes adaptées à leur âge. Les hôtes expliquent les étapes de leur travail et les contraintes liées aux saisons. Contrairement à une visite de ferme limitée à quelques heures, le séjour permet d'observer les activités à plusieurs moments de la journée.\n\nCe tourisme apporte un complément de revenu aux exploitants, mais il demande aussi du temps d'accueil et une organisation des activités. Les programmes affichés restent parfois sujets à modification : la pluie peut retarder une récolte, et certains soins aux animaux doivent primer sur les animations prévues. Plusieurs familles apprécient justement cette souplesse, à condition qu'elle ait été annoncée clairement. D'autres regrettent l'absence d'équipements comparables à ceux d'un hôtel. Les exploitants rappellent que le séjour ne vise pas à reproduire les services d'un établissement touristique classique ; il propose une participation encadrée à une activité agricole réelle, avec ses horaires et ses imprévus.","question":"Pourquoi des familles apprécient-elles le séjour malgré les changements possibles du programme ?","options":["Elles s'attendent à retrouver les équipements d'un grand hôtel","Elles souhaitent suivre un itinéraire fixé sans imprévus","Elles privilégient les animations garanties par tous les temps","Elles recherchent une immersion dans la vie agricole réelle"],"correct":"D","explanation":"L'intérêt réside dans l'expérience rurale authentique, y compris avec les contraintes de la météo et du travail.","section":"long","group":"Séjours à la campagne","semantic":{"concept":"farm-stay-rural-reality-over-hotel","evidence":"authentic-farm-routine-weather"}}]}$bank1$::jsonb;
 if exists(select 1 from academy_tef_reading.papers where id='tef-reading-01' and version='tef-reading-2026-11-original-01-v2' and content<>paper) then raise exception 'Cannot modify published TEF Reading paper version tef-reading-01';end if;
 insert into academy_tef_reading.papers(id,version,content) values('tef-reading-01','tef-reading-2026-11-original-01-v2',paper) on conflict do nothing;

 paper := $bank2${"id":"tef-reading-02","version":"tef-reading-2026-11-original-02-v2","title":"TEF Canada · Compréhension écrite · Test 02","seconds":3600,"maxPoints":40,"questions":[{"number":1,"points":1,"passage":"📖 BIBLIOTHÈQUE ITINÉRANTE\nEn raison du marché de quartier, l'arrêt du bibliobus prévu place des Tilleuls mercredi est déplacé devant la mairie. Les horaires restent de 14 h à 17 h. Les retours de documents sont acceptés aux deux endroits uniquement lors des permanences habituelles.","question":"Où faut-il se rendre pour emprunter un livre mercredi ?","explanation":"Le prêt du mercredi se déroule devant la mairie et les heures ne changent pas.","media":{"kind":"notice","icon":"📚","heading":"Bibliobus · changement d'arrêt","accent":"#1e5e97"},"options":["Au point de départ habituel de la place des Tilleuls","Devant la mairie pendant le créneau de l'après-midi","À l'intérieur de la bibliothèque centrale le matin","Au marché, près des commerçants, avant son ouverture"],"correct":"B","semantic":{"concept":"bibliobus-market-relocated-stop","evidence":"change-from-market-square-to-city-hall"}},{"number":2,"points":1,"passage":"🚧 AVIS AUX RIVERAINS\nLa rue du Puits sera interdite à la circulation automobile vendredi de 8 h à 18 h. Les piétons pourront traverser la zone, tandis que les livraisons des commerces seront assurées par l'accès nord jusqu'à midi.","question":"Quelle disposition concerne les commerces ?","explanation":"L'accès nord demeure ouvert aux livraisons jusqu'à midi, malgré la fermeture aux voitures.","media":{"kind":"notice","icon":"🚚","heading":"Travaux · accès aménagé","accent":"#c58021"},"options":["Les magasins devront faire effectuer leurs livraisons jeudi","Leurs fournisseurs devront attendre la fin du chantier","Leurs clients auront accès à un parking réservé","Leurs livraisons pourront passer par le nord jusqu'à midi"],"correct":"D","semantic":{"concept":"street-work-commercial-delivery-north-access","evidence":"deliveries-north-entrance-until-midday"}},{"number":3,"points":1,"passage":"🎟️ CENTRE CULTUREL DES HALLES\nPour les spectacles de vendredi, les billets achetés en ligne doivent être échangés contre un ticket d'entrée à l'accueil. Le comptoir ouvre une heure avant la représentation. Les billets achetés sur place n'exigent aucune démarche supplémentaire.","question":"Que doivent faire les spectateurs ayant réservé sur Internet ?","explanation":"Les achats en ligne doivent être échangés au comptoir dès son ouverture.","media":{"kind":"notice","icon":"🎭","heading":"Billetterie · information","accent":"#7b4baa"},"options":["Échanger leur justificatif en billet d'entrée à l'accueil","Imprimer une réservation de remplacement après la séance","Réserver un créneau de contrôle par téléphone la veille","Régler le supplément d'une seconde place à l'accueil"],"correct":"A","semantic":{"concept":"web-bought-ticket-exchanged-for-entry","evidence":"online-ticket-counter-exchange"}},{"number":4,"points":1,"passage":"🎻 INSTRUMENTOTHÈQUE\nLa maison de la musique prête des instruments aux élèves inscrits pendant six semaines. Une caution est versée au retrait et restituée si l'instrument revient en bon état. L'entretien normal est pris en charge par l'association, tandis que les réparations dues à une mauvaise utilisation restent à la charge de l'emprunteur.","question":"Quelle dépense peut rester à la charge de l'emprunteur ?","explanation":"L'association prend en charge l'entretien normal, mais pas les dommages dus à une mauvaise utilisation.","media":{"kind":"notice","icon":"🎻","heading":"Prêt d'instruments · conditions","accent":"#9a6d38"},"options":["La révision normale pendant la période de prêt","Le réglage périodique réalisé par l'association","Une réparation résultant d'un usage inapproprié","Le contrôle de l'état de l'instrument au retour"],"correct":"C","semantic":{"concept":"musical-instrument-loan-damage-billing","evidence":"accidental-damage-repair-charge"}},{"number":5,"points":1,"passage":"🎶 FESTIVAL DU QUARTIER\nLes concerts de samedi auront lieu dans le jardin municipal si la météo le permet. En cas de fortes pluies, les mêmes artistes joueront à la salle des Fêtes. Le programme et les horaires seront maintenus ; seul le lieu sera modifié.","question":"Qu'est-ce qui pourrait changer si les intempéries se confirment ?","explanation":"En cas de fortes pluies, les concerts sont déplacés en salle, sans changement d'horaires.","media":{"kind":"illustration","scene":"festival","heading":"Festival de quartier"},"options":["Le programme sera limité à un concert au lieu de deux","Les représentations seront décalées au dimanche suivant","Les spectacles auront lieu dans un bâtiment plutôt qu'au jardin","Les horaires seront raccourcis pour éviter la pluie"],"correct":"C","semantic":{"concept":"outdoor-festival-indoor-rain-alternative","evidence":"rain-switch-location-same-times"}},{"number":6,"points":1,"passage":"♻️ CONSIGNE DE BOÎTES REPAS\nDans les restaurants participants, une boîte réutilisable est remise contre un dépôt de 5 €. Elle peut être rapportée dans n'importe quel restaurant du réseau, qui restitue immédiatement le dépôt, même si la boîte vient d'un autre établissement.","question":"Comment récupérer le dépôt versé ?","explanation":"L'annonce autorise les retours auprès de tous les partenaires du réseau.","media":{"kind":"notice","icon":"🥡","heading":"Boîtes réutilisables · consigne","accent":"#28896c"},"options":["Restituer la boîte à un restaurant du même réseau","Rapporter la boîte uniquement à son point d'achat","Conserver la boîte pour trois consommations successives","Remettre le reçu à la mairie avant le remboursement"],"correct":"A","semantic":{"concept":"reuse-box-return-networkwide-deposit","evidence":"any-member-restaurant-refunds-deposit"}},{"number":7,"points":1,"passage":"🩺 MAISON DE SANTÉ\nLes consultations du lundi matin sont désormais réservées aux patients orientés par un professionnel de santé. Pour une consultation ordinaire, les rendez-vous restent disponibles du lundi après-midi au vendredi. Les urgences vitales ne sont pas prises en charge sur place.","question":"Quelle demande peut être satisfaite le lundi après-midi ?","explanation":"Les rendez-vous habituels restent possibles à partir du lundi après-midi.","media":{"kind":"notice","icon":"🩺","heading":"Horaires de consultation","accent":"#1c8392"},"options":["Une urgence vitale nécessitant des soins immédiats","Une consultation matinale sans orientation préalable","Un examen urgent réalisé sans rendez-vous","Une consultation habituelle réservée pour l'après-midi"],"correct":"D","semantic":{"concept":"clinic-afternoon-routine-appointments","evidence":"routine-monday-pm-not-emergency"}},{"number":8,"points":1,"passage":"La direction a promis de ________ sa décision jusqu'à la fin de la concertation, afin de prendre en compte les propositions des habitants.","question":"Quel verbe complète logiquement cette phrase ?","explanation":"Différer une décision signifie en repousser le moment afin d'attendre d'autres éléments.","section":"cloze","options":["maintenir","différer","présenter","préciser"],"correct":"B","semantic":{"concept":"defer-decision-after-consultation","evidence":"postpone-until-community-feedback"}},{"number":9,"points":1,"passage":"Pour bénéficier du tarif réduit, le visiteur doit présenter un justificatif ________ à la date de sa visite.","question":"Quel adjectif convient le mieux ?","explanation":"Un justificatif doit être valable au moment de la visite, pas simplement disponible.","section":"cloze","options":["valable","authentique","disponible","préparatoire"],"correct":"A","semantic":{"concept":"valid-id-at-visit-time","evidence":"proof-valid-at-time"}},{"number":10,"points":1,"passage":"Bien que les travaux ________ terminés, le passage restera interdit jusqu'au contrôle de sécurité.","question":"Quelle forme verbale faut-il employer ?","explanation":"Après « bien que », le subjonctif présent « soient » convient.","section":"cloze","options":["sont","seront","étaient","soient"],"correct":"D","semantic":{"concept":"although-subjunctive-agreement","evidence":"bien-que-soient"}},{"number":11,"points":1,"passage":"Le conseil a adopté une mesure ________ qui sera réexaminée au bout de six mois.","question":"Quel adjectif correspond à cette limitation dans le temps ?","explanation":"Une mesure provisoire s'applique temporairement, avant réexamen.","section":"cloze","options":["progressive","provisoire","conditionnelle","préparatoire"],"correct":"B","semantic":{"concept":"provisional-temporary-measure","evidence":"review-after-six-months"}},{"number":12,"points":1,"passage":"ARCHIVES MUNICIPALES\nAvant d'ouvrir la collection au public, les archivistes doivent ________ (1) les documents les plus fragiles. Une fois les fichiers créés, les chercheurs pourront les ________ (2) sans manipuler les originaux.","question":"Quel verbe convient à l'espace (1) ?","explanation":"La création de fichiers consultables suppose de numériser les originaux.","section":"paired-cloze","group":"Archives municipales","options":["inventorier","transporter","numériser","restaurer"],"correct":"C","semantic":{"concept":"archive-fragile-original-digitization","evidence":"digitize-fragile-records"}},{"number":13,"points":1,"passage":"ARCHIVES MUNICIPALES\nAvant d'ouvrir la collection au public, les archivistes doivent ________ (1) les documents les plus fragiles. Une fois les fichiers créés, les chercheurs pourront les ________ (2) sans manipuler les originaux.","question":"Quel verbe convient à l'espace (2) ?","explanation":"L'objectif est de permettre la consultation numérique plutôt que la manipulation des documents.","section":"paired-cloze","group":"Archives municipales","options":["modifier","authentifier","reproduire","consulter"],"correct":"D","semantic":{"concept":"archive-files-online-consultation","evidence":"consult-files-not-originals"}},{"number":14,"points":1,"passage":"FÊTE DES VOISINS\nL'équipe organisatrice invite les habitants à ________ (1) leurs idées d'activités avant le 5 juin. Elle répartira ensuite les tâches entre bénévoles pour ________ (2) les préparatifs.","question":"Quel verbe convient à l'espace (1) ?","explanation":"Les habitants sont invités à proposer leurs idées, c'est-à-dire à les soumettre.","section":"paired-cloze","group":"Fête des voisins","options":["diffuser","défendre","soumettre","archiver"],"correct":"C","semantic":{"concept":"neighbors-propose-activity-ideas","evidence":"residents-send-suggestions"}},{"number":15,"points":1,"passage":"FÊTE DES VOISINS\nL'équipe organisatrice invite les habitants à ________ (1) leurs idées d'activités avant le 5 juin. Elle répartira ensuite les tâches entre bénévoles pour ________ (2) les préparatifs.","question":"Quel verbe convient à l'espace (2) ?","explanation":"La répartition des tâches sert à coordonner le travail des bénévoles.","section":"paired-cloze","group":"Fête des voisins","options":["accélérer","coordonner","contrôler","réserver"],"correct":"B","semantic":{"concept":"volunteers-coordinate-tasks","evidence":"allocate-volunteer-work"}},{"number":16,"points":1,"passage":"RESTAURATION COLLECTIVE\nPour éviter les surplus, la cantine demande aux élèves d'indiquer leur présence la veille. Elle peut ainsi ________ (1) le nombre de portions préparées, puis ________ (2) les produits non utilisés à une association partenaire.","question":"Quel verbe convient à l'espace (1) ?","explanation":"Connaître la fréquentation à l'avance permet d'ajuster la quantité préparée.","section":"paired-cloze","group":"Cantine solidaire","options":["ajuster","augmenter","évaluer","prévoir"],"correct":"A","semantic":{"concept":"canteen-adjust-portion-count","evidence":"portion-count-based-on-attendance"}},{"number":17,"points":1,"passage":"RESTAURATION COLLECTIVE\nPour éviter les surplus, la cantine demande aux élèves d'indiquer leur présence la veille. Elle peut ainsi ________ (1) le nombre de portions préparées, puis ________ (2) les produits non utilisés à une association partenaire.","question":"Quel verbe convient à l'espace (2) ?","explanation":"La cantine remet les produits restants à l'association, sans contrepartie.","section":"paired-cloze","group":"Cantine solidaire","options":["facturer","donner","restituer","commander"],"correct":"B","semantic":{"concept":"canteen-donate-surplus-food","evidence":"surplus-sent-to-partner-group"}},{"number":18,"points":1,"passage":"","question":"Quelle annonce conviendrait à une personne qui n'est libre que le samedi et souhaite acquérir une première expérience rémunérée ?","explanation":"L'offre 3 propose explicitement des samedis rémunérés avec accompagnement des débutants.","section":"offers","media":{"kind":"offers","heading":"Petits emplois · Disponibilité et expérience","items":["Cinéma local — accueil rémunéré le samedi, maîtrise préalable d'un logiciel de billetterie","Association sportive — accompagnement le samedi, bénévolat et formation assurée","Marché couvert — aide rémunérée chaque samedi, initiation et accompagnement des débutants","Atelier de design — accueil rémunéré samedi et dimanche, expérience requise"]},"options":["Offre 1","Offre 2","Offre 3","Offre 4"],"correct":"C","semantic":{"concept":"paid-saturday-beginner-market-job","evidence":"paid-saturday-training-included"}},{"number":19,"points":1,"passage":"","question":"Quel poste correspond à une personne sans permis de conduire, expérimentée dans l'accueil du public, qui souhaite travailler en semaine ?","explanation":"L'offre 2 exige l'accueil du public, accepte les déplacements en transport en commun et se déroule du lundi au vendredi.","section":"offers","media":{"kind":"offers","heading":"Offres d'emploi · Conditions de recrutement","items":["Livraison de repas — tournée du lundi au vendredi, permis B indispensable, contact client fréquent.","Maison des associations — accueil au guichet du lundi au vendredi, expérience demandée ; accès en transport collectif.","Office de tourisme itinérant — accueil et déplacements entre sites, permis B exigé ; travail le week-end.","Accueil d'événements — expérience de billetterie appréciée, missions surtout les samedis et dimanches."]},"options":["Offre 2","Offre 1","Offre 3","Offre 4"],"correct":"A","semantic":{"concept":"weekdays-frontdesk-no-drivers-license","evidence":"weekday-counter-public-transit"}},{"number":20,"points":1,"passage":"SUIVI DES INSCRIPTIONS\nObservez les tendances annuelles de ces quatre séries.","question":"Quel graphique présente une augmentation régulière jusqu'à l'avant-dernière année, suivie d'un léger recul, tout en restant au-dessus du niveau initial ?","explanation":"La première série évolue de 12 à 22 de manière continue, puis descend légèrement à 20.","section":"charts","media":{"kind":"chart-grid","heading":"Effectifs des ateliers","unit":"en centaines d'inscriptions","years":["2019","2020","2021","2022","2023"],"series":[[12,14,18,22,20],[11,20,12,23,18],[23,21,19,16,14],[10,10,16,13,13]]},"options":["Graphique 2","Graphique 3","Graphique 4","Graphique 1"],"correct":"D","semantic":{"concept":"chart-steady-rising-then-last-slip","evidence":"rise-to-penultimate-then-dip"}},{"number":21,"points":1,"passage":"ÉVOLUTION DES VISITES\nLes graphiques retracent cinq observations successives.","question":"Quel graphique indique deux baisses consécutives, puis une reprise sur les deux dernières périodes jusqu'au-dessus du niveau de départ ?","explanation":"La troisième série suit 24, 16, 10, 19, 28 : deux replis suivis de deux hausses.","section":"charts","media":{"kind":"chart-grid","heading":"Fréquentation des lieux patrimoniaux","unit":"en milliers de visites","years":["2018","2019","2020","2021","2022"],"series":[[25,10,15,18,24],[15,20,14,16,20],[24,16,10,19,28],[18,20,19,21,20]]},"options":["Graphique 3","Graphique 1","Graphique 2","Graphique 4"],"correct":"A","semantic":{"concept":"chart-two-falls-then-two-rises-above-start","evidence":"trough-then-recovery-twice"}},{"number":22,"points":1,"passage":"COMPARAISON DES CONSOMMATIONS\nChaque courbe rassemble cinq mesures successives.","question":"Quel graphique revient précisément à son niveau de départ, après des variations importantes et sans deux valeurs successives identiques ?","explanation":"La deuxième série part de 20 et finit à 20, après des fluctuations 28, 11 et 26, sans plateau.","section":"charts","media":{"kind":"chart-grid","heading":"Consommation annuelle","unit":"en unités comparables","years":["A1","A2","A3","A4","A5"],"series":[[14,18,20,24,27],[20,28,11,26,20],[19,22,17,21,23],[12,12,25,12,12]]},"options":["Graphique 1","Graphique 3","Graphique 2","Graphique 4"],"correct":"C","semantic":{"concept":"chart-high-variation-return-to-origin","evidence":"same-start-end-intervening-fluctuations"}},{"number":23,"points":1,"passage":"Objet : Objet retrouvé après le concert\nBonjour,\nNous avons retrouvé le sac correspondant à votre signalement. Vous pourrez le récupérer mercredi ou vendredi entre 14 h et 18 h au guichet des objets trouvés, sur présentation d'une pièce d'identité. Si vous souhaitez confier le retrait à une autre personne, celle-ci devra apporter une autorisation signée et une copie de votre document d'identité. Nous ne proposons pas d'expédition postale. Les objets non récupérés dans les trente jours suivant la notification sont transmis à une association partenaire. Merci de nous indiquer si vous prévoyez un retrait.\nCordialement,\nService des objets trouvés.","question":"À quelle condition une autre personne peut-elle récupérer le sac ?","explanation":"Un retrait par procuration nécessite une autorisation signée et une copie du document du propriétaire.","section":"email","group":"Objet retrouvé","options":["En indiquant verbalement le nom de son propriétaire","En présentant seulement son propre justificatif d'identité","En apportant le billet d'entrée du concert","En fournissant une autorisation signée et un justificatif"],"correct":"D","semantic":{"concept":"lost-property-thirdparty-signed-permission","evidence":"proxy-needs-signed-authority-and-id"}},{"number":24,"points":1,"passage":"Objet : Objet retrouvé après le concert\nBonjour,\nNous avons retrouvé le sac correspondant à votre signalement. Vous pourrez le récupérer mercredi ou vendredi entre 14 h et 18 h au guichet des objets trouvés, sur présentation d'une pièce d'identité. Si vous souhaitez confier le retrait à une autre personne, celle-ci devra apporter une autorisation signée et une copie de votre document d'identité. Nous ne proposons pas d'expédition postale. Les objets non récupérés dans les trente jours suivant la notification sont transmis à une association partenaire. Merci de nous indiquer si vous prévoyez un retrait.\nCordialement,\nService des objets trouvés.","question":"Qu'adviendra-t-il du sac s'il n'est pas retiré dans le délai annoncé ?","explanation":"Le service remet les objets non réclamés dans les trente jours à une association.","section":"email","group":"Objet retrouvé","options":["Il sera expédié à l'adresse fournie lors du signalement","Il pourra être transmis à une association partenaire","Il restera en dépôt jusqu'à la fin de l'année","Il sera remis directement à la salle de concert"],"correct":"B","semantic":{"concept":"lost-property-unclaimed-donation-window","evidence":"unclaimed-after-thirty-days-donated"}},{"number":25,"points":1,"passage":"Note aux résidents — Collecte des biodéchets\nÀ compter du mois prochain, des bacs marron seront installés au pied des immeubles. Ils accueilleront les épluchures, le marc de café et les restes végétaux, mais pas les emballages, même présentés comme compostables. Les gardiens distribueront des petits contenants à chaque foyer. Pendant les trois premières semaines, des agents seront présents deux soirs par semaine pour répondre aux questions. La ville évaluera les erreurs de tri avant d'étendre le dispositif à d'autres quartiers.","question":"Pourquoi des agents seront-ils présents au démarrage ?","explanation":"Les agents seront là pour répondre aux questions pendant la phase de lancement.","section":"email","group":"Tri des biodéchets","options":["Pour contrôler le contenu individuel de chaque bac","Pour récupérer les déchets dans les appartements","Pour guider les résidents dans les nouvelles consignes","Pour remplacer les gardiens lors de la distribution"],"correct":"C","semantic":{"concept":"food-waste-collection-launch-educators","evidence":"staff-explain-sorting"}},{"number":26,"points":1,"passage":"Note aux résidents — Collecte des biodéchets\nÀ compter du mois prochain, des bacs marron seront installés au pied des immeubles. Ils accueilleront les épluchures, le marc de café et les restes végétaux, mais pas les emballages, même présentés comme compostables. Les gardiens distribueront des petits contenants à chaque foyer. Pendant les trois premières semaines, des agents seront présents deux soirs par semaine pour répondre aux questions. La ville évaluera les erreurs de tri avant d'étendre le dispositif à d'autres quartiers.","question":"Quelle décision dépendra de la première phase ?","explanation":"La municipalité évaluera les erreurs avant de décider de l'extension du programme.","section":"email","group":"Tri des biodéchets","options":["La fréquence de collecte dans les immeubles existants","Le maintien des horaires des agents municipaux","Le prix des contenants remis aux foyers","La possible extension du tri à de nouveaux quartiers"],"correct":"D","semantic":{"concept":"food-waste-evaluate-pilot-expansion","evidence":"expand-after-error-measurement"}},{"number":27,"points":1,"passage":"Objet : Votre participation au stage de photographie\nMadame,\nNous avons bien reçu votre acompte pour le stage du 12 au 14 octobre. Les séances pratiques auront lieu en extérieur, y compris en cas de pluie légère ; prévoyez une protection pour votre matériel. Si une alerte météorologique empêche les prises de vue, une séance en studio remplacera la sortie concernée. L'acompte reste déductible du prix final. Pour toute annulation à votre initiative après le 1er octobre, il ne pourra être remboursé que si une personne sur liste d'attente reprend votre place.\nL'organisateur.","question":"Quelle adaptation est prévue en cas de conditions dangereuses ?","explanation":"Le studio remplace la sortie si l'alerte météo rend la prise de vue extérieure impossible.","section":"email","group":"Stage de photographie","options":["Le report de la totalité du séjour à la saison suivante","Le remplacement d'une sortie par une séance intérieure","La réduction des journées pratiques sans compensation","Le déplacement de la séance vers un autre site extérieur"],"correct":"B","semantic":{"concept":"photo-course-weather-studio-alternative","evidence":"warning-weather-moves-inside"}},{"number":28,"points":1,"passage":"Objet : Votre participation au stage de photographie\nMadame,\nNous avons bien reçu votre acompte pour le stage du 12 au 14 octobre. Les séances pratiques auront lieu en extérieur, y compris en cas de pluie légère ; prévoyez une protection pour votre matériel. Si une alerte météorologique empêche les prises de vue, une séance en studio remplacera la sortie concernée. L'acompte reste déductible du prix final. Pour toute annulation à votre initiative après le 1er octobre, il ne pourra être remboursé que si une personne sur liste d'attente reprend votre place.\nL'organisateur.","question":"À quelle condition l'acompte pourrait-il être rendu après le 1er octobre ?","explanation":"Après le 1er octobre, le remboursement dépend du remplacement du participant.","section":"email","group":"Stage de photographie","options":["Si un autre participant reprend la place devenue libre","Si l'inscrit dépose sa demande quelques jours plus tard","Si la pluie impose une séance supplémentaire en studio","Si le stage choisit un autre appareil photo"],"correct":"A","semantic":{"concept":"photo-course-refund-if-waitlist-replacement","evidence":"refund-conditional-on-filling-spot"}},{"number":29,"points":1,"passage":"Appel à bénévoles — Bibliothèque des Peupliers\nLa bibliothèque recherche des personnes pour accompagner des ateliers de lecture à destination d'adultes découvrant le français. Il ne s'agit pas de donner des cours de grammaire, mais d'aider les participants à lire des textes courants et à échanger leurs impressions. Les séances auront lieu chaque mardi en fin d'après-midi. Une réunion de préparation sera organisée début janvier. Les candidatures sont ouvertes jusqu'au 15 décembre ; aucune expérience d'enseignement n'est exigée, mais une présence régulière pendant le trimestre est nécessaire.","question":"Quelle sera la mission principale des bénévoles ?","explanation":"Le rôle consiste à accompagner la lecture et les échanges, pas à donner un cours structuré.","section":"email","group":"Bénévolat à la bibliothèque","options":["Conduire des échanges autour de textes du quotidien","Enseigner un programme complet de conjugaison","Former de futurs professeurs à la didactique","Évaluer le niveau linguistique avec des examens"],"correct":"D","semantic":{"concept":"literacy-volunteers-discuss-not-teach","evidence":"adult-read-everyday-text-discussion"}},{"number":30,"points":1,"passage":"Appel à bénévoles — Bibliothèque des Peupliers\nLa bibliothèque recherche des personnes pour accompagner des ateliers de lecture à destination d'adultes découvrant le français. Il ne s'agit pas de donner des cours de grammaire, mais d'aider les participants à lire des textes courants et à échanger leurs impressions. Les séances auront lieu chaque mardi en fin d'après-midi. Une réunion de préparation sera organisée début janvier. Les candidatures sont ouvertes jusqu'au 15 décembre ; aucune expérience d'enseignement n'est exigée, mais une présence régulière pendant le trimestre est nécessaire.","question":"Quel engagement est attendu des candidats ?","explanation":"La bibliothèque exige une présence régulière sur le trimestre, pas de diplôme d'enseignement.","section":"email","group":"Bénévolat à la bibliothèque","options":["Assurer une présence régulière pendant la période prévue","Disposer d'une qualification reconnue d'enseignant","Accepter une disponibilité chaque jour de semaine","Avoir déjà été bénévole dans la même bibliothèque"],"correct":"A","semantic":{"concept":"reading-volunteer-reliable-quarter-commitment","evidence":"quarter-regularity-not-teaching-license"}},{"number":31,"points":1,"passage":"Message du service des ressources humaines\nÀ partir de mars, l'entreprise proposera un covoiturage pour les salariés qui se rendent sur le site industriel. Les trajets seront organisés au moyen d'une plateforme interne ; les conducteurs pourront demander une contribution aux frais dans les limites indiquées. Le dispositif sera testé pendant quatre mois avant toute décision de prolongation. Les horaires décalés ne sont pas encore couverts, car les premiers trajets concernent surtout les équipes de journée. Les participants pourront quitter le programme à tout moment, sans incidence sur leur prise en charge habituelle des transports.","question":"Quelle limite du programme est signalée ?","explanation":"Le programme couvre d'abord les équipes de journée et pas encore tous les horaires décalés.","section":"email","group":"Covoiturage au travail","options":["Les équipes de jour ne peuvent utiliser la plateforme","Les conducteurs doivent prendre en charge tous les frais","Le programme couvre encore mal les horaires atypiques","Les aides habituelles au transport seront supprimées"],"correct":"C","semantic":{"concept":"work-carpool-limited-shift-coverage","evidence":"initially-daytime-teams-only"}},{"number":32,"points":1,"passage":"Message du service des ressources humaines\nÀ partir de mars, l'entreprise proposera un covoiturage pour les salariés qui se rendent sur le site industriel. Les trajets seront organisés au moyen d'une plateforme interne ; les conducteurs pourront demander une contribution aux frais dans les limites indiquées. Le dispositif sera testé pendant quatre mois avant toute décision de prolongation. Les horaires décalés ne sont pas encore couverts, car les premiers trajets concernent surtout les équipes de journée. Les participants pourront quitter le programme à tout moment, sans incidence sur leur prise en charge habituelle des transports.","question":"Qu'est-il prévu au terme des quatre mois ?","explanation":"La prolongation n'est pas acquise : elle sera décidée après une phase d'essai.","section":"email","group":"Covoiturage au travail","options":["Une inscription automatique de tous les salariés concernés","Un bilan avant décision sur la poursuite de l'initiative","Un déplacement permanent des trajets vers le soir","Une répartition définitive des contributions financières"],"correct":"B","semantic":{"concept":"carpool-pilot-reviewed-after-four-months","evidence":"four-month-evaluation-before-extension"}},{"number":33,"points":1,"passage":"LA VILLE FACE AUX ÎLOTS DE CHALEUR\nDans plusieurs communes, les températures relevées en été varient fortement d'une rue à l'autre. Les relevés effectués à l'aide de capteurs montrent que les secteurs très minéralisés restent chauds bien après le coucher du soleil, alors que les rues bordées d'arbres se refroidissent plus rapidement. Pourtant, planter quelques végétaux ne résout pas à lui seul le problème : les racines ont besoin d'espace et l'entretien demande de l'eau pendant les premières années.\n\nPour décider où agir, la municipalité croise les températures observées avec des données sur l'âge des habitants et l'accès aux espaces publics. Certains élus voulaient financer d'abord de grandes places emblématiques, plus visibles dans les médias. L'équipe technique défend au contraire des interventions modestes près des écoles et des résidences pour personnes âgées, où les possibilités de se mettre à l'ombre sont limitées. La mairie annonce un premier bilan dans deux étés, tout en reconnaissant que les effets d'une végétalisation récente seront encore partiels à cette échéance.","question":"Sur quel principe repose la priorité défendue par l'équipe technique ?","explanation":"Les données thermiques sont rapprochées de l'âge des habitants et du manque d'ombre.","section":"long","group":"Îlots de chaleur","options":["Privilégier les espaces déjà très ombragés","Choisir les rues où les travaux coûteront le moins","Intervenir en priorité sur les sites les plus célèbres","Croiser l'intensité de la chaleur et la vulnérabilité"],"correct":"D","semantic":{"concept":"heat-island-prioritize-vulnerable-locations","evidence":"combine-temp-with-age-shade"}},{"number":34,"points":1,"passage":"LA VILLE FACE AUX ÎLOTS DE CHALEUR\nDans plusieurs communes, les températures relevées en été varient fortement d'une rue à l'autre. Les relevés effectués à l'aide de capteurs montrent que les secteurs très minéralisés restent chauds bien après le coucher du soleil, alors que les rues bordées d'arbres se refroidissent plus rapidement. Pourtant, planter quelques végétaux ne résout pas à lui seul le problème : les racines ont besoin d'espace et l'entretien demande de l'eau pendant les premières années.\n\nPour décider où agir, la municipalité croise les températures observées avec des données sur l'âge des habitants et l'accès aux espaces publics. Certains élus voulaient financer d'abord de grandes places emblématiques, plus visibles dans les médias. L'équipe technique défend au contraire des interventions modestes près des écoles et des résidences pour personnes âgées, où les possibilités de se mettre à l'ombre sont limitées. La mairie annonce un premier bilan dans deux étés, tout en reconnaissant que les effets d'une végétalisation récente seront encore partiels à cette échéance.","question":"Pourquoi le bilan annoncé ne permettra-t-il pas de juger entièrement le projet ?","explanation":"Le texte reconnaît que les effets de la végétalisation resteront partiels à deux ans.","section":"long","group":"Îlots de chaleur","options":["Les relevés de température sont limités aux matinées","Les arbres récents n'auront pas encore atteint leur plein effet","La ville n'a prévu aucune comparaison entre les rues","L'entretien des plantations ne commencera qu'après le bilan"],"correct":"B","semantic":{"concept":"tree-planting-effect-not-full-at-two-years","evidence":"growth-not-mature-after-two-summers"}},{"number":35,"points":1,"passage":"NUMÉRISER LES ARCHIVES SANS EFFACER LES CONTEXTES\nLorsqu'une institution met ses archives en ligne, elle facilite l'accès à des documents jusque-là réservés aux chercheurs pouvant se déplacer. Mais un fichier photographié n'est pas une source complètement autonome : la date, le classement original et la provenance du document sont souvent nécessaires pour comprendre ce qu'il représente. Sans ces indications, un extrait spectaculaire peut circuler hors de son contexte et conduire à des interprétations hâtives.\n\nUn réseau de musées régionaux a donc choisi d'avancer moins vite que prévu. Ses équipes ne publient désormais les images qu'après avoir vérifié les notices et précisé les éventuelles lacunes. Cette démarche coûte davantage au départ, mais elle évite de multiplier ultérieurement les corrections. Certains usagers regrettent les délais et demandent une publication immédiate de toutes les photos disponibles. Les archivistes répondent qu'un accès véritablement utile suppose des documents retrouvables, datés et accompagnés d'explications honnêtes sur ce qui demeure incertain. Leur objectif n'est pas de limiter la consultation, mais de ne pas transformer une source incomplète en certitude apparente.","question":"Quel risque est particulièrement souligné par les archivistes ?","explanation":"L'absence de date, de provenance et de contexte peut favoriser de fausses interprétations.","section":"long","group":"Archives numériques","options":["Détériorer les documents originaux pendant la photographie","Empêcher les lecteurs de retrouver les collections accessibles","Interpréter une source isolée sans son contexte historique","Confondre les documents privés avec des livres contemporains"],"correct":"C","semantic":{"concept":"archive-online-documents-provenance-context","evidence":"context-of-origin-important"}},{"number":36,"points":1,"passage":"NUMÉRISER LES ARCHIVES SANS EFFACER LES CONTEXTES\nLorsqu'une institution met ses archives en ligne, elle facilite l'accès à des documents jusque-là réservés aux chercheurs pouvant se déplacer. Mais un fichier photographié n'est pas une source complètement autonome : la date, le classement original et la provenance du document sont souvent nécessaires pour comprendre ce qu'il représente. Sans ces indications, un extrait spectaculaire peut circuler hors de son contexte et conduire à des interprétations hâtives.\n\nUn réseau de musées régionaux a donc choisi d'avancer moins vite que prévu. Ses équipes ne publient désormais les images qu'après avoir vérifié les notices et précisé les éventuelles lacunes. Cette démarche coûte davantage au départ, mais elle évite de multiplier ultérieurement les corrections. Certains usagers regrettent les délais et demandent une publication immédiate de toutes les photos disponibles. Les archivistes répondent qu'un accès véritablement utile suppose des documents retrouvables, datés et accompagnés d'explications honnêtes sur ce qui demeure incertain. Leur objectif n'est pas de limiter la consultation, mais de ne pas transformer une source incomplète en certitude apparente.","question":"Comment les musées justifient-ils leur rythme de publication plus lent ?","explanation":"Les équipes vérifient les notices et signalent les lacunes avant diffusion pour prévenir les corrections et erreurs.","section":"long","group":"Archives numériques","options":["Vérifier les références avant diffusion malgré les délais","Publier les images avant leur inventaire complet","Réserver les contenus intéressants aux chercheurs internes","Supprimer les informations discutées pour aller plus vite"],"correct":"A","semantic":{"concept":"archive-accurate-metadata-first","evidence":"meta-verified-before-release"}},{"number":37,"points":1,"passage":"LES EMBALLAGES RÉUTILISABLES CHANGENT-ILS LA DONNE ?\nDe nombreux restaurants proposent désormais des contenants consignés en remplacement des emballages jetables. L'idée paraît simple : après le repas, le client rapporte sa boîte, qui est lavée puis remise en circulation. Le bénéfice environnemental dépend pourtant du nombre de réutilisations, de l'énergie nécessaire au nettoyage et des distances parcourues pour récupérer les contenants. Une boîte robuste utilisée très peu de fois peut finalement avoir un bilan moins favorable que prévu.\n\nUne enquête menée auprès de plusieurs cantines a relevé une autre difficulté. Les clients apprécient la possibilité de rapporter leur contenant à différents points de collecte, mais se découragent lorsque les horaires sont réduits ou lorsque le dépôt est long à récupérer. Pour améliorer le taux de retour, certains gestionnaires ont choisi des comptoirs de collecte communs à plusieurs établissements. Cela augmente leurs coûts logistiques à court terme, mais permet d'éviter que chaque restaurant organise seul le stockage et la récupération. Les auteurs de l'étude estiment donc que la réussite du système dépend autant de son organisation collective que de la matière utilisée pour fabriquer les boîtes.","question":"Quelle idée centrale l'enquête met-elle en avant ?","explanation":"Le nombre de réemplois et les conditions concrètes de collecte et de lavage déterminent le bilan.","section":"long","group":"Contenants réutilisables","options":["Le bilan dépend de l'usage répété et de la facilité des retours","L'impact dépend seulement du matériau de fabrication","La consigne améliore le bilan dès la première utilisation","Le lavage annule l'ensemble des coûts de transport"],"correct":"A","semantic":{"concept":"reuse-container-frequency-return-logistics","evidence":"environmental-benefit-needs-reuse-returns"}},{"number":38,"points":1,"passage":"LES EMBALLAGES RÉUTILISABLES CHANGENT-ILS LA DONNE ?\nDe nombreux restaurants proposent désormais des contenants consignés en remplacement des emballages jetables. L'idée paraît simple : après le repas, le client rapporte sa boîte, qui est lavée puis remise en circulation. Le bénéfice environnemental dépend pourtant du nombre de réutilisations, de l'énergie nécessaire au nettoyage et des distances parcourues pour récupérer les contenants. Une boîte robuste utilisée très peu de fois peut finalement avoir un bilan moins favorable que prévu.\n\nUne enquête menée auprès de plusieurs cantines a relevé une autre difficulté. Les clients apprécient la possibilité de rapporter leur contenant à différents points de collecte, mais se découragent lorsque les horaires sont réduits ou lorsque le dépôt est long à récupérer. Pour améliorer le taux de retour, certains gestionnaires ont choisi des comptoirs de collecte communs à plusieurs établissements. Cela augmente leurs coûts logistiques à court terme, mais permet d'éviter que chaque restaurant organise seul le stockage et la récupération. Les auteurs de l'étude estiment donc que la réussite du système dépend autant de son organisation collective que de la matière utilisée pour fabriquer les boîtes.","question":"Pourquoi des établissements acceptent-ils des frais logistiques supplémentaires ?","explanation":"Les points communs de collecte simplifient le retour pour les clients et répartissent des tâches autrefois individuelles.","section":"long","group":"Contenants réutilisables","options":["Pour augmenter le prix payé par les clients au retour","Pour supprimer le nettoyage centralisé des contenants","Pour simplifier la collecte en partageant les infrastructures","Pour réduire le nombre d'établissements du réseau"],"correct":"C","semantic":{"concept":"reuse-container-shared-deposit-collection","evidence":"shared-pickup-offsets-individual-cost"}},{"number":39,"points":1,"passage":"DESSERVIR LES PETITES GARES : UNE QUESTION D'ARBITRAGE\nDans une région de moyenne montagne, les élus souhaitent rendre le train plus attractif pour les habitants des villages. L'augmentation du nombre de départs serait une solution visible, mais les lignes disposent de peu de voies de croisement. Ajouter un train à une heure très demandée pourrait alors imposer de déplacer un autre service et compliquer certaines correspondances. Les associations d'usagers rappellent qu'un horaire stable est parfois plus utile qu'une fréquence théorique élevée.\n\nL'autorité organisatrice étudie un compromis : renforcer les départs du matin vers la ville principale, maintenir un retour en soirée et coordonner les bus locaux avec les trains existants. Le projet ne répond pas à toutes les demandes, notamment celles des travailleurs aux horaires atypiques. En revanche, il éviterait d'investir immédiatement dans de nouvelles infrastructures, dont les travaux prendraient plusieurs années. Les décideurs comptent mesurer le nombre de voyageurs mais aussi les correspondances manquées, car une hausse des montées à bord pourrait masquer une dégradation des déplacements complets pour une partie du territoire.","question":"Pourquoi une augmentation des départs ne réglerait-elle pas nécessairement les problèmes ?","explanation":"Le nombre limité de voies peut entraîner un déplacement de services et des correspondances moins pratiques.","section":"long","group":"Petites gares","options":["Elle imposerait de retirer tous les trains du matin","Elle pourrait désorganiser d'autres trajets et correspondances","Elle rendrait inutiles les bus desservant les petits villages","Elle limiterait les déplacements uniquement aux personnes âgées"],"correct":"B","semantic":{"concept":"single-track-frequencies-impact-connecting-services","evidence":"limited-crossing-tracks-cause-disruption"}},{"number":40,"points":1,"passage":"DESSERVIR LES PETITES GARES : UNE QUESTION D'ARBITRAGE\nDans une région de moyenne montagne, les élus souhaitent rendre le train plus attractif pour les habitants des villages. L'augmentation du nombre de départs serait une solution visible, mais les lignes disposent de peu de voies de croisement. Ajouter un train à une heure très demandée pourrait alors imposer de déplacer un autre service et compliquer certaines correspondances. Les associations d'usagers rappellent qu'un horaire stable est parfois plus utile qu'une fréquence théorique élevée.\n\nL'autorité organisatrice étudie un compromis : renforcer les départs du matin vers la ville principale, maintenir un retour en soirée et coordonner les bus locaux avec les trains existants. Le projet ne répond pas à toutes les demandes, notamment celles des travailleurs aux horaires atypiques. En revanche, il éviterait d'investir immédiatement dans de nouvelles infrastructures, dont les travaux prendraient plusieurs années. Les décideurs comptent mesurer le nombre de voyageurs mais aussi les correspondances manquées, car une hausse des montées à bord pourrait masquer une dégradation des déplacements complets pour une partie du territoire.","question":"Quel indicateur complétera le comptage des voyageurs pour évaluer le compromis ?","explanation":"Les décideurs veulent suivre les correspondances manquées pour juger la qualité des trajets entiers.","section":"long","group":"Petites gares","options":["Le nombre de billets vendus en vente directe","Les kilomètres de nouvelles voies mis en service","La dépense prévue pour construire les gares","Le suivi des correspondances que les voyageurs ratent"],"correct":"D","semantic":{"concept":"rail-success-assessed-missed-interchanges","evidence":"count-connections-not-only-boardings"}}]}$bank2$::jsonb;
 if exists(select 1 from academy_tef_reading.papers where id='tef-reading-02' and version='tef-reading-2026-11-original-02-v2' and content<>paper) then raise exception 'Cannot modify published TEF Reading paper version tef-reading-02';end if;
 insert into academy_tef_reading.papers(id,version,content) values('tef-reading-02','tef-reading-2026-11-original-02-v2',paper) on conflict do nothing;

 paper := $bank3${"id":"tef-reading-03","version":"tef-reading-2026-11-original-03-v1","title":"TEF Canada · Compréhension écrite · Test 03","seconds":3600,"maxPoints":40,"questions":[{"number":1,"points":1,"passage":"⛴️ PORT DU LEVANT\nLe départ de 8 h 20 vers l'île de Brume est maintenu, mais l'embarquement se fera exceptionnellement au ponton C. Les voyageurs présentant un billet acheté pour le ponton A n'ont pas besoin de l'échanger ; leur billet reste valable.","question":"Quelle démarche est demandée aux voyageurs déjà munis d'un billet ?","options":["Échanger leur billet au guichet du ponton A","Se présenter au ponton C avec leur billet initial","Confirmer leur voyage au service des réservations","Rejoindre le ponton A puis attendre une navette"],"correct":"B","explanation":"Le quai d'embarquement change, mais les billets restent valables sans échange.","semantic":{"concept":"ferry-pier-relocation","evidence":"ticket-valid-despite-boarding-location"},"media":{"kind":"notice","icon":"⛴️","heading":"Départ du bateau · ponton modifié","accent":"#146d89"}},{"number":2,"points":1,"passage":"🕰️ MUSÉE DES MÉTIERS\nLes visites commentées commencent à 10 h et 15 h. Le mardi, la séance du matin est réservée aux groupes scolaires ; les visiteurs individuels peuvent participer à celle de l'après-midi, dans la limite des places.","question":"Quelle visite est accessible à une personne seule le mardi ?","options":["Celle de 10 h avec inscription sur place","Celle de 10 h en rejoignant un groupe scolaire","Les deux séances, sans réservation préalable","Celle de 15 h, sous réserve de disponibilité"],"correct":"D","explanation":"Le mardi matin est réservé aux écoles, mais l'après-midi reste accessible aux particuliers.","semantic":{"concept":"museum-weekday-restricted-session","evidence":"individual-entry-afternoon-only"},"media":{"kind":"notice","icon":"🏛️","heading":"Visites commentées · mardi","accent":"#6c5d9e"}},{"number":3,"points":1,"passage":"🧵 ATELIER DE COUTURE\nLa séance « Retouches simples » accueille les débutants avec leur vêtement à réparer. Les machines sont prêtées gratuitement, tandis que le fil et les fermetures doivent être apportés par les participants. L'atelier ne vend pas de fournitures.","question":"Que doit prévoir un participant ?","options":["Les petites fournitures nécessaires à sa retouche","Une machine personnelle en état de marche","Une attestation de niveau en couture","Le règlement d'une location de machine"],"correct":"A","explanation":"Le prêt des machines est gratuit mais les fournitures restent à apporter.","semantic":{"concept":"sewing-supplies-required","evidence":"machines-provided-not-materials"},"media":{"kind":"notice","icon":"🧵","heading":"Atelier retouches · matériel","accent":"#ad6746"}},{"number":4,"points":1,"passage":"🔭 OBSERVATOIRE DES COLLINES\nPour limiter la pollution lumineuse, la soirée d'observation débute après l'extinction de l'éclairage du parc. Les participants sont invités à utiliser une lampe à lumière rouge pour se déplacer sans gêner les télescopes.","question":"Pourquoi recommande-t-on un éclairage rouge ?","options":["Pour repérer plus facilement les planètes lumineuses","Pour signaler sa présence aux visiteurs du parc","Pour préserver les conditions d'observation nocturne","Pour compenser l'absence de télescopes individuels"],"correct":"C","explanation":"Une lumière rouge gêne moins l'observation et l'adaptation des yeux à l'obscurité.","semantic":{"concept":"observatory-low-light-guidance","evidence":"red-light-preserves-night-vision"},"media":{"kind":"illustration","scene":"observatory","heading":"Soirée d'observation du ciel"}},{"number":5,"points":1,"passage":"🎤 RADIO ASSOCIATIVE\nLes habitants souhaitant proposer une émission disposent jusqu'au 12 avril pour envoyer une présentation de cinq minutes. Les projets retenus participeront ensuite à un atelier technique avant toute diffusion à l'antenne.","question":"Quelle étape précède la diffusion d'un projet accepté ?","options":["Un vote des auditeurs pendant cinq semaines","L'enregistrement immédiat d'une émission complète","Le paiement d'un abonnement à la station","Une initiation aux outils de production radiophonique"],"correct":"D","explanation":"Les propositions retenues passent par un atelier technique avant leur diffusion.","semantic":{"concept":"community-radio-onboarding","evidence":"technical-workshop-before-broadcast"},"media":{"kind":"illustration","scene":"radio","heading":"Proposez votre émission"}},{"number":6,"points":1,"passage":"🌾 PANIER LOCAL\nLes commandes passées avant mercredi 18 h sont livrées le vendredi. Au-delà de cette limite, le panier est préparé pour le vendredi suivant. Les commandes peuvent être modifiées tant que l'échéance du mercredi n'est pas dépassée.","question":"Quand sera livré un panier commandé jeudi matin ?","options":["Le vendredi immédiatement après la commande","Le samedi matin avec un supplément de transport","Le vendredi de la semaine suivante","Le mercredi suivant après validation"],"correct":"C","explanation":"Une commande après mercredi 18 h passe au cycle de livraison suivant.","semantic":{"concept":"weekly-cutoff-rollover","evidence":"post-deadline-order-next-week"},"media":{"kind":"notice","icon":"🥬","heading":"Commande des paniers","accent":"#3d855b"}},{"number":7,"points":1,"passage":"🚴 PARCOURS CYCLABLE\nUne portion du parcours le long du canal est temporairement partagée avec les piétons. Les cyclistes doivent mettre pied à terre sur les 200 mètres indiqués par des panneaux. Le reste de la voie demeure accessible à vélo.","question":"Quelle règle s'applique dans la zone signalée ?","options":["Pousser son vélo sur une courte portion du trajet","Emprunter la chaussée réservée aux automobiles","Continuer à rouler en réduisant seulement sa vitesse","Rebrousser chemin jusqu'au dernier carrefour"],"correct":"A","explanation":"L'obligation de descendre du vélo concerne uniquement la section balisée.","semantic":{"concept":"cyclist-dismount-segment","evidence":"walking-bike-on-signed-stretch"},"media":{"kind":"notice","icon":"🚲","heading":"Itinéraire partagé · canal","accent":"#34839e"}},{"number":8,"points":1,"passage":"Le rapport contient plusieurs réserves ; sa publication ne doit pas être ________ comme une approbation sans condition.","question":"Quel verbe respecte le sens de la phrase ?","options":["présentée","interprétée","examinée","annoncée"],"correct":"B","explanation":"La phrase précise que publier le rapport ne signifie pas lui donner une interprétation d'approbation totale.","semantic":{"concept":"report-interpretation-reservations","evidence":"publication-not-unconditional-approval"},"section":"cloze"},{"number":9,"points":1,"passage":"Les travaux commenceront lundi, ________ l'autorisation administrative ait été délivrée d'ici là.","question":"Quelle locution convient grammaticalement ?","options":["à condition que","même si","alors que","du fait que"],"correct":"A","explanation":"L'action dépend d'une autorisation encore incertaine, d'où « à condition que » suivi du subjonctif.","semantic":{"concept":"conditional-work-authorization","evidence":"condition-and-subjunctive"},"section":"cloze"},{"number":10,"points":1,"passage":"La facture doit être réglée ________ quinze jours à compter de sa réception.","question":"Quelle expression de délai convient ?","options":["à la suite de","à l'occasion de","dans un délai de","à la mesure de"],"correct":"C","explanation":"« Dans un délai de quinze jours » exprime une échéance à respecter.","semantic":{"concept":"payment-window-idiom","evidence":"deadline-counted-from-receipt"},"section":"cloze"},{"number":11,"points":1,"passage":"Les auteurs ont demandé que la proposition ________ examinée à la prochaine séance.","question":"Quelle forme verbale complète correctement la phrase ?","options":["sera","est","était","soit"],"correct":"D","explanation":"« Demander que » appelle le subjonctif ; « soit examinée » est la forme passive correcte.","semantic":{"concept":"request-subjunctive-passive","evidence":"demander-que-soit-examinee"},"section":"cloze"},{"number":12,"points":1,"passage":"ÉQUIPEMENT PUBLIC\nAprès la panne, les techniciens ont d'abord cherché à ________ (1) l'origine du défaut avant de commander des pièces. Ils ont reporté la réouverture pour ne pas ________ (2) la sécurité des usagers.","question":"Quel verbe convient à l'espace (1) ?","options":["évaluer","identifier","déplacer","expliquer"],"correct":"B","explanation":"Avant de commander une pièce, les techniciens doivent identifier l'origine de la panne.","semantic":{"concept":"fault-root-cause","evidence":"diagnose-before-ordering"},"section":"paired-cloze","group":"Équipement public"},{"number":13,"points":1,"passage":"ÉQUIPEMENT PUBLIC\nAprès la panne, les techniciens ont d'abord cherché à ________ (1) l'origine du défaut avant de commander des pièces. Ils ont reporté la réouverture pour ne pas ________ (2) la sécurité des usagers.","question":"Quel verbe convient à l'espace (2) ?","options":["compromettre","garantir","renforcer","contrôler"],"correct":"A","explanation":"Reporter la réouverture évite de compromettre la sécurité des utilisateurs.","semantic":{"concept":"reopening-safety-risk","evidence":"delay-to-avoid-risk"},"section":"paired-cloze","group":"Équipement public"},{"number":14,"points":1,"passage":"COOPÉRATIVE ARTISANALE\nLes membres ont décidé de ________ (1) leurs achats de matières premières afin de négocier de meilleurs tarifs. Ils conserveront cependant leur ________ (2) pour fixer le prix de vente de leurs créations.","question":"Quel verbe convient à l'espace (1) ?","options":["différer","limiter","regrouper","justifier"],"correct":"C","explanation":"Des achats regroupés permettent à plusieurs artisans de négocier ensemble.","semantic":{"concept":"group-procurement-negotiation","evidence":"purchasing-collectively"},"section":"paired-cloze","group":"Coopérative artisanale"},{"number":15,"points":1,"passage":"COOPÉRATIVE ARTISANALE\nLes membres ont décidé de ________ (1) leurs achats de matières premières afin de négocier de meilleurs tarifs. Ils conserveront cependant leur ________ (2) pour fixer le prix de vente de leurs créations.","question":"Quel nom convient à l'espace (2) ?","options":["ancienneté","visibilité","obligation","autonomie"],"correct":"D","explanation":"Chaque artisan continuera à décider lui-même de ses prix de vente.","semantic":{"concept":"independent-pricing-cooperative","evidence":"maintains-own-selling-prices"},"section":"paired-cloze","group":"Coopérative artisanale"},{"number":16,"points":1,"passage":"RENCONTRE LITTÉRAIRE\nLa médiatrice demande aux invités de ________ (1) un passage de leur choix, puis de le commenter. Afin que chacun puisse s'exprimer, elle veillera à ________ (2) équitablement les temps de parole.","question":"Quel verbe convient à l'espace (1) ?","options":["classer","lire","publier","résumer"],"correct":"B","explanation":"Il est prévu de faire entendre un passage avant sa discussion.","semantic":{"concept":"read-excerpt-aloud","evidence":"passage-followed-by-commentary"},"section":"paired-cloze","group":"Rencontre littéraire"},{"number":17,"points":1,"passage":"RENCONTRE LITTÉRAIRE\nLa médiatrice demande aux invités de ________ (1) un passage de leur choix, puis de le commenter. Afin que chacun puisse s'exprimer, elle veillera à ________ (2) équitablement les temps de parole.","question":"Quel verbe convient à l'espace (2) ?","options":["répartir","prolonger","réserver","mesurer"],"correct":"A","explanation":"Il s'agit d'attribuer à chacun une part équitable du temps de parole.","semantic":{"concept":"allocate-turns-fairly","evidence":"fair-speaking-time-allocation"},"section":"paired-cloze","group":"Rencontre littéraire"},{"number":18,"points":1,"passage":"","question":"Quelle proposition convient à une personne expérimentée en cuisine qui cherche un contrat de semaine, sans service le soir ?","options":["Offre 1","Offre 2","Offre 4","Offre 3"],"correct":"C","explanation":"La quatrième offre est en cuisine, en journée du lundi au vendredi, et exige une expérience antérieure.","semantic":{"concept":"weekday-daytime-experienced-cook","evidence":"all-constraints-one-offer"},"section":"offers","media":{"kind":"offers","heading":"Recrutements · Restauration","items":["Restaurant du port : cuisinier expérimenté, service du soir du mardi au samedi.","Cantine scolaire : aide débutant, déjeuner du lundi au vendredi, formation proposée.","Hôtel : chef de partie confirmé, déjeuner et dîner selon planning tournant.","Cafétéria d'entreprise : cuisinier confirmé, préparation du lundi au vendredi de 7 h à 15 h."]}},{"number":19,"points":1,"passage":"","question":"Quelle annonce correspond à une activité occasionnelle à distance, réservée aux personnes maîtrisant déjà le montage vidéo ?","options":["Offre 2","Offre 3","Offre 4","Offre 1"],"correct":"D","explanation":"Seule l'offre 1 combine la possibilité de travailler à distance, des missions ponctuelles et une maîtrise préalable du montage.","semantic":{"concept":"remote-freelance-video-editing","evidence":"remote-occasional-skilled"},"section":"offers","media":{"kind":"offers","heading":"Missions · Création numérique","items":["Studio documentaire : montage de séquences à domicile, quelques missions par trimestre ; pratique confirmée exigée.","Centre culturel : initiation au montage, présence deux soirs par semaine sur place.","Agence média : montage professionnel au bureau, contrat fixe à temps plein.","Association locale : filmer des événements ponctuels, déplacements obligatoires ; débutants acceptés."]}},{"number":20,"points":1,"passage":"ÉVOLUTION D'UN INDICATEUR\nComparez la direction des variations entre les cinq observations.","question":"Quel graphique présente une hausse, puis deux reculs successifs, avant une dernière hausse dépassant le premier sommet ?","options":["Graphique 1","Graphique 3","Graphique 2","Graphique 4"],"correct":"B","explanation":"La série 3 passe de 10 à 24, recule deux fois puis atteint 28, au-delà de son premier pic.","semantic":{"concept":"trend-rise-two-falls-rise-past-peak","evidence":"shape-10-24-18-12-28"},"section":"charts","media":{"kind":"chart-grid","heading":"Évolution des réservations","unit":"en milliers","years":["A","B","C","D","E"],"series":[[18,20,22,21,24],[27,19,11,17,20],[10,24,18,12,28],[17,17,23,23,24]]}},{"number":21,"points":1,"passage":"SUIVI DES DONNÉES\nLes quatre graphiques portent sur une période comparable.","question":"Quel graphique montre une progression initiale, un palier de deux observations, puis une baisse finale inférieure à la valeur de départ ?","options":["Graphique 2","Graphique 1","Graphique 3","Graphique 4"],"correct":"A","explanation":"Dans la série 2, les valeurs passent de 14 à 22, restent à 22, puis chutent à 9, sous 14.","semantic":{"concept":"rise-plateau-then-below-start","evidence":"shape-14-22-22-22-9"},"section":"charts","media":{"kind":"chart-grid","heading":"Visites au centre nautique","unit":"en centaines","years":["P1","P2","P3","P4","P5"],"series":[[21,15,23,16,21],[14,22,22,22,9],[12,12,17,21,23],[28,24,19,14,10]]}},{"number":22,"points":1,"passage":"MESURES ANNUELLES\nAnalysez les séries sur cinq années.","question":"Quel graphique affiche un creux à la troisième année, suivi de deux hausses, sans retrouver le niveau de la première année ?","options":["Graphique 1","Graphique 2","Graphique 4","Graphique 3"],"correct":"C","explanation":"La série 4 atteint son minimum au milieu, puis remonte deux fois, mais finit à 21 contre 25 au départ.","semantic":{"concept":"midpoint-trough-two-rises-under-start","evidence":"shape-25-16-9-15-21"},"section":"charts","media":{"kind":"chart-grid","heading":"Volumes de marchandises","unit":"en centaines de tonnes","years":["2018","2019","2020","2021","2022"],"series":[[18,16,14,20,25],[10,20,10,20,10],[14,16,10,8,13],[25,16,9,15,21]]}},{"number":23,"points":1,"passage":"Objet : Réservation de salle pour votre association\nBonjour,\nNous pouvons vous réserver la salle du premier étage le jeudi 18 mai. Le mobilier sera installé selon le plan joint, à condition que vous nous confirmiez le nombre de participants avant lundi soir. En revanche, l'accès à la terrasse est suspendu en raison de travaux sur la façade ; elle ne pourra pas servir de sortie supplémentaire. La salle possède deux issues de secours accessibles. Le tarif convenu inclut le nettoyage ordinaire après l'événement, mais pas l'enlèvement de décors volumineux. Merci de nous indiquer si ces conditions vous conviennent.\nService des manifestations.","question":"Quelle information l'association doit-elle transmettre avant lundi soir ?","options":["Le choix de l'entreprise chargée des travaux","Les noms des personnes responsables du nettoyage","La liste des meubles qu'elle souhaite acheter","Le nombre définitif de personnes attendues"],"correct":"D","explanation":"Le plan de mobilier dépend du nombre de participants à confirmer.","semantic":{"concept":"event-attendance-confirmation","evidence":"count-for-room-setup"},"section":"email","group":"Réservation d'une salle"},{"number":24,"points":1,"passage":"Objet : Réservation de salle pour votre association\nBonjour,\nNous pouvons vous réserver la salle du premier étage le jeudi 18 mai. Le mobilier sera installé selon le plan joint, à condition que vous nous confirmiez le nombre de participants avant lundi soir. En revanche, l'accès à la terrasse est suspendu en raison de travaux sur la façade ; elle ne pourra pas servir de sortie supplémentaire. La salle possède deux issues de secours accessibles. Le tarif convenu inclut le nettoyage ordinaire après l'événement, mais pas l'enlèvement de décors volumineux. Merci de nous indiquer si ces conditions vous conviennent.\nService des manifestations.","question":"Quelle tâche pourrait être facturée en supplément ?","options":["Le nettoyage habituel des sols après la rencontre","L'évacuation d'installations encombrantes après l'activité","La mise en place du mobilier selon le plan prévu","L'utilisation des deux issues de secours"],"correct":"B","explanation":"Le nettoyage courant est compris, contrairement à l'enlèvement de gros décors.","semantic":{"concept":"venue-bulky-decor-removal-charge","evidence":"regular-clean-included-bulky-extra"},"section":"email","group":"Réservation d'une salle"},{"number":25,"points":1,"passage":"Information aux usagers — Stationnement résidentiel\nLe permis de stationnement sera renouvelé en ligne cette année. La plateforme ouvre le 3 janvier et ferme le 31 janvier. Les permis déjà valables jusqu'au 28 février continuent de fonctionner pendant la procédure. Les résidents ayant changé de véhicule doivent joindre une copie de leur nouveau certificat d'immatriculation. Le tarif reste identique, mais une vérification du domicile est effectuée pour chaque demande. Les personnes qui n'utilisent pas Internet peuvent déposer leur dossier auprès du point d'accueil, sur rendez-vous uniquement. Aucun renouvellement automatique n'est prévu.","question":"À qui demande-t-on une pièce supplémentaire liée au véhicule ?","options":["Aux titulaires dont la voiture n'est plus la même","Aux usagers qui renouvellent leur permis sans changement","Aux personnes qui règlent leur abonnement sur place","Aux résidents arrivant en voiture au point d'accueil"],"correct":"A","explanation":"Le nouveau certificat d'immatriculation est exigé en cas de changement de véhicule.","semantic":{"concept":"permit-new-vehicle-proof","evidence":"car-registration-only-if-changed"},"section":"email","group":"Stationnement résidentiel"},{"number":26,"points":1,"passage":"Information aux usagers — Stationnement résidentiel\nLe permis de stationnement sera renouvelé en ligne cette année. La plateforme ouvre le 3 janvier et ferme le 31 janvier. Les permis déjà valables jusqu'au 28 février continuent de fonctionner pendant la procédure. Les résidents ayant changé de véhicule doivent joindre une copie de leur nouveau certificat d'immatriculation. Le tarif reste identique, mais une vérification du domicile est effectuée pour chaque demande. Les personnes qui n'utilisent pas Internet peuvent déposer leur dossier auprès du point d'accueil, sur rendez-vous uniquement. Aucun renouvellement automatique n'est prévu.","question":"Que doivent prévoir les personnes sans accès à Internet ?","options":["Un renouvellement assuré automatiquement en février","Une demande transmise oralement au poste de police","Un dépôt de dossier avec rendez-vous préalable","Une visite spontanée pendant les horaires d'ouverture"],"correct":"C","explanation":"Une alternative au portail existe, mais elle nécessite un rendez-vous.","semantic":{"concept":"permit-offline-appointment","evidence":"in-person-only-on-appointment"},"section":"email","group":"Stationnement résidentiel"},{"number":27,"points":1,"passage":"Objet : Participation au programme de mentorat\nBonjour,\nVotre candidature au programme de mentorat professionnel a été retenue. Vous serez mis en relation avec une personne travaillant dans un secteur proche du vôtre, et non nécessairement dans la même entreprise. Les échanges se dérouleront pendant quatre mois, à raison d'au moins une rencontre mensuelle. La première séance collective est obligatoire ; elle permettra de préciser le cadre de confidentialité et les attentes mutuelles. Le programme est gratuit. Si vous souhaitez vous désister, prévenez-nous au moins une semaine avant le lancement afin que votre place soit proposée à une personne sur liste d'attente.\nL'équipe du programme.","question":"À quoi sert principalement la séance collective initiale ?","options":["À choisir une entreprise qui recrutera le participant","À évaluer les candidats au moyen d'un examen","À négocier le prix des rencontres individuelles","À définir des règles communes et les objectifs du suivi"],"correct":"D","explanation":"La rencontre sert à poser les règles de confidentialité et les attentes de chacun.","semantic":{"concept":"mentorship-onboarding-confidentiality","evidence":"rules-and-expectations-at-start"},"section":"email","group":"Mentorat professionnel"},{"number":28,"points":1,"passage":"Objet : Participation au programme de mentorat\nBonjour,\nVotre candidature au programme de mentorat professionnel a été retenue. Vous serez mis en relation avec une personne travaillant dans un secteur proche du vôtre, et non nécessairement dans la même entreprise. Les échanges se dérouleront pendant quatre mois, à raison d'au moins une rencontre mensuelle. La première séance collective est obligatoire ; elle permettra de préciser le cadre de confidentialité et les attentes mutuelles. Le programme est gratuit. Si vous souhaitez vous désister, prévenez-nous au moins une semaine avant le lancement afin que votre place soit proposée à une personne sur liste d'attente.\nL'équipe du programme.","question":"Pourquoi faut-il prévenir assez tôt en cas de désistement ?","options":["Pour obtenir le remboursement de la première séance","Pour permettre de proposer la place à un autre candidat","Pour changer immédiatement le secteur du mentor","Pour réduire la durée prévue du programme"],"correct":"B","explanation":"Le préavis sert à réattribuer la place disponible.","semantic":{"concept":"mentorship-waitlist-reassignment","evidence":"withdrawal-notice-waitlist"},"section":"email","group":"Mentorat professionnel"},{"number":29,"points":1,"passage":"Communiqué — Marché des créateurs\nÀ l'occasion du marché de printemps, les artisans sélectionnés pourront exposer deux journées dans la galerie couverte. Les stands standards seront fournis, mais l'éclairage spécifique et les présentoirs supplémentaires resteront à leur charge. Les participants devront présenter un dossier photographique de leurs créations avant le 20 février. Le comité examinera la cohérence du travail proposé et la diversité des techniques représentées, sans tenir compte du nombre d'abonnés sur les réseaux sociaux. Une réunion d'information suivra la sélection ; les exposants recevront à ce moment les consignes d'installation.","question":"Sur quel élément le comité prévoit-il de juger les candidatures ?","options":["La qualité et la diversité des démarches présentées","La popularité des candidats sur les réseaux sociaux","Le nombre d'expositions commerciales déjà réalisées","Le montant des investissements en publicité"],"correct":"A","explanation":"Le comité examine le travail et les techniques, pas la popularité numérique.","semantic":{"concept":"artisan-market-selection-criteria","evidence":"coherence-and-technique-not-followers"},"section":"email","group":"Marché des créateurs"},{"number":30,"points":1,"passage":"Communiqué — Marché des créateurs\nÀ l'occasion du marché de printemps, les artisans sélectionnés pourront exposer deux journées dans la galerie couverte. Les stands standards seront fournis, mais l'éclairage spécifique et les présentoirs supplémentaires resteront à leur charge. Les participants devront présenter un dossier photographique de leurs créations avant le 20 février. Le comité examinera la cohérence du travail proposé et la diversité des techniques représentées, sans tenir compte du nombre d'abonnés sur les réseaux sociaux. Une réunion d'information suivra la sélection ; les exposants recevront à ce moment les consignes d'installation.","question":"Que doivent financer eux-mêmes les exposants ?","options":["La location de l'emplacement standard","La fourniture du mobilier de base de chaque stand","Les équipements particuliers au-delà du stand fourni","L'organisation de la réunion d'information"],"correct":"C","explanation":"Le stand est mis à disposition, mais l'éclairage spécifique et les présentoirs additionnels restent payants.","semantic":{"concept":"artisan-market-extra-equipment","evidence":"extras-not-basic-stand"},"section":"email","group":"Marché des créateurs"},{"number":31,"points":1,"passage":"Message aux membres — Association des jardins du quartier\nNotre association proposera cet automne un échange de graines entre habitants. Pour éviter la diffusion de variétés mal identifiées, chaque sachet devra porter le nom de la plante, l'année de récolte et l'origine des graines. Des bénévoles pourront aider à préparer les étiquettes lors de la permanence du samedi. Les sachets dont les informations sont incomplètes ne seront pas jetés, mais conservés séparément jusqu'à clarification. Les échanges resteront gratuits et les participants ne seront pas tenus de donner autant de graines qu'ils en reçoivent. L'objectif est de partager des variétés adaptées au climat local.","question":"Comment l'association traitera-t-elle un sachet mal étiqueté ?","options":["Elle le distribuera en priorité aux nouveaux membres","Elle le détruira systématiquement pendant la collecte","Elle le vendra à prix réduit sans autre vérification","Elle le mettra de côté jusqu'à vérification des informations"],"correct":"D","explanation":"Les sachets incomplets sont conservés séparément, et non jetés.","semantic":{"concept":"seed-label-quarantine","evidence":"hold-incomplete-packets"},"section":"email","group":"Échange de graines"},{"number":32,"points":1,"passage":"Message aux membres — Association des jardins du quartier\nNotre association proposera cet automne un échange de graines entre habitants. Pour éviter la diffusion de variétés mal identifiées, chaque sachet devra porter le nom de la plante, l'année de récolte et l'origine des graines. Des bénévoles pourront aider à préparer les étiquettes lors de la permanence du samedi. Les sachets dont les informations sont incomplètes ne seront pas jetés, mais conservés séparément jusqu'à clarification. Les échanges resteront gratuits et les participants ne seront pas tenus de donner autant de graines qu'ils en reçoivent. L'objectif est de partager des variétés adaptées au climat local.","question":"Quelle règle encadre la quantité de graines échangées ?","options":["Chaque membre doit apporter exactement autant qu'il emporte","Le don reçu n'oblige pas à fournir une quantité équivalente","Seuls les membres ayant donné l'an dernier peuvent recevoir","L'échange dépend du paiement d'une cotisation par sachet"],"correct":"B","explanation":"La quantité donnée ne doit pas être égale à la quantité reçue.","semantic":{"concept":"seed-exchange-no-equal-reciprocity","evidence":"no-quantity-reciprocity-required"},"section":"email","group":"Échange de graines"},{"number":33,"points":1,"passage":"QUAND LES CARTES DE RISQUES DEVIENNENT DES OUTILS DE DIALOGUE\nDans une vallée régulièrement touchée par les crues, les services publics ont produit une carte détaillée des zones susceptibles d'être inondées. Le document, fondé sur plusieurs décennies d'observations et des scénarios de fortes pluies, a d'abord été présenté comme un outil technique. Certains habitants y ont pourtant vu une décision immédiate d'interdire toute rénovation dans leur rue. Les ingénieurs ont dû distinguer les informations sur le danger potentiel des règles d'urbanisme effectivement en vigueur.\n\nPour rendre la carte utile, une série de réunions a été organisée avec les riverains. Les participants ont apporté des connaissances que les données générales ne faisaient pas apparaître : passages d'eau derrière des murs, caves régulièrement humides, chemins empruntés lors de précédentes évacuations. Ces témoignages n'ont pas remplacé les mesures officielles, mais ils ont conduit à ajouter des points de vigilance et à préciser plusieurs parcours de mise à l'abri. Les responsables reconnaissent qu'une carte exacte peut rester inefficace si ses destinataires la comprennent mal. Ils souhaitent maintenant publier des exemples concrets de décisions que la carte peut éclairer, sans la présenter comme une prédiction certaine de la prochaine crue.","question":"Quelle difficulté est apparue lors de la première diffusion de la carte ?","options":["Une partie du public a confondu indication de risque et règle applicable","Les données chiffrées contredisaient systématiquement les mesures existantes","Les habitants refusaient de transmettre toute observation locale","Les ingénieurs voulaient interdire tout usage public du document"],"correct":"A","explanation":"Des riverains ont pris la représentation du danger pour une décision de réglementation immédiate.","semantic":{"concept":"risk-map-misread-as-policy","evidence":"hazard-information-not-building-ban"},"section":"long","group":"Cartographie des crues"},{"number":34,"points":1,"passage":"QUAND LES CARTES DE RISQUES DEVIENNENT DES OUTILS DE DIALOGUE\nDans une vallée régulièrement touchée par les crues, les services publics ont produit une carte détaillée des zones susceptibles d'être inondées. Le document, fondé sur plusieurs décennies d'observations et des scénarios de fortes pluies, a d'abord été présenté comme un outil technique. Certains habitants y ont pourtant vu une décision immédiate d'interdire toute rénovation dans leur rue. Les ingénieurs ont dû distinguer les informations sur le danger potentiel des règles d'urbanisme effectivement en vigueur.\n\nPour rendre la carte utile, une série de réunions a été organisée avec les riverains. Les participants ont apporté des connaissances que les données générales ne faisaient pas apparaître : passages d'eau derrière des murs, caves régulièrement humides, chemins empruntés lors de précédentes évacuations. Ces témoignages n'ont pas remplacé les mesures officielles, mais ils ont conduit à ajouter des points de vigilance et à préciser plusieurs parcours de mise à l'abri. Les responsables reconnaissent qu'une carte exacte peut rester inefficace si ses destinataires la comprennent mal. Ils souhaitent maintenant publier des exemples concrets de décisions que la carte peut éclairer, sans la présenter comme une prédiction certaine de la prochaine crue.","question":"Quel rôle les témoignages ont-ils joué dans la révision du document ?","options":["Supprimer les cartes officielles au profit des seuls souvenirs des riverains","Garantir la date exacte de la prochaine inondation importante","Compléter les mesures avec des observations locales utiles aux parcours","Remplacer les règles d'urbanisme par un accord entre voisins"],"correct":"C","explanation":"Les récits ont apporté des informations locales et amélioré les itinéraires, sans supplanter les mesures.","semantic":{"concept":"risk-map-local-knowledge-complement","evidence":"testimony-adds-points-and-routes"},"section":"long","group":"Cartographie des crues"},{"number":35,"points":1,"passage":"LES PETITS CINÉMAS À L'HEURE DES PLATEFORMES\nLa fréquentation des cinémas de proximité ne suit pas exactement celle des grands complexes. Une enquête régionale montre que les habitants ne choisissent pas seulement une séance en fonction du titre projeté : ils apprécient parfois la possibilité de rencontrer un réalisateur ou de discuter d'un film après sa diffusion. Pour autant, organiser de telles rencontres coûte du temps et ne garantit pas une salle pleine. Les établissements ayant multiplié les événements sans tenir compte des habitudes de leur quartier ont parfois vu leurs dépenses augmenter plus vite que leurs recettes.\n\nPlusieurs cinémas ont adopté une stratégie plus modeste. Ils organisent une discussion mensuelle avec des associations locales, tout en conservant des séances ordinaires à prix accessible. Dans l'un de ces établissements, la fréquentation a légèrement progressé sans que le nombre de projections augmente. La direction estime qu'une programmation reconnaissable est plus importante qu'une succession d'animations exceptionnelles. Certains exploitants continuent néanmoins de privilégier les sorties très médiatisées, car elles attirent ponctuellement davantage de spectateurs. Les auteurs de l'étude refusent donc de désigner une solution universelle : ils conseillent de tenir compte de la population desservie et de mesurer les résultats sur plusieurs mois, au lieu de juger une démarche à partir d'une seule soirée réussie.","question":"Quelle leçon l'enquête tire-t-elle des événements organisés trop fréquemment ?","options":["Ils rendent toutes les séances ordinaires immédiatement plus rentables","Ils attirent nécessairement un public fidèle dès leur première édition","Ils remplacent durablement les séances accessibles au tarif habituel","Ils peuvent créer des coûts qui ne sont pas compensés par le public présent"],"correct":"D","explanation":"Les animations demandent des moyens sans toujours augmenter suffisamment la fréquentation.","semantic":{"concept":"local-cinema-events-cost-return","evidence":"event-spending-may-outgrow-revenue"},"section":"long","group":"Cinémas de proximité"},{"number":36,"points":1,"passage":"LES PETITS CINÉMAS À L'HEURE DES PLATEFORMES\nLa fréquentation des cinémas de proximité ne suit pas exactement celle des grands complexes. Une enquête régionale montre que les habitants ne choisissent pas seulement une séance en fonction du titre projeté : ils apprécient parfois la possibilité de rencontrer un réalisateur ou de discuter d'un film après sa diffusion. Pour autant, organiser de telles rencontres coûte du temps et ne garantit pas une salle pleine. Les établissements ayant multiplié les événements sans tenir compte des habitudes de leur quartier ont parfois vu leurs dépenses augmenter plus vite que leurs recettes.\n\nPlusieurs cinémas ont adopté une stratégie plus modeste. Ils organisent une discussion mensuelle avec des associations locales, tout en conservant des séances ordinaires à prix accessible. Dans l'un de ces établissements, la fréquentation a légèrement progressé sans que le nombre de projections augmente. La direction estime qu'une programmation reconnaissable est plus importante qu'une succession d'animations exceptionnelles. Certains exploitants continuent néanmoins de privilégier les sorties très médiatisées, car elles attirent ponctuellement davantage de spectateurs. Les auteurs de l'étude refusent donc de désigner une solution universelle : ils conseillent de tenir compte de la population desservie et de mesurer les résultats sur plusieurs mois, au lieu de juger une démarche à partir d'une seule soirée réussie.","question":"Pourquoi les auteurs évitent-ils de prescrire une même stratégie à tous les cinémas ?","options":["Les complexes et petits cinémas diffusent obligatoirement les mêmes films","L'efficacité dépend du quartier et d'observations menées dans la durée","Les rencontres avec les réalisateurs sont interdites dans certains quartiers","Les statistiques de fréquentation n'apportent aucun renseignement utile"],"correct":"B","explanation":"Les recommandations doivent tenir compte du public local et de résultats suivis sur plusieurs mois.","semantic":{"concept":"local-cinema-contextual-evaluation","evidence":"local-audience-and-longer-measurement"},"section":"long","group":"Cinémas de proximité"},{"number":37,"points":1,"passage":"LE RETOUR DES ATELIERS DE CARTOGRAPHIE PARTICIPATIVE\nUn collectif de randonneurs a entrepris de mettre à jour les chemins d'une zone rurale, où les cartes numériques comportaient plusieurs passages impraticables. Les bénévoles ont commencé par relever les obstacles sur le terrain. Ils ont rapidement constaté que les chemins les plus utilisés n'étaient pas toujours les plus sûrs, notamment lorsqu'ils traversaient des propriétés privées ou des terrains fragilisés après des pluies. Publier immédiatement toutes les traces aurait pu attirer davantage de marcheurs dans des secteurs qui nécessitaient encore des vérifications.\n\nLe collectif a donc créé deux niveaux d'information : les parcours confirmés sont visibles sur la carte destinée au public, tandis que les tracés en cours de vérification restent dans un espace de travail réservé aux contributeurs. Cette séparation a déplu à certains passionnés de données ouvertes, qui craignaient que les corrections n'arrivent trop lentement. L'équipe leur répond qu'une carte diffusée largement engage une responsabilité particulière : elle doit aider à circuler sans encourager les détours dangereux. Les collectivités partenaires ont promis de traiter rapidement les observations signalant des clôtures nouvelles ou des portions érodées. Le collectif évaluera la qualité du projet non au nombre de kilomètres ajoutés, mais à la fiabilité des itinéraires proposés aux marcheurs.","question":"Quel est le principal motif de la séparation entre itinéraires publiés et tracés provisoires ?","options":["Éviter de recommander des passages dont la sécurité reste incertaine","Réserver les parcours les plus attrayants aux seuls contributeurs","Réduire la fréquence des échanges avec les collectivités locales","Masquer les erreurs anciennes pour améliorer artificiellement les statistiques"],"correct":"A","explanation":"Les parcours non vérifiés peuvent traverser des secteurs risqués ou privés.","semantic":{"concept":"trail-map-unverified-private-layer","evidence":"withhold-unverified-routes-for-safety"},"section":"long","group":"Cartographie participative"},{"number":38,"points":1,"passage":"LE RETOUR DES ATELIERS DE CARTOGRAPHIE PARTICIPATIVE\nUn collectif de randonneurs a entrepris de mettre à jour les chemins d'une zone rurale, où les cartes numériques comportaient plusieurs passages impraticables. Les bénévoles ont commencé par relever les obstacles sur le terrain. Ils ont rapidement constaté que les chemins les plus utilisés n'étaient pas toujours les plus sûrs, notamment lorsqu'ils traversaient des propriétés privées ou des terrains fragilisés après des pluies. Publier immédiatement toutes les traces aurait pu attirer davantage de marcheurs dans des secteurs qui nécessitaient encore des vérifications.\n\nLe collectif a donc créé deux niveaux d'information : les parcours confirmés sont visibles sur la carte destinée au public, tandis que les tracés en cours de vérification restent dans un espace de travail réservé aux contributeurs. Cette séparation a déplu à certains passionnés de données ouvertes, qui craignaient que les corrections n'arrivent trop lentement. L'équipe leur répond qu'une carte diffusée largement engage une responsabilité particulière : elle doit aider à circuler sans encourager les détours dangereux. Les collectivités partenaires ont promis de traiter rapidement les observations signalant des clôtures nouvelles ou des portions érodées. Le collectif évaluera la qualité du projet non au nombre de kilomètres ajoutés, mais à la fiabilité des itinéraires proposés aux marcheurs.","question":"Sur quel critère la réussite du projet sera-t-elle d'abord appréciée ?","options":["Le volume total de données brutes mises en ligne chaque jour","La rapidité avec laquelle tous les chemins sont publiés sans examen","La confiance que les marcheurs peuvent accorder aux parcours proposés","Le nombre de contributeurs possédant leur propre logiciel de cartographie"],"correct":"C","explanation":"Les responsables privilégient la fiabilité des itinéraires plutôt que le nombre de kilomètres ajoutés.","semantic":{"concept":"trail-map-reliability-over-volume","evidence":"quality-metric-route-reliability"},"section":"long","group":"Cartographie participative"},{"number":39,"points":1,"passage":"LES FESTIVALS ET LEUR EMPREINTE SONORE\nÀ l'approche de l'été, plusieurs villes débattent des concerts en plein air organisés près des quartiers résidentiels. Les organisateurs soulignent leur contribution à la vie culturelle et aux commerces. Les habitants, eux, ne réagissent pas uniquement au niveau maximal des décibels : des nuisances moins fortes mais répétées tard dans la soirée peuvent devenir plus difficiles à supporter qu'un événement ponctuel particulièrement bruyant. Une étude municipale recommande donc de prendre en compte la durée, les horaires et la répétition des spectacles, en plus de la puissance sonore mesurée.\n\nPlutôt que de déplacer l'ensemble des concerts en périphérie, la ville a proposé un calendrier partagé limitant les soirées successives et imposant des heures de fin différentes selon les sites. Les professionnels du spectacle préféraient initialement une règle unique pour tous les lieux, plus simple à appliquer. Des associations de riverains redoutaient au contraire qu'un calendrier souple ne soit impossible à contrôler. Le projet prévoit alors la publication des horaires autorisés et d'un bilan des plaintes après chaque événement. Il ne prétend pas supprimer tout désagrément : la municipalité souhaite rendre les arbitrages compréhensibles et ajustables, sans opposer mécaniquement culture et tranquillité.","question":"Pourquoi l'étude ne retient-elle pas uniquement le niveau sonore maximal ?","options":["Parce que les appareils de mesure ne fonctionnent pas après la tombée du jour","Parce que les habitants ignorent entièrement l'intensité des événements","Parce que les nuisances disparaissent dès que le concert est de courte durée","Parce que la répétition et l'horaire influencent aussi la gêne ressentie"],"correct":"D","explanation":"La gêne dépend notamment de la durée et des horaires, pas seulement des pics mesurés.","semantic":{"concept":"sound-impact-repetition-timing","evidence":"noise-affected-by-duration-and-hour"},"section":"long","group":"Festivals et bruit"},{"number":40,"points":1,"passage":"LES FESTIVALS ET LEUR EMPREINTE SONORE\nÀ l'approche de l'été, plusieurs villes débattent des concerts en plein air organisés près des quartiers résidentiels. Les organisateurs soulignent leur contribution à la vie culturelle et aux commerces. Les habitants, eux, ne réagissent pas uniquement au niveau maximal des décibels : des nuisances moins fortes mais répétées tard dans la soirée peuvent devenir plus difficiles à supporter qu'un événement ponctuel particulièrement bruyant. Une étude municipale recommande donc de prendre en compte la durée, les horaires et la répétition des spectacles, en plus de la puissance sonore mesurée.\n\nPlutôt que de déplacer l'ensemble des concerts en périphérie, la ville a proposé un calendrier partagé limitant les soirées successives et imposant des heures de fin différentes selon les sites. Les professionnels du spectacle préféraient initialement une règle unique pour tous les lieux, plus simple à appliquer. Des associations de riverains redoutaient au contraire qu'un calendrier souple ne soit impossible à contrôler. Le projet prévoit alors la publication des horaires autorisés et d'un bilan des plaintes après chaque événement. Il ne prétend pas supprimer tout désagrément : la municipalité souhaite rendre les arbitrages compréhensibles et ajustables, sans opposer mécaniquement culture et tranquillité.","question":"Quel compromis les responsables cherchent-ils à établir ?","options":["Appliquer sans exception les mêmes heures à chaque manifestation","Adapter les contraintes selon les lieux et suivre publiquement leurs effets","Reporter tous les concerts jusqu'à disparition de toute opposition","Confier exclusivement aux organisateurs le contrôle des plaintes"],"correct":"B","explanation":"Le calendrier tient compte des sites et prévoit un suivi public des horaires et plaintes.","semantic":{"concept":"sound-governance-site-specific-transparent","evidence":"tailored-calendar-with-public-reporting"},"section":"long","group":"Festivals et bruit"}]}$bank3$::jsonb;
 if exists(select 1 from academy_tef_reading.papers where id='tef-reading-03' and version='tef-reading-2026-11-original-03-v1' and content<>paper) then raise exception 'Cannot modify published TEF Reading paper version tef-reading-03';end if;
 insert into academy_tef_reading.papers(id,version,content) values('tef-reading-03','tef-reading-2026-11-original-03-v1',paper) on conflict do nothing;

 paper := $bank4${"id":"tef-reading-04","version":"tef-reading-2026-11-original-04-v1","title":"TEF Canada · Compréhension écrite · Test 04","seconds":3600,"maxPoints":40,"questions":[{"number":1,"points":1,"passage":"🌊 PHARE DES VENTS\nPour préserver l'escalier historique, l'accès à la lanterne du phare se fait désormais par petits groupes de huit. Le billet inclut la visite du rez-de-chaussée ; la montée nécessite une réservation de créneau supplémentaire sans frais.","question":"Qu'exige la visite de la partie supérieure du phare ?","options":["Un supplément de prix à payer à l'arrivée","Une inscription à un groupe de plus de huit visiteurs","Un créneau réservé, même avec un billet d'entrée","Une visite préalable guidée du musée voisin"],"correct":"C","explanation":"Le billet couvre le bâtiment, mais la montée est conditionnée à un créneau spécifique gratuit.","semantic":{"concept":"historic-lighthouse-lantern-timeslot","evidence":"included-ticket-extra-reservation"},"media":{"kind":"illustration","scene":"lighthouse","heading":"Visite du phare"}},{"number":2,"points":1,"passage":"🎨 GALERIE DES ATELIERS\nLes œuvres de l'exposition temporaire ne peuvent être photographiées qu'à l'aide d'un appareil sans flash. Les prises de vue destinées à une publication commerciale nécessitent l'autorisation écrite de la galerie avant leur diffusion.","question":"Quel usage demande une autorisation particulière ?","options":["La publication de photographies à des fins commerciales","La prise d'une photographie privée sans flash","La consultation du catalogue de l'exposition","L'entrée dans une salle d'œuvres temporaires"],"correct":"A","explanation":"Le texte distingue les photos personnelles sans flash des publications commerciales soumises à accord.","semantic":{"concept":"gallery-commercial-photo-permission","evidence":"commercial-distribution-written-consent"},"media":{"kind":"notice","icon":"🖼️","heading":"Photographies · conditions","accent":"#9c5285"}},{"number":3,"points":1,"passage":"🌲 SENTIER DU BELVÉDÈRE\nUne portion du chemin traverse un secteur où nichent des oiseaux protégés. Entre avril et juillet, les visiteurs doivent rester sur la passerelle balisée. Le belvédère demeure accessible toute l'année par l'itinéraire inférieur.","question":"Quelle restriction est saisonnière ?","options":["La fermeture du belvédère pendant quatre mois","L'interdiction de se promener sur l'itinéraire inférieur","L'accès au site réservé aux guides agréés","L'obligation d'emprunter la passerelle dans une zone précise"],"correct":"D","explanation":"Le passage par la passerelle est imposé durant la période de nidification.","semantic":{"concept":"nesting-season-boardwalk-rule","evidence":"seasonal-route-not-whole-site"},"media":{"kind":"notice","icon":"🦉","heading":"Protection des oiseaux","accent":"#357c5d"}},{"number":4,"points":1,"passage":"📻 MÉDIATHÈQUE SONORE\nLes personnes malvoyantes peuvent emprunter un lecteur audio pour trois semaines. L'appareil se retire uniquement à l'accueil sur présentation de la carte de la médiathèque, mais peut être rendu dans n'importe quelle antenne du réseau.","question":"Qu'est-ce qui distingue le retrait du retour de l'appareil ?","options":["Seul le retour exige de présenter une pièce d'identité","Seul le retrait doit s'effectuer à un guichet précis","Le retrait peut se faire dans toute antenne du réseau","Les deux démarches nécessitent un rendez-vous préalable"],"correct":"B","explanation":"L'emprunt débute à l'accueil, mais l'objet peut être rendu dans n'importe quelle antenne.","semantic":{"concept":"accessible-audio-player-pickup-return-asymmetry","evidence":"pick-up-restricted-returns-networkwide"},"media":{"kind":"notice","icon":"🎧","heading":"Prêt de lecteurs audio","accent":"#3b7cb5"}},{"number":5,"points":1,"passage":"🪴 SERRE EXPÉRIMENTALE\nLa visite publique du dimanche comprend une présentation des cultures sous verre. Pour des raisons sanitaires, les visiteurs ne peuvent pas toucher les plants. Une table d'observation permet néanmoins d'examiner les échantillons prélevés par l'équipe.","question":"Quelle activité reste possible pendant la visite ?","options":["Manipuler librement les plantes cultivées sous verre","Observer des échantillons préparés par le personnel","Prélever soi-même des feuilles dans la serre","Participer à une expérience en semant de nouvelles graines"],"correct":"B","explanation":"La manipulation des plants est interdite, mais des échantillons sont mis à disposition pour observation.","semantic":{"concept":"experimental-greenhouse-observe-no-touch","evidence":"samples-staff-prepared-not-live-handling"},"media":{"kind":"illustration","scene":"greenhouse","heading":"Visite de la serre"}},{"number":6,"points":1,"passage":"🏊 BASSIN MUNICIPAL\nLes inscriptions aux cours de natation sont ouvertes aux résidents et aux non-résidents. Les premiers bénéficient d'une priorité jusqu'au 15 septembre ; les places restantes seront ensuite attribuées selon l'ordre d'arrivée des demandes.","question":"Comment les demandes seront-elles traitées après le 15 septembre ?","options":["En conservant sans limite la priorité des résidents","En réservant l'ensemble des créneaux aux non-résidents","Au moyen d'un tirage au sort entre les anciens inscrits","Selon leur arrivée, pour les places encore disponibles"],"correct":"D","explanation":"Après la période prioritaire, les places restantes sont distribuées dans l'ordre des demandes.","semantic":{"concept":"resident-preference-expiration","evidence":"after-deadline-first-come-remaining"},"media":{"kind":"notice","icon":"🏊","heading":"Inscriptions piscine","accent":"#1a839c"}},{"number":7,"points":1,"passage":"🧪 FOIRE SCIENTIFIQUE\nLes démonstrations débuteront toutes les demi-heures, sans inscription. Pour accéder au laboratoire temporaire, un adulte devra accompagner les visiteurs de moins de 14 ans. Les expériences projetées sur écran resteront ouvertes à tous.","question":"Quelle activité comporte une condition liée à l'âge ?","options":["L'entrée dans le laboratoire temporaire","Le visionnage des expériences sur écran","L'accès général à la foire et aux stands","L'assistance aux présentations en salle principale"],"correct":"A","explanation":"Les moins de quatorze ans doivent être accompagnés dans le laboratoire, pas pour les projections.","semantic":{"concept":"science-fair-underage-lab-accompaniment","evidence":"only-physical-lab-age-rule"},"media":{"kind":"notice","icon":"🧫","heading":"Espace laboratoire","accent":"#7d63ae"}},{"number":8,"points":1,"passage":"Les résultats sont encourageants, ________ ils ne permettent pas encore de conclure à une amélioration durable.","question":"Quel connecteur exprime la réserve de l'auteur ?","options":["d'ailleurs","par conséquent","toutefois","de surcroît"],"correct":"C","explanation":"« Toutefois » introduit une nuance opposée aux résultats encourageants.","semantic":{"concept":"cautious-concession-connector","evidence":"promising-but-insufficient"},"section":"cloze"},{"number":9,"points":1,"passage":"Ce musée est l'un des rares établissements qui ________ encore cette technique artisanale.","question":"Quelle forme verbale est grammaticalement attendue ?","options":["pratique","pratiqueront","pratiquaient","pratiquent"],"correct":"D","explanation":"Avec « l'un des rares établissements qui », le relatif reprend « établissements » au pluriel.","semantic":{"concept":"relative-plural-agreement","evidence":"establishments-pratiquent"},"section":"cloze"},{"number":10,"points":1,"passage":"Nous vous transmettrons le dossier, sous réserve qu'il ________ complet lors du contrôle.","question":"Quelle forme convient après « sous réserve que » ?","options":["est","soit","sera","était"],"correct":"B","explanation":"La locution de condition exige le subjonctif présent.","semantic":{"concept":"sous-reserve-subjunctive","evidence":"conditional-subjunctive-soit"},"section":"cloze"},{"number":11,"points":1,"passage":"La mesure envisagée pourrait ________ des conséquences imprévues pour les petits commerces.","question":"Quel verbe forme l'expression la plus naturelle ?","options":["entraîner","prévenir","dissiper","contourner"],"correct":"A","explanation":"« Entraîner des conséquences » signifie les provoquer, parfois involontairement.","semantic":{"concept":"cause-unforeseen-consequences-collocation","evidence":"entrainer-des-consequences"},"section":"cloze"},{"number":12,"points":1,"passage":"PROTOCOLE DE RECHERCHE\nPour pouvoir comparer les expériences, les équipes doivent ________ (1) les conditions de mesure. Tout écart significatif sera ensuite ________ (2) dans le compte rendu plutôt que dissimulé.","question":"Quel verbe convient à l'espace (1) ?","options":["accélérer","justifier","harmoniser","alterner"],"correct":"C","explanation":"Harmoniser les conditions permet de rendre les résultats des équipes comparables.","semantic":{"concept":"research-standardize-measurements","evidence":"comparable-measurement-conditions"},"section":"paired-cloze","group":"Protocole scientifique"},{"number":13,"points":1,"passage":"PROTOCOLE DE RECHERCHE\nPour pouvoir comparer les expériences, les équipes doivent ________ (1) les conditions de mesure. Tout écart significatif sera ensuite ________ (2) dans le compte rendu plutôt que dissimulé.","question":"Quel verbe convient à l'espace (2) ?","options":["signalé","corrigé","inventé","attribué"],"correct":"A","explanation":"Le protocole exige de signaler les écarts plutôt que de les masquer.","semantic":{"concept":"research-disclose-deviation","evidence":"document-departure-in-report"},"section":"paired-cloze","group":"Protocole scientifique"},{"number":14,"points":1,"passage":"CHANTIER DE RESTAURATION\nAvant de nettoyer la fresque, l'équipe procédera à un examen ________ (1) afin d'établir son état initial. Les produits seront ensuite testés sur une petite zone pour vérifier leur ________ (2) avec les pigments.","question":"Quel adjectif convient à l'espace (1) ?","options":["immédiat","préalable","progressif","facultatif"],"correct":"B","explanation":"L'examen a lieu avant le nettoyage pour établir un état initial.","semantic":{"concept":"conservation-baseline-precheck","evidence":"pre-treatment-condition-assessment"},"section":"paired-cloze","group":"Restauration d'une fresque"},{"number":15,"points":1,"passage":"CHANTIER DE RESTAURATION\nAvant de nettoyer la fresque, l'équipe procédera à un examen ________ (1) afin d'établir son état initial. Les produits seront ensuite testés sur une petite zone pour vérifier leur ________ (2) avec les pigments.","question":"Quel nom convient à l'espace (2) ?","options":["durabilité","visibilité","popularité","compatibilité"],"correct":"D","explanation":"Les tests vérifient que les produits n'abîmeront pas les pigments.","semantic":{"concept":"conservation-chemical-compatibility","evidence":"test-cleaner-on-small-area"},"section":"paired-cloze","group":"Restauration d'une fresque"},{"number":16,"points":1,"passage":"PLAN DE CONTINUITÉ\nL'association souhaite ________ (1) ses activités en cas de panne prolongée d'Internet. Elle conservera donc une copie locale des documents essentiels, accessible même si le réseau est ________ (2).","question":"Quel verbe convient à l'espace (1) ?","options":["suspendre","externaliser","maintenir","centraliser"],"correct":"C","explanation":"La copie locale permet de continuer l'activité pendant une interruption de connexion.","semantic":{"concept":"offline-business-continuity","evidence":"keep-services-during-outage"},"section":"paired-cloze","group":"Continuité d'activité"},{"number":17,"points":1,"passage":"PLAN DE CONTINUITÉ\nL'association souhaite ________ (1) ses activités en cas de panne prolongée d'Internet. Elle conservera donc une copie locale des documents essentiels, accessible même si le réseau est ________ (2).","question":"Quel participe convient à l'espace (2) ?","options":["indisponible","protégé","sécurisé","surchargé"],"correct":"A","explanation":"Il s'agit d'accéder aux fichiers lorsque le réseau ne fonctionne pas.","semantic":{"concept":"local-copy-no-network","evidence":"access-even-offline"},"section":"paired-cloze","group":"Continuité d'activité"},{"number":18,"points":1,"passage":"","question":"Quelle offre correspond à une étudiante qui dispose uniquement des mercredis après-midi, cherche un poste payé et peut se déplacer sans voiture ?","options":["Offre 1","Offre 3","Offre 4","Offre 2"],"correct":"D","explanation":"L'offre 2 réunit le mercredi après-midi, la rémunération et un lieu accessible en transports publics.","semantic":{"concept":"paid-wednesday-transit-access","evidence":"three-conditions-paid-wed-transport"},"section":"offers","media":{"kind":"offers","heading":"Annonces · Activités étudiantes","items":["Centre de loisirs : mercredi après-midi, bénévolat, bus devant l'établissement.","Maison des langues : accueil payé le mercredi après-midi, proche du métro.","Bibliothèque mobile : mercredi après-midi, rémunéré, permis de conduire exigé.","Librairie : accueil rémunéré les mercredis matin, proche des transports."]}},{"number":19,"points":1,"passage":"","question":"Quelle proposition convient à un technicien qualifié disponible pour un travail de nuit, mais refusant les déplacements entre sites ?","options":["Offre 1","Offre 3","Offre 2","Offre 4"],"correct":"B","explanation":"L'offre 3 porte sur une maintenance nocturne dans un site unique et exige la qualification annoncée.","semantic":{"concept":"qualified-night-static-site-technician","evidence":"qualified-night-single-facility"},"section":"offers","media":{"kind":"offers","heading":"Recrutement · Maintenance","items":["Réseau de magasins : technicien qualifié, nuit, interventions sur quatre sites.","Hôpital local : aide de maintenance, poste fixe de jour, formation assurée.","Entrepôt logistique : technicien confirmé, équipe de nuit sur un seul site.","Service de sécurité : ronde nocturne sur plusieurs bâtiments, certificat demandé."]}},{"number":20,"points":1,"passage":"SÉRIES COMPARÉES\nCinq observations annuelles sont représentées.","question":"Quelle courbe progresse au départ, connaît un creux à la quatrième période, puis termine à un niveau supérieur à celui de la deuxième période ?","options":["Graphique 1","Graphique 2","Graphique 4","Graphique 3"],"correct":"C","explanation":"La quatrième série part de 8, atteint 18 puis 24, descend à 12 et finit à 21, au-dessus de la deuxième période.","semantic":{"concept":"rise-then-late-dip-recover-over-second","evidence":"shape-8-18-24-12-21"},"section":"charts","media":{"kind":"chart-grid","heading":"Visites des réserves naturelles","unit":"en centaines","years":["A","B","C","D","E"],"series":[[15,18,21,24,27],[29,23,19,14,10],[14,20,15,19,13],[8,18,24,12,21]]}},{"number":21,"points":1,"passage":"ÉVOLUTION DES ACTIVITÉS\nLes séries portent sur la même durée.","question":"Quel graphique montre une diminution à chaque période, à l'exception d'une reprise temporaire en quatrième position ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"A","explanation":"La première série suit 30, 22, 15, 20, 12 : seule la quatrième observation interrompt la baisse.","semantic":{"concept":"decrease-with-fourth-period-rebound","evidence":"shape-30-22-15-20-12"},"section":"charts","media":{"kind":"chart-grid","heading":"Flux d'eau surveillés","unit":"valeurs indicatives","years":["P1","P2","P3","P4","P5"],"series":[[30,22,15,20,12],[12,20,26,22,28],[16,16,20,22,23],[25,21,17,12,9]]}},{"number":22,"points":1,"passage":"CINQ RELEVÉS\nChaque graphique illustre une évolution différente.","question":"Quel graphique montre une montée régulière pendant trois périodes, suivie de deux baisses, sans retomber au niveau initial ?","options":["Graphique 1","Graphique 3","Graphique 4","Graphique 2"],"correct":"D","explanation":"La deuxième courbe monte de 9 à 16 puis 29, puis recule à 24 et 18, valeur toujours au-dessus de 9.","semantic":{"concept":"two-rises-two-falls-end-above-start","evidence":"shape-9-16-29-24-18"},"section":"charts","media":{"kind":"chart-grid","heading":"Projets participatifs soutenus","unit":"nombre de projets","years":["N-4","N-3","N-2","N-1","N"],"series":[[27,17,24,19,12],[9,16,29,24,18],[11,15,20,25,30],[14,14,28,28,14]]}},{"number":23,"points":1,"passage":"Objet : Prêt exceptionnel d'une œuvre\nMadame,\nVotre musée peut accueillir temporairement la sculpture demandée, sous réserve du respect des conditions de transport et de température mentionnées dans le dossier technique. L'assurance doit couvrir l'œuvre dès son départ de notre réserve, et non uniquement pendant son exposition chez vous. Nos équipes prépareront un constat d'état conjoint au moment du départ et du retour. Le transporteur proposé est agréé, mais la date définitive reste à confirmer selon la disponibilité de notre restauratrice. Une présentation publique de la sculpture ne sera possible qu'après validation du dispositif de sécurité du lieu d'accueil.\nDirection des collections.","question":"À partir de quel moment l'assurance doit-elle prendre effet ?","options":["Seulement après son installation dans l'espace d'exposition","Dès que la sculpture quitte la réserve d'origine","À la date où le public est autorisé à voir la sculpture","Après la signature du constat établi au retour"],"correct":"B","explanation":"La couverture doit commencer au départ de la réserve, avant l'exposition.","semantic":{"concept":"museum-loan-transit-insurance-start","evidence":"insured-from-departure"},"section":"email","group":"Prêt muséal"},{"number":24,"points":1,"passage":"Objet : Prêt exceptionnel d'une œuvre\nMadame,\nVotre musée peut accueillir temporairement la sculpture demandée, sous réserve du respect des conditions de transport et de température mentionnées dans le dossier technique. L'assurance doit couvrir l'œuvre dès son départ de notre réserve, et non uniquement pendant son exposition chez vous. Nos équipes prépareront un constat d'état conjoint au moment du départ et du retour. Le transporteur proposé est agréé, mais la date définitive reste à confirmer selon la disponibilité de notre restauratrice. Une présentation publique de la sculpture ne sera possible qu'après validation du dispositif de sécurité du lieu d'accueil.\nDirection des collections.","question":"Qu'est-ce qui empêche de fixer immédiatement la date de transport ?","options":["L'absence d'agrément du transporteur déjà sélectionné","Le manque de précision sur la valeur de l'œuvre","L'attente de confirmation de disponibilité d'une spécialiste","L'obligation d'obtenir d'abord une autorisation du public"],"correct":"C","explanation":"Le transporteur convient, mais la disponibilité de la restauratrice conditionne la date.","semantic":{"concept":"museum-loan-conservator-scheduling","evidence":"restorer-availability-date-uncertain"},"section":"email","group":"Prêt muséal"},{"number":25,"points":1,"passage":"Note aux équipes — Journée portes ouvertes du laboratoire\nLe laboratoire accueillera des classes de lycée le 14 mars. Les démonstrations proposées devront utiliser du matériel déjà validé par le responsable de sécurité. Les appareils qui ne figurent pas sur l'inventaire pourront être montrés hors tension, mais pas mis en marche. Chaque équipe présentera son activité en moins de quinze minutes afin de laisser du temps aux questions. L'accès aux espaces de stockage restera limité au personnel. Une répétition technique aura lieu la veille : elle permettra de vérifier la circulation des groupes et les besoins de projection, sans modifier le contenu scientifique des interventions.","question":"Quelle démonstration serait autorisée pour un appareil non inscrit à l'inventaire ?","options":["Le présenter sans le faire fonctionner","Le faire fonctionner sous surveillance d'un professeur","Le remplacer après validation par les élèves","Le mettre en marche uniquement lors de la répétition"],"correct":"A","explanation":"Les appareils absents de l'inventaire peuvent être exposés, mais restent hors tension.","semantic":{"concept":"lab-nonapproved-equipment-display-off","evidence":"unlisted-device-no-power"},"section":"email","group":"Portes ouvertes laboratoire"},{"number":26,"points":1,"passage":"Note aux équipes — Journée portes ouvertes du laboratoire\nLe laboratoire accueillera des classes de lycée le 14 mars. Les démonstrations proposées devront utiliser du matériel déjà validé par le responsable de sécurité. Les appareils qui ne figurent pas sur l'inventaire pourront être montrés hors tension, mais pas mis en marche. Chaque équipe présentera son activité en moins de quinze minutes afin de laisser du temps aux questions. L'accès aux espaces de stockage restera limité au personnel. Une répétition technique aura lieu la veille : elle permettra de vérifier la circulation des groupes et les besoins de projection, sans modifier le contenu scientifique des interventions.","question":"Quel est l'objectif de la répétition prévue ?","options":["Changer les résultats des expériences présentées","Évaluer les connaissances des lycéens invités","Vérifier l'organisation pratique de la visite","Réduire les questions autorisées pendant les séances"],"correct":"C","explanation":"La répétition sert à contrôler les déplacements et projections, pas le contenu scientifique.","semantic":{"concept":"lab-open-house-logistical-dry-run","evidence":"group-flow-projection-check"},"section":"email","group":"Portes ouvertes laboratoire"},{"number":27,"points":1,"passage":"Information aux riverains — Suivi de la qualité du ruisseau\nDepuis février, des capteurs mesurent la température et l'oxygène de l'eau à différents points du ruisseau. Les résultats bruts sont consultables en ligne, mais ils doivent être interprétés avec précaution : les variations quotidiennes peuvent être importantes même en l'absence de pollution. Une équipe de chercheurs publiera chaque trimestre une synthèse tenant compte de la météo et du débit. Les habitants peuvent signaler une odeur ou une coloration inhabituelle à l'adresse dédiée. Ces signalements serviront à orienter les vérifications de terrain ; ils ne seront pas affichés automatiquement comme des incidents confirmés sur la carte publique.","question":"Pourquoi les chiffres disponibles en ligne ne suffisent-ils pas à établir une pollution ?","options":["Les capteurs ne relèvent que la présence de déchets visibles","L'équipe refuse de comparer les mesures à la météo","Les résultats ne sont accessibles qu'après un contrôle annuel","Les fluctuations normales peuvent expliquer certaines valeurs observées"],"correct":"D","explanation":"Les variations peuvent venir des cycles naturels, d'où l'analyse contextuelle.","semantic":{"concept":"water-sensor-raw-data-context","evidence":"daily-variation-not-proof-pollution"},"section":"email","group":"Surveillance d'un ruisseau"},{"number":28,"points":1,"passage":"Information aux riverains — Suivi de la qualité du ruisseau\nDepuis février, des capteurs mesurent la température et l'oxygène de l'eau à différents points du ruisseau. Les résultats bruts sont consultables en ligne, mais ils doivent être interprétés avec précaution : les variations quotidiennes peuvent être importantes même en l'absence de pollution. Une équipe de chercheurs publiera chaque trimestre une synthèse tenant compte de la météo et du débit. Les habitants peuvent signaler une odeur ou une coloration inhabituelle à l'adresse dédiée. Ces signalements serviront à orienter les vérifications de terrain ; ils ne seront pas affichés automatiquement comme des incidents confirmés sur la carte publique.","question":"Comment les observations des habitants seront-elles utilisées ?","options":["Pour modifier automatiquement les résultats des capteurs","Pour guider des contrôles sans être assimilées d'emblée à des faits établis","Pour remplacer chaque analyse trimestrielle par un témoignage","Pour publier immédiatement toutes les alertes comme confirmées"],"correct":"B","explanation":"Les signalements orientent les vérifications, sans valoir une confirmation.","semantic":{"concept":"citizen-water-report-triage","evidence":"reports-trigger-checks-not-confirmation"},"section":"email","group":"Surveillance d'un ruisseau"},{"number":29,"points":1,"passage":"Objet : Ateliers d'écriture en résidence\nBonjour,\nNous vous proposons de participer à notre résidence d'écriture du 6 au 20 juillet. Le logement et l'accès aux espaces de travail sont pris en charge. Les frais de voyage restent à votre charge, sauf pour les participants bénéficiant d'une aide accordée sur dossier. La résidence prévoit deux rencontres publiques, mais aucune obligation de présenter une œuvre achevée. Un texte bref sera toutefois demandé à la fin du séjour pour rendre compte des recherches engagées. Les candidatures à l'aide au transport sont étudiées séparément et doivent nous parvenir avant le 1er mai. Merci de nous répondre d'ici la semaine prochaine concernant votre participation.\nLa coordination.","question":"Quel engagement de production est réellement demandé aux résidents ?","options":["Achever obligatoirement un manuscrit prêt à publier","Présenter chaque jour un chapitre au public","Remettre uniquement les notes de frais de voyage","Remettre un court bilan de travail, même sans œuvre terminée"],"correct":"D","explanation":"La résidence n'exige pas d'œuvre finie mais demande un bref texte de bilan.","semantic":{"concept":"writing-residency-progress-note-not-final-work","evidence":"brief-research-accountability"},"section":"email","group":"Résidence d'écriture"},{"number":30,"points":1,"passage":"Objet : Ateliers d'écriture en résidence\nBonjour,\nNous vous proposons de participer à notre résidence d'écriture du 6 au 20 juillet. Le logement et l'accès aux espaces de travail sont pris en charge. Les frais de voyage restent à votre charge, sauf pour les participants bénéficiant d'une aide accordée sur dossier. La résidence prévoit deux rencontres publiques, mais aucune obligation de présenter une œuvre achevée. Un texte bref sera toutefois demandé à la fin du séjour pour rendre compte des recherches engagées. Les candidatures à l'aide au transport sont étudiées séparément et doivent nous parvenir avant le 1er mai. Merci de nous répondre d'ici la semaine prochaine concernant votre participation.\nLa coordination.","question":"Qui peut obtenir une prise en charge du déplacement ?","options":["Tous les participants dès la confirmation d'inscription","Les personnes ayant obtenu une aide sur demande spécifique","Seulement les auteurs ayant terminé leur manuscrit","Les personnes présentes aux deux rencontres publiques"],"correct":"B","explanation":"Les frais de transport ne sont couverts que dans le cadre d'une aide accordée sur dossier.","semantic":{"concept":"residency-travel-grant-application","evidence":"transport-only-individual-grant"},"section":"email","group":"Résidence d'écriture"},{"number":31,"points":1,"passage":"Note de service — Expérimentation d'un accueil sans rendez-vous\nÀ compter du 2 septembre, notre antenne testera deux matinées hebdomadaires d'accueil sans rendez-vous pour les démarches simples. Les dossiers complexes continueront à nécessiter une réservation. Le test durera six semaines et sera accompagné d'un comptage des temps d'attente et du nombre de dossiers traités. Les usagers qui se présentent sans rendez-vous pour une démarche complexe recevront de l'aide pour réserver un créneau, mais ne seront pas reçus le jour même. Les résultats de l'essai seront discutés avec les agents avant toute éventuelle généralisation à d'autres antennes.","question":"Que propose-t-on à une personne venue sans rendez-vous pour un dossier complexe ?","options":["Une aide à réserver une consultation ultérieure","Un examen complet de sa demande le jour même","Un traitement prioritaire pendant la matinée sans rendez-vous","Une dispense définitive des documents nécessaires"],"correct":"A","explanation":"Les demandes complexes restent sur rendez-vous ; le personnel aide à en réserver un.","semantic":{"concept":"walkin-complex-case-booking-help","evidence":"complex-no-same-day-walkin"},"section":"email","group":"Accueil administratif"},{"number":32,"points":1,"passage":"Note de service — Expérimentation d'un accueil sans rendez-vous\nÀ compter du 2 septembre, notre antenne testera deux matinées hebdomadaires d'accueil sans rendez-vous pour les démarches simples. Les dossiers complexes continueront à nécessiter une réservation. Le test durera six semaines et sera accompagné d'un comptage des temps d'attente et du nombre de dossiers traités. Les usagers qui se présentent sans rendez-vous pour une démarche complexe recevront de l'aide pour réserver un créneau, mais ne seront pas reçus le jour même. Les résultats de l'essai seront discutés avec les agents avant toute éventuelle généralisation à d'autres antennes.","question":"Quel critère contribuera à juger l'expérimentation ?","options":["Le nombre de réservations annulées dans les autres services","La satisfaction recueillie uniquement auprès des directeurs","La durée des attentes et les dossiers effectivement traités","La variation des loyers commerciaux dans le quartier"],"correct":"C","explanation":"Le dispositif prévoit explicitement de mesurer l'attente et le volume de dossiers.","semantic":{"concept":"walkin-trial-wait-time-throughput","evidence":"waiting-time-and-cases-processed"},"section":"email","group":"Accueil administratif"},{"number":33,"points":1,"passage":"COMPTER LES INSECTES SANS CONFONDRE PRÉSENCE ET ABONDANCE\nDans les jardins urbains, des bénévoles photographient les insectes qu'ils rencontrent afin d'aider les scientifiques à suivre les changements de biodiversité. Les observations se multiplient chaque printemps. Pourtant, une hausse du nombre de photos ne signifie pas nécessairement que les insectes deviennent plus nombreux : elle peut traduire une participation accrue des habitants ou une météo plus favorable aux sorties. Pour comparer les années, les chercheurs demandent désormais aux contributeurs d'indiquer la durée de leur observation et le type de lieu visité.\n\nCette évolution a provoqué des réactions contrastées. Certains bénévoles redoutent que les fiches supplémentaires transforment une activité agréable en travail administratif. L'équipe scientifique a donc conçu un formulaire plus court et des séances d'explication destinées aux nouveaux participants. Elle préfère recevoir moins de données mais mieux documentées, plutôt qu'un grand volume de signalements impossible à interpréter. Les chercheurs reconnaissent également que les jardins accessibles sont observés plus souvent que les terrains privés, ce qui peut fausser la représentation de certains habitats. Leur projet n'est pas de calculer un chiffre exact pour chaque espèce, mais d'identifier des tendances robustes en rendant explicites les limites de l'échantillon.","question":"Pourquoi une augmentation des photographies ne prouve-t-elle pas une hausse de population des insectes ?","options":["Les photographies des années précédentes sont systématiquement détruites","Les espèces urbaines se déplacent toujours vers les mêmes jardins","Les bénévoles ne photographient que les insectes déjà disparus","L'effort d'observation peut varier indépendamment de la population réelle"],"correct":"D","explanation":"Le nombre de participants, le temps passé et la météo influencent les photos comptées.","semantic":{"concept":"citizen-science-sampling-effort","evidence":"more-photos-not-more-animals"},"section":"long","group":"Insectes observés"},{"number":34,"points":1,"passage":"COMPTER LES INSECTES SANS CONFONDRE PRÉSENCE ET ABONDANCE\nDans les jardins urbains, des bénévoles photographient les insectes qu'ils rencontrent afin d'aider les scientifiques à suivre les changements de biodiversité. Les observations se multiplient chaque printemps. Pourtant, une hausse du nombre de photos ne signifie pas nécessairement que les insectes deviennent plus nombreux : elle peut traduire une participation accrue des habitants ou une météo plus favorable aux sorties. Pour comparer les années, les chercheurs demandent désormais aux contributeurs d'indiquer la durée de leur observation et le type de lieu visité.\n\nCette évolution a provoqué des réactions contrastées. Certains bénévoles redoutent que les fiches supplémentaires transforment une activité agréable en travail administratif. L'équipe scientifique a donc conçu un formulaire plus court et des séances d'explication destinées aux nouveaux participants. Elle préfère recevoir moins de données mais mieux documentées, plutôt qu'un grand volume de signalements impossible à interpréter. Les chercheurs reconnaissent également que les jardins accessibles sont observés plus souvent que les terrains privés, ce qui peut fausser la représentation de certains habitats. Leur projet n'est pas de calculer un chiffre exact pour chaque espèce, mais d'identifier des tendances robustes en rendant explicites les limites de l'échantillon.","question":"Quelle concession l'équipe fait-elle pour préserver la participation des bénévoles ?","options":["Abandonner toute précision sur le temps passé dans chaque jardin","Simplifier la collecte tout en conservant les informations indispensables","Réserver les enquêtes exclusivement aux spécialistes rémunérés","Supprimer la possibilité de prendre des photographies"],"correct":"B","explanation":"Le formulaire raccourci cherche à maintenir la qualité des données sans décourager les volontaires.","semantic":{"concept":"citizen-science-shorter-structured-form","evidence":"short-form-quality-vs-participation"},"section":"long","group":"Insectes observés"},{"number":35,"points":1,"passage":"LE PARTAGE D'ÉNERGIE À L'ÉCHELLE D'UN IMMEUBLE\nDans certaines copropriétés, l'électricité produite par des panneaux solaires installés sur le toit est répartie entre plusieurs logements. Ce modèle peut intéresser des habitants qui n'ont pas la possibilité d'installer leur propre équipement. Cependant, les besoins des ménages ne coïncident pas toujours avec les heures de production. Un appartement vacant pendant la journée consomme peu au moment où les panneaux produisent le plus, tandis que d'autres ménages utilisent davantage d'électricité le soir.\n\nUne expérimentation a tenté d'améliorer la répartition en incitant les résidents volontaires à déplacer certains usages, comme le fonctionnement du lave-linge, vers les heures ensoleillées. Les résultats ont été encourageants, mais les organisateurs refusent d'en conclure que tous les immeubles pourraient reproduire les mêmes économies. Le dispositif suppose une entente sur l'entretien, une gestion transparente des contributions financières et une règle de partage comprise par chacun. Les copropriétaires souhaitent maintenant publier des bilans distinguant production totale, consommation collective et économies effectivement réalisées par logement. Selon les responsables, la confiance dépend autant de la lisibilité des comptes que de la performance des panneaux eux-mêmes.","question":"Quelle limite pratique du partage solaire est soulignée ?","options":["Les horaires de consommation ne correspondent pas toujours à ceux de production","Les panneaux produisent nécessairement davantage la nuit","Les logements doivent tous disposer d'un toit individuel","La production solaire ne peut jamais être utilisée dans un immeuble"],"correct":"A","explanation":"Le moment où l'électricité est générée ne coïncide pas toujours avec les besoins des habitants.","semantic":{"concept":"solar-shared-load-production-mismatch","evidence":"daytime-generation-evening-use"},"section":"long","group":"Énergie partagée"},{"number":36,"points":1,"passage":"LE PARTAGE D'ÉNERGIE À L'ÉCHELLE D'UN IMMEUBLE\nDans certaines copropriétés, l'électricité produite par des panneaux solaires installés sur le toit est répartie entre plusieurs logements. Ce modèle peut intéresser des habitants qui n'ont pas la possibilité d'installer leur propre équipement. Cependant, les besoins des ménages ne coïncident pas toujours avec les heures de production. Un appartement vacant pendant la journée consomme peu au moment où les panneaux produisent le plus, tandis que d'autres ménages utilisent davantage d'électricité le soir.\n\nUne expérimentation a tenté d'améliorer la répartition en incitant les résidents volontaires à déplacer certains usages, comme le fonctionnement du lave-linge, vers les heures ensoleillées. Les résultats ont été encourageants, mais les organisateurs refusent d'en conclure que tous les immeubles pourraient reproduire les mêmes économies. Le dispositif suppose une entente sur l'entretien, une gestion transparente des contributions financières et une règle de partage comprise par chacun. Les copropriétaires souhaitent maintenant publier des bilans distinguant production totale, consommation collective et économies effectivement réalisées par logement. Selon les responsables, la confiance dépend autant de la lisibilité des comptes que de la performance des panneaux eux-mêmes.","question":"Pourquoi les responsables veulent-ils détailler les bilans par logement ?","options":["Pour garantir exactement les mêmes économies à tous les appartements","Pour éviter d'expliquer les règles financières du dispositif","Pour distinguer les bénéfices réellement obtenus des volumes globaux annoncés","Pour démontrer que l'entretien des panneaux est devenu inutile"],"correct":"C","explanation":"La publication détaillée aide à comprendre la répartition et les économies réelles.","semantic":{"concept":"solar-transparent-individual-savings","evidence":"separate-total-generation-from-household-benefit"},"section":"long","group":"Énergie partagée"},{"number":37,"points":1,"passage":"À QUI APPARTIENT L'HISTOIRE D'UN OBJET DE MUSÉE ?\nUne collection régionale conserve depuis plus d'un siècle des objets acquis lors d'expéditions anciennes. Les fiches d'inventaire indiquent souvent la date d'entrée au musée, mais fournissent peu de précisions sur les conditions de leur acquisition. Des chercheurs ont entrepris de reconstituer ces parcours en consultant des correspondances, des photographies et des archives conservées ailleurs. Leur travail révèle des situations très diverses, allant du don documenté à des transferts dont les circonstances restent controversées.\n\nLe musée a choisi de publier les résultats progressivement, y compris lorsque les recherches sont incomplètes. Il présente désormais certaines pièces avec plusieurs points de vue, en précisant ce qui est attesté et ce qui demeure débattu. Quelques visiteurs craignent que cette approche rende les cartels difficiles à lire. La direction répond que l'incertitude fait partie des connaissances disponibles et qu'une formule brève ne doit pas transformer une hypothèse en fait établi. Le musée dialogue également avec des représentants des communautés concernées afin de mieux comprendre les usages originels de certains objets. Ce dialogue n'apporte pas automatiquement une réponse juridique unique, mais il peut conduire à revoir les descriptions, les conditions d'exposition et les priorités de recherche.","question":"En quoi la présentation des objets a-t-elle changé ?","options":["Elle remplace chaque notice par une explication juridique définitive","Elle distingue davantage les faits établis des interprétations discutées","Elle écarte toutes les archives dont les informations restent partielles","Elle présente les acquisitions anciennes comme uniformément documentées"],"correct":"B","explanation":"Le musée expose plusieurs perspectives et précise les zones d'incertitude.","semantic":{"concept":"museum-provenance-facts-vs-uncertainty","evidence":"show-attested-and-disputed-interpretations"},"section":"long","group":"Provenance muséale"},{"number":38,"points":1,"passage":"À QUI APPARTIENT L'HISTOIRE D'UN OBJET DE MUSÉE ?\nUne collection régionale conserve depuis plus d'un siècle des objets acquis lors d'expéditions anciennes. Les fiches d'inventaire indiquent souvent la date d'entrée au musée, mais fournissent peu de précisions sur les conditions de leur acquisition. Des chercheurs ont entrepris de reconstituer ces parcours en consultant des correspondances, des photographies et des archives conservées ailleurs. Leur travail révèle des situations très diverses, allant du don documenté à des transferts dont les circonstances restent controversées.\n\nLe musée a choisi de publier les résultats progressivement, y compris lorsque les recherches sont incomplètes. Il présente désormais certaines pièces avec plusieurs points de vue, en précisant ce qui est attesté et ce qui demeure débattu. Quelques visiteurs craignent que cette approche rende les cartels difficiles à lire. La direction répond que l'incertitude fait partie des connaissances disponibles et qu'une formule brève ne doit pas transformer une hypothèse en fait établi. Le musée dialogue également avec des représentants des communautés concernées afin de mieux comprendre les usages originels de certains objets. Ce dialogue n'apporte pas automatiquement une réponse juridique unique, mais il peut conduire à revoir les descriptions, les conditions d'exposition et les priorités de recherche.","question":"Quel rôle les échanges avec les communautés concernées peuvent-ils jouer ?","options":["Annuler immédiatement toute recherche conduite par les historiens","Remplacer les inventaires par une seule interprétation obligatoire","Régler à eux seuls les questions juridiques de propriété","Apporter des informations utiles sans trancher automatiquement tous les litiges"],"correct":"D","explanation":"Le dialogue enrichit la connaissance et les choix d'exposition, sans résoudre à lui seul le statut légal.","semantic":{"concept":"museum-community-dialogue-not-automatic-legal-answer","evidence":"contextual-knowledge-not-juridical-settlement"},"section":"long","group":"Provenance muséale"},{"number":39,"points":1,"passage":"LES FORMATIONS COURTES PEUVENT-ELLES CHANGER UNE CARRIÈRE ?\nLes universités proposent de plus en plus de formations très courtes, parfois appelées microcertifications, destinées à des salariés qui souhaitent acquérir une compétence précise sans reprendre un long cursus. Cette souplesse intéresse les entreprises, mais elle soulève une question : comment comparer deux attestations délivrées par des organismes différents ? L'intitulé d'une formation ne renseigne pas toujours sur la durée du travail demandé, les modalités d'évaluation ou le niveau d'autonomie réellement atteint.\n\nUn consortium d'établissements travaille donc sur un cadre commun décrivant les acquis attendus et les preuves exigées pour obtenir chaque attestation. Il ne cherche pas à rendre identiques toutes les formations ; il souhaite permettre aux employeurs de comprendre ce qu'un titulaire a effectivement démontré. Certaines entreprises demandent cependant une reconnaissance encore plus simple, par exemple un seul score numérique. Les responsables universitaires s'y opposent : une compétence technique acquise dans un contexte donné ne se réduit pas à une note comparable à toutes les autres. Le consortium prévoit aussi des possibilités d'articulation avec des cursus plus longs, mais sans promettre qu'une accumulation automatique de petites attestations équivaudra à un diplôme complet.","question":"Quelle difficulté motive la création du cadre commun ?","options":["Des intitulés similaires peuvent cacher des exigences d'apprentissage différentes","Les organismes ne sont pas autorisés à former des adultes salariés","Les employeurs refusent par principe toute preuve de formation courte","Les universités proposent uniquement des formations de longue durée"],"correct":"A","explanation":"Le titre seul n'indique ni l'effort, ni la manière d'évaluer, ni les acquis réels.","semantic":{"concept":"microcredential-comparability-evidence","evidence":"labels-hide-learning-assessment-difference"},"section":"long","group":"Microcertifications"},{"number":40,"points":1,"passage":"LES FORMATIONS COURTES PEUVENT-ELLES CHANGER UNE CARRIÈRE ?\nLes universités proposent de plus en plus de formations très courtes, parfois appelées microcertifications, destinées à des salariés qui souhaitent acquérir une compétence précise sans reprendre un long cursus. Cette souplesse intéresse les entreprises, mais elle soulève une question : comment comparer deux attestations délivrées par des organismes différents ? L'intitulé d'une formation ne renseigne pas toujours sur la durée du travail demandé, les modalités d'évaluation ou le niveau d'autonomie réellement atteint.\n\nUn consortium d'établissements travaille donc sur un cadre commun décrivant les acquis attendus et les preuves exigées pour obtenir chaque attestation. Il ne cherche pas à rendre identiques toutes les formations ; il souhaite permettre aux employeurs de comprendre ce qu'un titulaire a effectivement démontré. Certaines entreprises demandent cependant une reconnaissance encore plus simple, par exemple un seul score numérique. Les responsables universitaires s'y opposent : une compétence technique acquise dans un contexte donné ne se réduit pas à une note comparable à toutes les autres. Le consortium prévoit aussi des possibilités d'articulation avec des cursus plus longs, mais sans promettre qu'une accumulation automatique de petites attestations équivaudra à un diplôme complet.","question":"Pourquoi les universités rejettent-elles l'idée d'un score unique ?","options":["Les formations courtes ne doivent jamais comporter d'évaluation","La notation supprimerait toute possibilité d'accès à l'emploi","La portée d'une compétence dépend du contexte où elle a été démontrée","Les employeurs ne souhaitent connaître que le nombre d'heures suivies"],"correct":"C","explanation":"Une compétence contextualisée ne peut être ramenée à un nombre universel.","semantic":{"concept":"microcredential-against-one-score","evidence":"competence-context-not-one-number"},"section":"long","group":"Microcertifications"}]}$bank4$::jsonb;
 if exists(select 1 from academy_tef_reading.papers where id='tef-reading-04' and version='tef-reading-2026-11-original-04-v1' and content<>paper) then raise exception 'Cannot modify published TEF Reading paper version tef-reading-04';end if;
 insert into academy_tef_reading.papers(id,version,content) values('tef-reading-04','tef-reading-2026-11-original-04-v1',paper) on conflict do nothing;

 paper := $bank5${"id":"tef-reading-05","version":"tef-reading-2026-11-original-05-v1","title":"TEF Canada · Compréhension écrite · Test 05","seconds":3600,"maxPoints":40,"questions":[{"number":1,"points":1,"passage":"🚈 TRAIN HISTORIQUE\nLes billets pour le voyage patrimonial de dimanche donnent accès au train et à la visite guidée de la gare ancienne. Le déjeuner servi sur place n'est pas compris et doit être réservé séparément au moins 48 heures avant le départ.","question":"Quelle prestation nécessite une démarche supplémentaire ?","options":["L'accès aux voitures du train ancien","La visite commentée de la gare historique","L'utilisation du billet sur le trajet prévu","Le repas proposé pendant l'excursion"],"correct":"D","explanation":"Le repas ne fait pas partie du forfait et exige une réservation anticipée.","semantic":{"concept":"heritage-rail-excluded-lunch","evidence":"tour-included-meal-extra"},"media":{"kind":"illustration","scene":"heritage-train","heading":"Voyage ferroviaire historique"}},{"number":2,"points":1,"passage":"📱 POINT NUMÉRIQUE\nLes habitants peuvent utiliser les ordinateurs du point numérique pour réaliser leurs démarches. Une aide individuelle est proposée sur rendez-vous le jeudi. Le libre accès aux postes demeure possible les autres jours sans accompagnement.","question":"Quelle différence existe entre l'aide et l'accès aux ordinateurs ?","options":["Les ordinateurs sont toujours réservés aux accompagnants","L'assistance personnalisée demande une réservation","L'utilisation des postes exige un rendez-vous quotidien","Les démarches libres sont interdites le reste de la semaine"],"correct":"B","explanation":"L'accès aux ordinateurs est libre, tandis que l'aide individuelle est sur rendez-vous.","semantic":{"concept":"digital-support-appointment-vs-free-access","evidence":"one-on-one-booking-not-pc"},"media":{"kind":"notice","icon":"💻","heading":"Espace numérique · permanences","accent":"#267a9b"}},{"number":3,"points":1,"passage":"🎭 THÉÂTRE DES MARRONNIERS\nLa représentation de samedi sera surtitrée en français. Les surtitres sont visibles depuis les places centrales, mais pas depuis les sièges situés sur les côtés de la première rangée. Un plan des places adaptées est disponible auprès du guichet.","question":"Quel conseil concerne les personnes souhaitant lire les surtitres ?","options":["Privilégier les sièges situés au centre de la salle","Choisir les sièges latéraux de la première rangée","Acheter uniquement des places réservées aux abonnés","Demander une copie des dialogues avant le spectacle"],"correct":"A","explanation":"La visibilité des surtitres varie selon l'emplacement, surtout au premier rang.","semantic":{"concept":"theater-surtitles-sightline","evidence":"center-seats-readable"},"media":{"kind":"notice","icon":"🎭","heading":"Spectacle surtitré · places","accent":"#8c538d"}},{"number":4,"points":1,"passage":"🛶 BASE NAUTIQUE\nPour les sorties encadrées sur la rivière, le matériel est fourni. Les participants doivent savoir nager et présenter une autorisation parentale s'ils sont mineurs. Un test d'aisance aquatique est organisé sur place avant le départ du groupe.","question":"Que doivent démontrer les participants, quel que soit leur âge ?","options":["Leur possession de leur propre embarcation","Leur inscription à un club de compétition","Leur capacité à évoluer dans l'eau","Leur expérience de navigation en mer"],"correct":"C","explanation":"La capacité à nager est obligatoire pour tous et vérifiée avant le départ.","semantic":{"concept":"river-canoe-swim-assessment","evidence":"swimming-test-everyone"},"media":{"kind":"illustration","scene":"canoe","heading":"Sortie sur la rivière"}},{"number":5,"points":1,"passage":"♻️ RÉEMPLOI DES MATÉRIAUX\nL'atelier municipal accepte les chutes de bois non traitées, même de petite taille. Les panneaux peints ou vernis ne peuvent pas être déposés dans cette collecte. Les pièces acceptées seront mises à disposition des associations locales.","question":"Quel matériau pourra être déposé ?","options":["Une étagère recouverte d'un vernis brillant","Une petite planche de bois brut","Un panneau repeint après ponçage superficiel","Une porte en bois traitée contre l'humidité"],"correct":"B","explanation":"Seuls les éléments en bois non traité sont admis, quelle que soit leur taille.","semantic":{"concept":"wood-reuse-uncoated-only","evidence":"untreated-even-small-offcuts"},"media":{"kind":"notice","icon":"🪵","heading":"Collecte de bois de réemploi","accent":"#81705b"}},{"number":6,"points":1,"passage":"🏘️ VISITES D'ARCHITECTURE\nLe parcours du centre-ville est accessible sans réservation, mais la visite de l'intérieur des immeubles n'est possible qu'avec un guide. Les groupes guidés partent à 11 h et 16 h. Les photographies à l'extérieur restent autorisées.","question":"Que permet une visite autonome ?","options":["Découvrir les façades sans entrer dans les bâtiments","Entrer dans les immeubles à l'heure de son choix","Accéder aux appartements uniquement le matin","Photographier les intérieurs sans accompagnateur"],"correct":"A","explanation":"L'accès autonome se limite au circuit extérieur, tandis que l'intérieur nécessite un guide.","semantic":{"concept":"urban-architecture-exterior-free-interior-guided","evidence":"unescorted-facades-only"},"media":{"kind":"notice","icon":"🏘️","heading":"Parcours architectural","accent":"#45769c"}},{"number":7,"points":1,"passage":"🥗 ATELIER CUISINE\nLes participants inscrits recevront la liste des ingrédients avant la séance. Le matériel de cuisine est prêté. Les personnes ayant une allergie alimentaire doivent le signaler au moins trois jours avant l'atelier afin que l'animateur étudie une adaptation de la recette.","question":"Pourquoi signaler une allergie suffisamment tôt ?","options":["Pour obtenir automatiquement une place gratuite","Pour recevoir son propre équipement de cuisine","Pour vérifier si la recette peut être adaptée","Pour remplacer une activité pratique par un cours théorique"],"correct":"C","explanation":"Le délai permet à l'équipe d'examiner une adaptation alimentaire possible.","semantic":{"concept":"cooking-allergy-advance-recipe-adaptation","evidence":"three-day-notice-for-substitution"},"media":{"kind":"notice","icon":"🥣","heading":"Atelier cuisine · informations","accent":"#a66c40"}},{"number":8,"points":1,"passage":"Le directeur souhaite conserver la solution actuelle, ________ les résultats de l'évaluation soient satisfaisants.","question":"Quel connecteur exige une condition positive ?","options":["bien que","tandis que","parce que","pourvu que"],"correct":"D","explanation":"« Pourvu que » marque une condition souhaitée suivie du subjonctif.","semantic":{"concept":"pourvu-que-conditional-subjunctive","evidence":"continue-only-if-evaluation-good"},"section":"cloze"},{"number":9,"points":1,"passage":"Le comité a décidé de reporter l'annonce, faute de données suffisamment ________.","question":"Quel adjectif convient au contexte d'une décision prudente ?","options":["visibles","régulières","récentes","fiables"],"correct":"D","explanation":"La prudence résulte d'une insuffisante fiabilité des données, non de leur présentation.","semantic":{"concept":"decision-postponed-unreliable-data","evidence":"data-quality-not-visibility"},"section":"cloze"},{"number":10,"points":1,"passage":"Les dispositions resteront en vigueur ________ nouvel ordre de l'administration.","question":"Quelle préposition complète l'expression administrative ?","options":["jusqu'à","envers","malgré","depuis"],"correct":"A","explanation":"« Jusqu'à nouvel ordre » signifie que la règle reste applicable sans échéance fixée.","semantic":{"concept":"until-further-notice-idiom","evidence":"jusqua-nouvel-ordre"},"section":"cloze"},{"number":11,"points":1,"passage":"Il importe que chaque membre ________ connaissance du règlement avant la séance.","question":"Quelle forme convient après « il importe que » ?","options":["prend","prendra","prenne","prenait"],"correct":"C","explanation":"« Il importe que » appelle ici le subjonctif « prenne ».","semantic":{"concept":"importe-que-subjunctive","evidence":"prenne-connaissance"},"section":"cloze"},{"number":12,"points":1,"passage":"CHANGEMENT DE FOURNISSEUR\nAvant de signer le contrat, l'association veut ________ (1) plusieurs devis comparables. Elle tiendra compte du coût, mais également de la ________ (2) des délais de livraison annoncés.","question":"Quel verbe convient à l'espace (1) ?","options":["conserver","comparer","prolonger","publier"],"correct":"B","explanation":"Les devis sont étudiés les uns par rapport aux autres avant toute signature.","semantic":{"concept":"procurement-compare-quotes","evidence":"different-supplier-proposals-before-contract"},"section":"paired-cloze","group":"Choix d'un fournisseur"},{"number":13,"points":1,"passage":"CHANGEMENT DE FOURNISSEUR\nAvant de signer le contrat, l'association veut ________ (1) plusieurs devis comparables. Elle tiendra compte du coût, mais également de la ________ (2) des délais de livraison annoncés.","question":"Quel nom convient à l'espace (2) ?","options":["fiabilité","variété","rapidité","simplicité"],"correct":"A","explanation":"Une livraison annoncée doit surtout respecter le délai convenu, et non seulement être rapide.","semantic":{"concept":"procurement-delivery-reliability","evidence":"reliable-promised-timelines"},"section":"paired-cloze","group":"Choix d'un fournisseur"},{"number":14,"points":1,"passage":"VOISINAGE SOLIDAIRE\nLes participants s'engagent à ________ (1) les besoins des personnes isolées avant de proposer une aide. Ils souhaitent ainsi éviter des interventions mal adaptées et préserver la ________ (2) des bénéficiaires.","question":"Quel verbe convient à l'espace (1) ?","options":["imaginer","limiter","recueillir","remplacer"],"correct":"C","explanation":"Il faut recueillir les besoins réels, plutôt que les supposer.","semantic":{"concept":"volunteer-needs-elicitation","evidence":"ask-before-intervening"},"section":"paired-cloze","group":"Voisinage solidaire"},{"number":15,"points":1,"passage":"VOISINAGE SOLIDAIRE\nLes participants s'engagent à ________ (1) les besoins des personnes isolées avant de proposer une aide. Ils souhaitent ainsi éviter des interventions mal adaptées et préserver la ________ (2) des bénéficiaires.","question":"Quel nom convient à l'espace (2) ?","options":["popularité","autonomie","présence","surveillance"],"correct":"B","explanation":"Une aide appropriée doit respecter la capacité des bénéficiaires à décider pour eux-mêmes.","semantic":{"concept":"volunteer-beneficiary-autonomy","evidence":"support-without-undermining-independent-choice"},"section":"paired-cloze","group":"Voisinage solidaire"},{"number":16,"points":1,"passage":"JOURNAL LOCAL\nPour éviter la diffusion de rumeurs, l'équipe vérifie les témoignages auprès de plusieurs ________ (1). Lorsqu'une information reste incertaine, elle le mentionne ________ (2) dans l'article.","question":"Quel nom convient à l'espace (1) ?","options":["rubriques","éditions","images","sources"],"correct":"D","explanation":"La vérification journalistique s'appuie sur plusieurs sources indépendantes.","semantic":{"concept":"local-news-crosscheck-sources","evidence":"corroborate-testimonials"},"section":"paired-cloze","group":"Journal local"},{"number":17,"points":1,"passage":"JOURNAL LOCAL\nPour éviter la diffusion de rumeurs, l'équipe vérifie les témoignages auprès de plusieurs ________ (1). Lorsqu'une information reste incertaine, elle le mentionne ________ (2) dans l'article.","question":"Quel adverbe convient à l'espace (2) ?","options":["explicitement","rarement","automatiquement","discrètement"],"correct":"A","explanation":"Le lecteur doit être informé clairement de l'incertitude encore présente.","semantic":{"concept":"local-news-disclose-uncertainty","evidence":"openly-label-unverified-claims"},"section":"paired-cloze","group":"Journal local"},{"number":18,"points":1,"passage":"","question":"Quel poste conviendrait à une personne disposant du permis B, disponible le week-end, mais ne souhaitant pas porter de charges lourdes ?","options":["Offre 2","Offre 3","Offre 1","Offre 4"],"correct":"C","explanation":"L'offre 1 prévoit des déplacements en voiture le week-end, sans manutention lourde.","semantic":{"concept":"weekend-driving-no-heavy-lifting","evidence":"driving-weekends-light-work"},"section":"offers","media":{"kind":"offers","heading":"Emplois · Logistique événementielle","items":["Navette visiteurs : conduite le samedi et le dimanche, permis B, sans manipulation de matériel.","Déménagement : conduite et port de meubles volumineux le samedi, permis B.","Entrepôt : tri de colis en semaine, travail physique, permis non nécessaire.","Livraison de matériel scénique : conduite le dimanche et installation de structures lourdes."]}},{"number":19,"points":1,"passage":"","question":"Quel poste convient à un candidat expérimenté qui souhaite superviser des bénévoles à temps partiel, exclusivement les après-midi en semaine ?","options":["Offre 1","Offre 3","Offre 2","Offre 4"],"correct":"B","explanation":"L'offre 3 porte sur la coordination de bénévoles, à temps partiel, l'après-midi en semaine.","semantic":{"concept":"weekday-afternoon-volunteer-supervisor","evidence":"parttime-weekday-pm-supervision"},"section":"offers","media":{"kind":"offers","heading":"Recrutements · Vie associative","items":["Centre social : supervision de bénévoles, temps plein avec permanences matinales.","Festival local : coordination de bénévoles, contrat à temps partiel avec services le week-end.","Maison de quartier : responsable bénévole confirmé, 14 h–18 h du lundi au jeudi, temps partiel.","Accueil municipal : supervision d'une équipe salariée, trois matinées de semaine."]}},{"number":20,"points":1,"passage":"VARIATIONS D'UNE SÉRIE\nLes quatre courbes présentent cinq relevés.","question":"Quel graphique connaît deux progressions successives, puis un recul et une stabilisation au dernier niveau ?","options":["Graphique 2","Graphique 3","Graphique 4","Graphique 1"],"correct":"D","explanation":"La première courbe monte de 8 à 14 puis 22, retombe à 17 et se maintient ensuite à 17.","semantic":{"concept":"two-rises-fall-last-plateau","evidence":"8-14-22-17-17"},"section":"charts","media":{"kind":"chart-grid","heading":"Nombre de visiteurs inscrits","unit":"en centaines","years":["T1","T2","T3","T4","T5"],"series":[[8,14,22,17,17],[13,15,22,20,14],[29,23,20,14,9],[12,19,15,23,18]]}},{"number":21,"points":1,"passage":"ÉVOLUTION DE LA DEMANDE\nComparez les variations d'une période à l'autre.","question":"Quel graphique présente un sommet dès la deuxième mesure, puis trois baisses consécutives, tout en terminant au-dessus du niveau initial ?","options":["Graphique 4","Graphique 1","Graphique 2","Graphique 3"],"correct":"A","explanation":"La quatrième série passe de 11 à 29, puis diminue à 25, 21 et 15 : le niveau final dépasse 11.","semantic":{"concept":"second-time-peak-three-falls-above-start","evidence":"11-29-25-21-15"},"section":"charts","media":{"kind":"chart-grid","heading":"Commandes de produits locaux","unit":"en milliers","years":["A1","A2","A3","A4","A5"],"series":[[25,20,15,10,5],[9,12,18,21,29],[15,22,18,24,20],[11,29,25,21,15]]}},{"number":22,"points":1,"passage":"MESURES DE PARTICIPATION\nLes données sont suivies pendant cinq périodes.","question":"Quel graphique revient à sa valeur de départ après une hausse initiale et deux baisses, avant la dernière reprise ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"B","explanation":"La série 2 part de 17, monte à 27, descend deux fois, puis finit à 17 exactement.","semantic":{"concept":"rise-two-falls-return-exact-start","evidence":"17-27-18-11-17"},"section":"charts","media":{"kind":"chart-grid","heading":"Présences aux activités collectives","unit":"en centaines","years":["1","2","3","4","5"],"series":[[10,14,19,24,28],[17,27,18,11,17],[27,20,14,17,23],[12,15,24,12,14]]}},{"number":23,"points":1,"passage":"Objet : Réservation d'une salle de répétition\nBonjour,\nNous confirmons que le studio B est disponible pour votre groupe les lundis de 19 h à 21 h jusqu'à la fin de juin. Les instruments fixes sont mis à disposition sans coût supplémentaire. L'accès à la régie d'enregistrement n'est pas inclus dans cette réservation ; il peut être demandé séparément si un technicien est disponible. Le groupe devra laisser le studio libre à 21 h, afin que l'équipe puisse effectuer les vérifications de fermeture. Les séances annulées par votre groupe moins de 48 heures à l'avance restent dues. En revanche, un changement imposé par le centre donnera lieu à un report sans frais.","question":"Quelle prestation n'est pas comprise dans la réservation ordinaire ?","options":["L'usage des instruments installés dans le studio","La mise à disposition du studio jusqu'à 21 h","L'utilisation de la régie avec un technicien","Les vérifications de fermeture par le personnel"],"correct":"C","explanation":"Le studio et ses instruments sont inclus, la régie étant proposée sous conditions.","semantic":{"concept":"rehearsal-control-room-not-included","evidence":"recording-control-optional"},"section":"email","group":"Studio de répétition"},{"number":24,"points":1,"passage":"Objet : Réservation d'une salle de répétition\nBonjour,\nNous confirmons que le studio B est disponible pour votre groupe les lundis de 19 h à 21 h jusqu'à la fin de juin. Les instruments fixes sont mis à disposition sans coût supplémentaire. L'accès à la régie d'enregistrement n'est pas inclus dans cette réservation ; il peut être demandé séparément si un technicien est disponible. Le groupe devra laisser le studio libre à 21 h, afin que l'équipe puisse effectuer les vérifications de fermeture. Les séances annulées par votre groupe moins de 48 heures à l'avance restent dues. En revanche, un changement imposé par le centre donnera lieu à un report sans frais.","question":"Dans quel cas une séance annulée pourrait-elle être reportée sans frais ?","options":["Si le groupe avertit moins de deux jours avant","Si le groupe termine sa répétition quelques minutes plus tôt","Si les musiciens souhaitent enregistrer leur prestation","Si le changement est décidé par le centre lui-même"],"correct":"D","explanation":"Seuls les changements imposés par le centre donnent lieu à un report gratuit.","semantic":{"concept":"rehearsal-venue-change-free-reschedule","evidence":"provider-cancel-no-charge"},"section":"email","group":"Studio de répétition"},{"number":25,"points":1,"passage":"Avis — Navettes du festival rural\nLe festival mettra en place une navette entre la gare régionale et le site des spectacles. Le premier départ sera assuré une heure avant l'ouverture des portes, puis un véhicule partira toutes les quarante minutes. Le soir, la dernière navette quittera le festival trente minutes après la fin annoncée du dernier concert. En cas de prolongation imprévue des spectacles, les organisateurs ne garantissent pas une navette supplémentaire. Les usagers sont donc invités à vérifier l'horaire officiel avant de quitter le site. Le transport est compris dans le billet du festival, mais les personnes non munies d'un billet ne peuvent pas utiliser le service.","question":"Quel risque existe si la fin des concerts est retardée ?","options":["La navette prévue pourrait ne pas être prolongée","La première navette du jour sera annulée le lendemain","Les voyageurs devront acheter un billet supplémentaire à la gare","Les navettes passeront automatiquement toutes les dix minutes"],"correct":"A","explanation":"Le dernier départ est lié à l'horaire annoncé ; une prolongation des spectacles ne garantit pas de véhicule additionnel.","semantic":{"concept":"festival-shuttle-overrun-not-guaranteed","evidence":"last-shuttle-based-on-scheduled-ending"},"section":"email","group":"Navettes de festival"},{"number":26,"points":1,"passage":"Avis — Navettes du festival rural\nLe festival mettra en place une navette entre la gare régionale et le site des spectacles. Le premier départ sera assuré une heure avant l'ouverture des portes, puis un véhicule partira toutes les quarante minutes. Le soir, la dernière navette quittera le festival trente minutes après la fin annoncée du dernier concert. En cas de prolongation imprévue des spectacles, les organisateurs ne garantissent pas une navette supplémentaire. Les usagers sont donc invités à vérifier l'horaire officiel avant de quitter le site. Le transport est compris dans le billet du festival, mais les personnes non munies d'un billet ne peuvent pas utiliser le service.","question":"Qui peut utiliser les navettes sans payer un titre de transport distinct ?","options":["Toute personne arrivant à la gare pendant la journée","Les visiteurs possédant uniquement un abonnement de train","Les détenteurs d'un billet valide pour le festival","Les habitants du village munis d'un justificatif de domicile"],"correct":"C","explanation":"Le prix est intégré au billet d'entrée du festival et réservé à ses détenteurs.","semantic":{"concept":"festival-shuttle-ticket-bundled","evidence":"festival-ticket-required"},"section":"email","group":"Navettes de festival"},{"number":27,"points":1,"passage":"Annonce — Concours de nouvelles\nLa maison de la lecture lance un concours ouvert aux auteurs n'ayant encore publié aucun livre à compte d'éditeur. Les candidats peuvent toutefois avoir déjà diffusé des textes dans une revue ou sur un site personnel. La nouvelle doit compter entre 3 000 et 5 000 mots et être envoyée anonymement, sans nom dans le fichier. Les coordonnées seront saisies dans un formulaire distinct. Un jury sélectionnera dix textes pour une lecture publique ; cette sélection ne garantit pas leur publication. Les textes envoyés après le 30 avril ne seront pas examinés. Le règlement complet précise les conditions de droits d'auteur.","question":"Quel candidat reste admissible au concours ?","options":["Un romancier ayant publié plusieurs ouvrages chez un éditeur","Un auteur de revue qui n'a jamais publié de livre chez un éditeur","Un auteur dont le texte porte son nom en première page","Un candidat qui transmet sa nouvelle après le 30 avril"],"correct":"B","explanation":"Publier dans une revue n'exclut pas la candidature ; avoir un livre à compte d'éditeur l'exclut.","semantic":{"concept":"writing-contest-published-magazine-allowed","evidence":"not-yet-book-published"},"section":"email","group":"Concours de nouvelles"},{"number":28,"points":1,"passage":"Annonce — Concours de nouvelles\nLa maison de la lecture lance un concours ouvert aux auteurs n'ayant encore publié aucun livre à compte d'éditeur. Les candidats peuvent toutefois avoir déjà diffusé des textes dans une revue ou sur un site personnel. La nouvelle doit compter entre 3 000 et 5 000 mots et être envoyée anonymement, sans nom dans le fichier. Les coordonnées seront saisies dans un formulaire distinct. Un jury sélectionnera dix textes pour une lecture publique ; cette sélection ne garantit pas leur publication. Les textes envoyés après le 30 avril ne seront pas examinés. Le règlement complet précise les conditions de droits d'auteur.","question":"Qu'implique la sélection parmi les dix textes retenus ?","options":["Une publication commerciale automatique de la nouvelle","Une rémunération garantie par le jury","Un droit de modifier librement le règlement du concours","Une présentation publique, sans certitude d'édition"],"correct":"D","explanation":"Les textes sont destinés à une lecture publique, pas automatiquement à une publication.","semantic":{"concept":"writing-contest-shortlist-reading-not-publishing","evidence":"shortlist-does-not-ensure-publication"},"section":"email","group":"Concours de nouvelles"},{"number":29,"points":1,"passage":"Note aux partenaires — Collecte de matériel informatique\nNotre association récupérera le mois prochain des ordinateurs encore fonctionnels pour les remettre à des centres de formation. Les donateurs devront supprimer leurs données personnelles avant le dépôt ; l'association effectuera ensuite une vérification technique, mais ne garantira pas l'effacement de fichiers oubliés. Les équipements trop anciens pour les logiciels pédagogiques seront orientés vers une filière de recyclage agréée. Un reçu de don sera remis après inventaire, et non au moment de la prise en charge des cartons. Les partenaires peuvent déposer leur matériel les mardi et jeudi, ou demander un enlèvement collectif si le volume dépasse dix appareils.","question":"Quelle responsabilité incombe aux donateurs avant le dépôt ?","options":["Retirer les informations personnelles stockées sur les machines","Réparer les logiciels pédagogiques des appareils reçus","Rédiger le reçu d'inventaire de chaque équipement","Choisir eux-mêmes le prestataire du recyclage final"],"correct":"A","explanation":"Les donateurs doivent effacer leurs données avant transfert à l'association.","semantic":{"concept":"used-computer-donor-data-erasure","evidence":"erase-personal-data-before-handoff"},"section":"email","group":"Don d'ordinateurs"},{"number":30,"points":1,"passage":"Note aux partenaires — Collecte de matériel informatique\nNotre association récupérera le mois prochain des ordinateurs encore fonctionnels pour les remettre à des centres de formation. Les donateurs devront supprimer leurs données personnelles avant le dépôt ; l'association effectuera ensuite une vérification technique, mais ne garantira pas l'effacement de fichiers oubliés. Les équipements trop anciens pour les logiciels pédagogiques seront orientés vers une filière de recyclage agréée. Un reçu de don sera remis après inventaire, et non au moment de la prise en charge des cartons. Les partenaires peuvent déposer leur matériel les mardi et jeudi, ou demander un enlèvement collectif si le volume dépasse dix appareils.","question":"Dans quelle situation un enlèvement peut-il être demandé ?","options":["Lorsque le donateur ne souhaite pas recevoir de reçu","Lorsque le matériel n'a plus de valeur marchande","Lorsque la collecte porte sur plus de dix équipements","Lorsque les appareils sont livrés directement au recyclage"],"correct":"C","explanation":"Le ramassage collectif est proposé au-delà d'un volume de dix appareils.","semantic":{"concept":"equipment-donation-bulk-pickup-threshold","evidence":"more-than-ten-equipment"},"section":"email","group":"Don d'ordinateurs"},{"number":31,"points":1,"passage":"Objet : Renouvellement de votre qualification\nMadame,\nVotre qualification professionnelle expire le 30 novembre. Pour la renouveler, vous devez présenter un justificatif de pratique récente et suivre le module de mise à jour prévu en octobre. Les personnes qui ont changé de secteur depuis leur dernière qualification pourront demander une évaluation individualisée, mais celle-ci ne dispense pas du module commun. Les candidatures complètes seront traitées dans l'ordre de réception. Une attestation provisoire pourra être délivrée aux candidats ayant achevé la formation mais dont le dossier de pratique reste à vérifier. Elle ne permet pas d'exercer les activités réservées aux titulaires pleinement qualifiés.","question":"Quel point reste obligatoire malgré la possibilité d'une évaluation individuelle ?","options":["Obtenir automatiquement la qualification définitive","Suivre le module commun de mise à jour","Renoncer à tout justificatif d'activité professionnelle","Déposer son dossier uniquement après son expiration"],"correct":"B","explanation":"L'évaluation spécifique ne remplace pas le module collectif imposé.","semantic":{"concept":"credential-individual-assessment-not-exempt-module","evidence":"module-common-mandatory"},"section":"email","group":"Qualification professionnelle"},{"number":32,"points":1,"passage":"Objet : Renouvellement de votre qualification\nMadame,\nVotre qualification professionnelle expire le 30 novembre. Pour la renouveler, vous devez présenter un justificatif de pratique récente et suivre le module de mise à jour prévu en octobre. Les personnes qui ont changé de secteur depuis leur dernière qualification pourront demander une évaluation individualisée, mais celle-ci ne dispense pas du module commun. Les candidatures complètes seront traitées dans l'ordre de réception. Une attestation provisoire pourra être délivrée aux candidats ayant achevé la formation mais dont le dossier de pratique reste à vérifier. Elle ne permet pas d'exercer les activités réservées aux titulaires pleinement qualifiés.","question":"Quelle limite s'applique à l'attestation provisoire ?","options":["Elle n'est délivrée qu'aux personnes sans expérience","Elle remplace définitivement la qualification expirée","Elle autorise la pratique avant même la formation requise","Elle ne donne pas accès aux actes réservés aux titulaires"],"correct":"D","explanation":"L'attestation provisoire ne confère pas les mêmes droits qu'une qualification validée.","semantic":{"concept":"provisional-credential-limited-practice","evidence":"temporary-certificate-does-not-authorize-restricted-work"},"section":"email","group":"Qualification professionnelle"},{"number":33,"points":1,"passage":"GÉRER LA PÊCHE CÔTIÈRE SANS OPPOSER TOUS LES ACTEURS\nDans une baie où la pêche artisanale reste une activité importante, une diminution des captures a conduit les autorités à envisager une fermeture saisonnière de certaines zones. Plusieurs pêcheurs reconnaissent la nécessité de protéger les périodes de reproduction, mais craignent qu'une interdiction uniforme ne pénalise davantage les petits navires que les flottes capables de se déplacer au large. De leur côté, les scientifiques soulignent que les données disponibles portent surtout sur les espèces commercialisées et décrivent moins bien les écosystèmes côtiers.\n\nUn comité associant professionnels, chercheurs et collectivités a proposé une expérimentation sur deux saisons. Les zones de protection seraient adaptées selon les observations de reproduction, tandis que les pêcheurs consigneraient leurs sorties et certains rejets habituellement non comptabilisés. Les représentants du secteur demandent que la collecte de données reste simple afin de ne pas multiplier les heures de travail administratif. Les chercheurs souhaitent des relevés comparables d'un bateau à l'autre. Le compromis porte donc autant sur la méthode de suivi que sur la géographie des zones fermées. Le comité annonce qu'il évaluera les tendances biologiques et les effets économiques, sans interpréter une bonne saison de captures comme preuve suffisante de rétablissement durable.","question":"Pourquoi certains pêcheurs contestent-ils une fermeture uniforme ?","options":["Elle peut avoir des conséquences inégales selon la mobilité des navires","Elle est automatiquement incompatible avec toute protection de la reproduction","Elle ne concernerait que les bateaux capables de s'éloigner de la côte","Elle remplacerait toutes les mesures scientifiques par des décisions commerciales"],"correct":"A","explanation":"Les petits navires n'ont pas les mêmes possibilités de déplacement que les grandes flottes.","semantic":{"concept":"fisheries-uniform-closure-unequal-ability","evidence":"small-boats-cannot-shift-offshore"},"section":"long","group":"Gestion de la pêche"},{"number":34,"points":1,"passage":"GÉRER LA PÊCHE CÔTIÈRE SANS OPPOSER TOUS LES ACTEURS\nDans une baie où la pêche artisanale reste une activité importante, une diminution des captures a conduit les autorités à envisager une fermeture saisonnière de certaines zones. Plusieurs pêcheurs reconnaissent la nécessité de protéger les périodes de reproduction, mais craignent qu'une interdiction uniforme ne pénalise davantage les petits navires que les flottes capables de se déplacer au large. De leur côté, les scientifiques soulignent que les données disponibles portent surtout sur les espèces commercialisées et décrivent moins bien les écosystèmes côtiers.\n\nUn comité associant professionnels, chercheurs et collectivités a proposé une expérimentation sur deux saisons. Les zones de protection seraient adaptées selon les observations de reproduction, tandis que les pêcheurs consigneraient leurs sorties et certains rejets habituellement non comptabilisés. Les représentants du secteur demandent que la collecte de données reste simple afin de ne pas multiplier les heures de travail administratif. Les chercheurs souhaitent des relevés comparables d'un bateau à l'autre. Le compromis porte donc autant sur la méthode de suivi que sur la géographie des zones fermées. Le comité annonce qu'il évaluera les tendances biologiques et les effets économiques, sans interpréter une bonne saison de captures comme preuve suffisante de rétablissement durable.","question":"Quelle précaution méthodologique guide l'évaluation du programme ?","options":["Considérer un seul bon rendement commercial comme preuve de succès","Mesurer exclusivement le prix moyen des poissons vendus","Croiser les observations biologiques et économiques sur plusieurs saisons","Limiter les relevés aux espèces capturées sur un seul bateau"],"correct":"C","explanation":"Le suivi doit dépasser les captures ponctuelles pour juger les stocks et les effets sur les professionnels.","semantic":{"concept":"fisheries-evaluate-multi-season-ecology-economy","evidence":"one-season-catch-not-recovery"},"section":"long","group":"Gestion de la pêche"},{"number":35,"points":1,"passage":"LA SEMAINE DE TRAVAIL SUR QUATRE JOURS À L'ÉPREUVE DES FAITS\nPlusieurs entreprises expérimentent une organisation répartissant le travail sur quatre jours. L'expression masque néanmoins deux dispositifs différents : certaines réduisent réellement le nombre d'heures travaillées, tandis que d'autres concentrent la même durée hebdomadaire sur des journées plus longues. Une enquête auprès de salariés fait apparaître des effets contrastés. Les participants à la réduction horaire déclarent parfois disposer de davantage de temps pour leurs obligations personnelles ; ceux qui travaillent des journées prolongées soulignent plutôt la fatigue accumulée en fin de journée.\n\nLes responsables d'une entreprise de services ont choisi d'évaluer la qualité des prestations, les délais de réponse et la répartition des tâches, au lieu de s'appuyer uniquement sur la satisfaction déclarée. Les premiers résultats sont encourageants dans les équipes dont l'activité se planifie à l'avance. En revanche, les services qui doivent répondre à des sollicitations imprévues ont dû mettre en place une rotation complexe pour éviter les absences simultanées. La direction refuse donc d'étendre immédiatement le modèle à tous les métiers. Elle souhaite distinguer les bénéfices réels d'une réduction de temps de travail des effets d'un simple réaménagement des horaires.","question":"Quelle distinction est essentielle pour comprendre les résultats de l'expérience ?","options":["La durée du travail et la répartition des horaires désignent toujours la même mesure","Réduire les heures n'est pas la même chose que les répartir sur moins de jours","Seuls les services de réponse urgente ont accès à quatre jours de travail","La satisfaction des salariés remplace toute mesure de productivité"],"correct":"B","explanation":"Le texte oppose réduction effective du temps et compression des mêmes heures.","semantic":{"concept":"four-day-workweek-hours-vs-compression","evidence":"less-hours-versus-same-longer-days"},"section":"long","group":"Semaine de quatre jours"},{"number":36,"points":1,"passage":"LA SEMAINE DE TRAVAIL SUR QUATRE JOURS À L'ÉPREUVE DES FAITS\nPlusieurs entreprises expérimentent une organisation répartissant le travail sur quatre jours. L'expression masque néanmoins deux dispositifs différents : certaines réduisent réellement le nombre d'heures travaillées, tandis que d'autres concentrent la même durée hebdomadaire sur des journées plus longues. Une enquête auprès de salariés fait apparaître des effets contrastés. Les participants à la réduction horaire déclarent parfois disposer de davantage de temps pour leurs obligations personnelles ; ceux qui travaillent des journées prolongées soulignent plutôt la fatigue accumulée en fin de journée.\n\nLes responsables d'une entreprise de services ont choisi d'évaluer la qualité des prestations, les délais de réponse et la répartition des tâches, au lieu de s'appuyer uniquement sur la satisfaction déclarée. Les premiers résultats sont encourageants dans les équipes dont l'activité se planifie à l'avance. En revanche, les services qui doivent répondre à des sollicitations imprévues ont dû mettre en place une rotation complexe pour éviter les absences simultanées. La direction refuse donc d'étendre immédiatement le modèle à tous les métiers. Elle souhaite distinguer les bénéfices réels d'une réduction de temps de travail des effets d'un simple réaménagement des horaires.","question":"Pourquoi la direction hésite-t-elle à généraliser le dispositif ?","options":["Les équipes planifiables ont déjà obtenu des résultats négatifs","La réduction d'horaires interdit tout travail avec des clients","La direction ne dispose d'aucune mesure sur les délais de service","Les métiers soumis à des demandes imprévisibles nécessitent une autre organisation"],"correct":"D","explanation":"Les services à sollicitations imprévues ont du mal à organiser la couverture des demandes.","semantic":{"concept":"four-day-workweek-unpredictable-services","evidence":"rota-challenge-in-unplanned-demand"},"section":"long","group":"Semaine de quatre jours"},{"number":37,"points":1,"passage":"QUI DÉCIDE DU PRIX D'UN LOYER SUGGÉRÉ PAR UN ALGORITHME ?\nDans plusieurs grandes villes, des propriétaires utilisent des outils informatiques pour estimer les loyers possibles. Les programmes prennent en compte la localisation, la surface et des caractéristiques de logements comparables. Leur intérêt est de traiter rapidement de nombreuses informations, mais les recommandations peuvent être trompeuses lorsque les données reflètent surtout les annonces affichées, sans montrer les loyers finalement négociés ni les logements restés vacants.\n\nUne association de consommateurs demande davantage de transparence sur les variables utilisées et sur la manière dont le bailleur conserve son pouvoir de décision. Les fournisseurs de logiciels répondent que les modèles ne fixent pas directement les prix : ils produisent une suggestion qu'un propriétaire peut accepter ou refuser. Les chercheurs interrogés estiment néanmoins que des recommandations similaires, adoptées par un grand nombre d'acteurs, peuvent modifier les pratiques du marché même sans obligation formelle. Ils souhaitent donc étudier les décisions réelles prises après la consultation du logiciel, plutôt que de conclure à partir de ses seules fonctionnalités déclarées. L'enjeu consiste à distinguer l'outil d'aide à la décision de ses effets collectifs possibles.","question":"Quelle faiblesse des données d'entrée peut fausser l'estimation ?","options":["Elles peuvent décrire les annonces plutôt que les locations réellement conclues","Elles portent uniquement sur les bâtiments construits avant le siècle dernier","Elles excluent toute information sur la taille des logements","Elles ne peuvent être analysées qu'une fois par année civile"],"correct":"A","explanation":"Le prix annoncé ne correspond pas toujours au prix négocié ou effectivement obtenu.","semantic":{"concept":"rent-algorithm-listing-vs-real-transactions","evidence":"posted-price-not-final-rent"},"section":"long","group":"Algorithmes de loyers"},{"number":38,"points":1,"passage":"QUI DÉCIDE DU PRIX D'UN LOYER SUGGÉRÉ PAR UN ALGORITHME ?\nDans plusieurs grandes villes, des propriétaires utilisent des outils informatiques pour estimer les loyers possibles. Les programmes prennent en compte la localisation, la surface et des caractéristiques de logements comparables. Leur intérêt est de traiter rapidement de nombreuses informations, mais les recommandations peuvent être trompeuses lorsque les données reflètent surtout les annonces affichées, sans montrer les loyers finalement négociés ni les logements restés vacants.\n\nUne association de consommateurs demande davantage de transparence sur les variables utilisées et sur la manière dont le bailleur conserve son pouvoir de décision. Les fournisseurs de logiciels répondent que les modèles ne fixent pas directement les prix : ils produisent une suggestion qu'un propriétaire peut accepter ou refuser. Les chercheurs interrogés estiment néanmoins que des recommandations similaires, adoptées par un grand nombre d'acteurs, peuvent modifier les pratiques du marché même sans obligation formelle. Ils souhaitent donc étudier les décisions réelles prises après la consultation du logiciel, plutôt que de conclure à partir de ses seules fonctionnalités déclarées. L'enjeu consiste à distinguer l'outil d'aide à la décision de ses effets collectifs possibles.","question":"Pourquoi les chercheurs s'intéressent-ils aux usages collectifs de ces outils ?","options":["Les outils imposent juridiquement leur estimation à tous les propriétaires","Des recommandations facultatives peuvent néanmoins orienter plusieurs décisions","Les propriétaires ne disposent d'aucune possibilité de refuser un conseil","Les programmes partagent obligatoirement les contrats individuels entre concurrents"],"correct":"B","explanation":"Même non contraignants, des conseils largement suivis peuvent influencer un marché.","semantic":{"concept":"rent-algorithm-collective-voluntary-adoption","evidence":"voluntary-suggestions-can-shift-market"},"section":"long","group":"Algorithmes de loyers"},{"number":39,"points":1,"passage":"TRANSMETTRE UNE LANGUE RÉGIONALE AU-DELÀ DES SALLES DE CLASSE\nUne association souhaite favoriser l'usage d'une langue régionale dont les locuteurs les plus âgés sont encore nombreux, mais que les jeunes utilisent peu entre eux. Des cours sont proposés depuis plusieurs années et attirent des participants motivés. Malgré cela, l'enquête menée auprès des familles montre qu'une bonne connaissance grammaticale ne se traduit pas toujours par un usage spontané dans les conversations quotidiennes. Certaines personnes maîtrisent les exercices mais hésitent à parler en dehors du cadre scolaire, de peur de commettre des erreurs.\n\nL'association développe désormais des activités intergénérationnelles autour de la cuisine, du jardinage et de récits de quartier. Les bénévoles encouragent des échanges authentiques plutôt que des dialogues entièrement préparés. Les organisateurs constatent que les participants prennent davantage la parole lorsqu'ils discutent d'une tâche concrète, mais reconnaissent que cette observation repose sur un groupe encore restreint. Ils ne présentent donc pas les activités comme une solution universelle. Ils envisagent des rencontres régulières dans différents lieux, afin que la langue soit associée à des usages réels et non seulement à une compétence évaluée en classe.","question":"Quelle limite des cours traditionnels l'association cherche-t-elle à dépasser ?","options":["L'impossibilité d'apprendre une grammaire dans un cadre scolaire","L'absence de locuteurs âgés capables de transmettre la langue","La difficulté à utiliser spontanément une langue pourtant étudiée","Le refus des jeunes d'assister à toute activité collective"],"correct":"C","explanation":"Les acquis scolaires peuvent rester difficiles à mobiliser dans la vie ordinaire.","semantic":{"concept":"heritage-language-classroom-to-natural-use","evidence":"grammar-skill-not-everyday-speech"},"section":"long","group":"Langues régionales"},{"number":40,"points":1,"passage":"TRANSMETTRE UNE LANGUE RÉGIONALE AU-DELÀ DES SALLES DE CLASSE\nUne association souhaite favoriser l'usage d'une langue régionale dont les locuteurs les plus âgés sont encore nombreux, mais que les jeunes utilisent peu entre eux. Des cours sont proposés depuis plusieurs années et attirent des participants motivés. Malgré cela, l'enquête menée auprès des familles montre qu'une bonne connaissance grammaticale ne se traduit pas toujours par un usage spontané dans les conversations quotidiennes. Certaines personnes maîtrisent les exercices mais hésitent à parler en dehors du cadre scolaire, de peur de commettre des erreurs.\n\nL'association développe désormais des activités intergénérationnelles autour de la cuisine, du jardinage et de récits de quartier. Les bénévoles encouragent des échanges authentiques plutôt que des dialogues entièrement préparés. Les organisateurs constatent que les participants prennent davantage la parole lorsqu'ils discutent d'une tâche concrète, mais reconnaissent que cette observation repose sur un groupe encore restreint. Ils ne présentent donc pas les activités comme une solution universelle. Ils envisagent des rencontres régulières dans différents lieux, afin que la langue soit associée à des usages réels et non seulement à une compétence évaluée en classe.","question":"Quelle réserve les organisateurs expriment-ils au sujet des résultats observés ?","options":["Les rencontres ont montré une baisse certaine des prises de parole","Les échanges spontanés seraient impossibles hors des salles de classe","Tous les participants ont atteint le même niveau linguistique","Le groupe étudié reste trop limité pour généraliser les bénéfices"],"correct":"D","explanation":"Les bénéfices semblent encourageants, mais l'échantillon demeure restreint.","semantic":{"concept":"heritage-language-pilot-limited-sample","evidence":"small-observed-group-not-universal-proof"},"section":"long","group":"Langues régionales"}]}$bank5$::jsonb;
 if exists(select 1 from academy_tef_reading.papers where id='tef-reading-05' and version='tef-reading-2026-11-original-05-v1' and content<>paper) then raise exception 'Cannot modify published TEF Reading paper version tef-reading-05';end if;
 insert into academy_tef_reading.papers(id,version,content) values('tef-reading-05','tef-reading-2026-11-original-05-v1',paper) on conflict do nothing;

 paper := $bank6${"id":"tef-reading-06","version":"tef-reading-2026-11-original-06-v1","title":"TEF Canada · Compréhension écrite · Test 06","seconds":3600,"maxPoints":40,"questions":[{"number":1,"points":1,"passage":"🎬 CINÉMA LA PASSERELLE\nUne séance sensoriellement adaptée aura lieu samedi à 11 h : le volume sonore sera réduit et une lumière douce restera allumée. Les spectateurs pourront sortir puis revenir pendant le film. Le placement sera libre dans les rangées accessibles.","question":"Quel aménagement concerne directement l'environnement de la projection ?","options":["Une diffusion sans dialogue et sans sous-titres","Une projection réservée uniquement aux abonnés","Une baisse du son accompagnée d'un éclairage discret","Une retransmission du film dans le hall d'entrée"],"correct":"C","explanation":"Le son est atténué et un éclairage discret reste allumé.","semantic":{"concept":"accessible-movie-sound-dim-lights","evidence":"reduced-volume-gentle-light"},"media":{"kind":"illustration","scene":"cinema","heading":"Séance sensoriellement adaptée"}},{"number":2,"points":1,"passage":"🔬 CENTRE MÉTÉOROLOGIQUE\nLe lancement public du ballon de mesure peut être avancé ou retardé selon la direction du vent. Les visiteurs sont invités à vérifier l'heure affichée sur le site le matin même. Les conférences en salle conserveront leurs horaires prévus.","question":"Quelle activité demande de consulter un horaire actualisé ?","options":["La conférence organisée dans le bâtiment principal","La visite de la petite exposition permanente","La remise des documents d'information à l'accueil","L'observation du lancement du ballon météorologique"],"correct":"D","explanation":"Les conditions de vent peuvent modifier l'heure du lancement mais pas les conférences.","semantic":{"concept":"weather-balloon-wind-launch-scheduling","evidence":"outdoor-release-variable"},"media":{"kind":"illustration","scene":"weatherballoon","heading":"Mesure de l'atmosphère"}},{"number":3,"points":1,"passage":"🍇 COOPÉRATIVE VITICOLE\nLes visites de cave sont proposées aux groupes de dix personnes ou plus, sur réservation. Les dégustations peuvent être remplacées par une découverte des arômes pour les visiteurs qui ne consomment pas de vin.","question":"Quelle solution est proposée aux adultes qui ne veulent pas déguster ?","options":["Une activité consacrée à la reconnaissance des arômes","Une visite de la cave sans accompagnateur","Une réduction automatique sur l'achat d'une bouteille","Un départ immédiat avant la fin de la visite"],"correct":"A","explanation":"Une découverte des arômes peut remplacer la dégustation.","semantic":{"concept":"winery-aroma-substitute","evidence":"alternative-to-wine-tasting"},"media":{"kind":"notice","icon":"🍇","heading":"Visite de la coopérative","accent":"#79549e"}},{"number":4,"points":1,"passage":"🎹 CONSERVATOIRE MUNICIPAL\nLes candidats à la classe de piano disposent d'un piano dans la salle d'audition, même s'ils préfèrent leur propre instrument transportable. Ils doivent en revanche apporter leurs partitions imprimées en deux exemplaires.","question":"Que doit apporter chaque candidat ?","options":["Son propre piano pour pouvoir jouer","Une preuve d'achat de son instrument","Un enregistrement préalable de son audition","Deux copies papier de ses partitions"],"correct":"D","explanation":"L'instrument est fourni, mais deux copies des partitions sont obligatoires.","semantic":{"concept":"conservatory-two-score-copies","evidence":"sheet-music-two-instrument-provided"},"media":{"kind":"notice","icon":"🎹","heading":"Audition de piano","accent":"#427fa6"}},{"number":5,"points":1,"passage":"🚉 PASS RÉGIONAL\nLe pass week-end est valable du vendredi 18 h au dimanche minuit. Un voyage commencé avant cette échéance mais se terminant après minuit nécessite un titre couvrant la partie du trajet effectuée le lundi.","question":"Quelle situation exige un titre de transport complémentaire ?","options":["Un trajet qui se poursuit après le dimanche à minuit","Un départ effectué le vendredi à 19 h","Une correspondance pendant la journée du samedi","Un retour effectué le dimanche en début de soirée"],"correct":"A","explanation":"La validité cesse à minuit dimanche, y compris pour un trajet déjà commencé.","semantic":{"concept":"ticket-crosses-weekend-midnight","evidence":"travel-monday-segment-uncovered"},"media":{"kind":"notice","icon":"🚆","heading":"Pass week-end · validité","accent":"#22838a"}},{"number":6,"points":1,"passage":"🌳 VERGER PARTAGÉ\nLa récolte collective de samedi est ouverte aux bénévoles inscrits. Les fruits cueillis seront d'abord pesés pour les associations alimentaires, puis le surplus sera partagé entre les participants. Merci de ne rien emporter avant la fin de la pesée.","question":"Quand les participants pourront-ils emporter une part de la récolte ?","options":["Dès qu'ils auront rempli leur panier personnel","Uniquement avant le passage des responsables de pesée","Après l'attribution prioritaire destinée aux associations","Avant que les fruits réservés aux associations soient comptés"],"correct":"C","explanation":"Les bénévoles reçoivent le surplus après la pesée et le don prioritaire.","semantic":{"concept":"orchard-harvest-charity-first","evidence":"share-surplus-after-weighting"},"media":{"kind":"illustration","scene":"orchard","heading":"Récolte au verger"}},{"number":7,"points":1,"passage":"🏰 TOUR MÉDIÉVALE\nLe sommet de la tour n'est accessible que par un escalier étroit. Une projection panoramique de la vue est proposée au rez-de-chaussée pour les personnes qui ne souhaitent pas monter. Le billet donne accès aux deux expériences.","question":"Quelle solution existe pour les visiteurs ne montant pas l'escalier ?","options":["Un accès par ascenseur à la terrasse supérieure","Une visite extérieure avec un billet supplémentaire","Une présentation immersive de la vue depuis le bas","Un remboursement conditionné à un certificat médical"],"correct":"C","explanation":"La projection panoramique est comprise dans le billet et accessible au rez-de-chaussée.","semantic":{"concept":"medieval-tower-virtual-view-alternative","evidence":"ground-floor-panorama"},"media":{"kind":"notice","icon":"🏰","heading":"Tour historique · accès","accent":"#b07d45"}},{"number":8,"points":1,"passage":"Les candidats doivent fournir une pièce attestant qu'ils ________ dans la région depuis au moins un an.","question":"Quelle forme convient sans changer le sens ?","options":["résident","résideraient","résidassent","résideront"],"correct":"A","explanation":"L'attestation concerne une situation réelle et actuelle : l'indicatif « résident ».","semantic":{"concept":"residence-proof-present-indicative","evidence":"actual-residence"},"section":"cloze"},{"number":9,"points":1,"passage":"Le comité ne se prononcera pas tant que les experts n'______ pas remis leur avis.","question":"Quelle forme verbale convient au contexte ?","options":["avaient","auront","auraient","aient"],"correct":"B","explanation":"Le futur antérieur « auront remis » marque l'achèvement nécessaire avant une décision future.","semantic":{"concept":"future-perfect-with-tant-que","evidence":"experts-must-finish-first"},"section":"cloze"},{"number":10,"points":1,"passage":"Ce changement a été introduit ________ limiter les erreurs de saisie, et non pour réduire les contrôles.","question":"Quelle expression introduit un objectif ?","options":["afin de","faute de","à moins de","au lieu de"],"correct":"A","explanation":"« Afin de » introduit le but de l'action.","semantic":{"concept":"afin-de-express-purpose","evidence":"goal-reduce-entry-errors"},"section":"cloze"},{"number":11,"points":1,"passage":"L'association a présenté plusieurs pistes, dont aucune ne ________ à elle seule résoudre la difficulté.","question":"Quelle forme convient au sujet de la relative ?","options":["semble","semblent","semblerait","sembleront"],"correct":"A","explanation":"« Aucune » est un sujet singulier et commande « semble ».","semantic":{"concept":"aucune-singular-verb-agreement","evidence":"aucune-ne-semble"},"section":"cloze"},{"number":12,"points":1,"passage":"TRADUCTION COLLECTIVE\nPour garantir la cohérence des termes techniques, l'équipe tiendra un ________ (1) commun. Les divergences seront discutées avant la version finale pour éviter des ________ (2) entre les chapitres.","question":"Quel nom convient à l'espace (1) ?","options":["glossaire","sommaire","registre","bulletin"],"correct":"A","explanation":"Un glossaire permet de fixer les mêmes termes pour toutes les traductions.","semantic":{"concept":"translation-common-glossary","evidence":"technical-terms-consistent"},"section":"paired-cloze","group":"Traduction collective"},{"number":13,"points":1,"passage":"TRADUCTION COLLECTIVE\nPour garantir la cohérence des termes techniques, l'équipe tiendra un ________ (1) commun. Les divergences seront discutées avant la version finale pour éviter des ________ (2) entre les chapitres.","question":"Quel nom convient à l'espace (2) ?","options":["incohérences","annotations","illustrations","corrections"],"correct":"A","explanation":"La coordination évite des choix terminologiques contradictoires entre chapitres.","semantic":{"concept":"translation-cross-chapter-consistency","evidence":"avoid-inconsistent-wording"},"section":"paired-cloze","group":"Traduction collective"},{"number":14,"points":1,"passage":"ACCUEIL DES PATIENTS\nLe nouveau système attribue une priorité selon la ________ (1) de la situation, et non l'heure d'arrivée. Le personnel explique cette procédure afin de ________ (2) les malentendus pendant l'attente.","question":"Quel nom convient à l'espace (1) ?","options":["durée","fréquence","distance","gravité"],"correct":"D","explanation":"Le triage classe les situations selon leur gravité médicale.","semantic":{"concept":"patient-triage-medical-acuity","evidence":"severity-not-arrival-time"},"section":"paired-cloze","group":"Triage des patients"},{"number":15,"points":1,"passage":"ACCUEIL DES PATIENTS\nLe nouveau système attribue une priorité selon la ________ (1) de la situation, et non l'heure d'arrivée. Le personnel explique cette procédure afin de ________ (2) les malentendus pendant l'attente.","question":"Quel verbe convient à l'espace (2) ?","options":["multiplier","prévenir","signaler","prolonger"],"correct":"B","explanation":"L'explication permet d'éviter les malentendus avant leur apparition.","semantic":{"concept":"triage-explained-to-prevent-disputes","evidence":"clear-procedure-reduces-confusion"},"section":"paired-cloze","group":"Triage des patients"},{"number":16,"points":1,"passage":"ACHATS RESPONSABLES\nLe fournisseur propose un tarif réduit pour des commandes ________ (1) sur une seule livraison. Le client souhaite cependant s'assurer que la qualité restera ________ (2) d'un lot à l'autre.","question":"Quel participe convient à l'espace (1) ?","options":["différées","fractionnées","refusées","regroupées"],"correct":"D","explanation":"Regrouper plusieurs commandes sur une livraison réduit les coûts logistiques.","semantic":{"concept":"supplier-combined-delivery-discount","evidence":"consolidate-order"},"section":"paired-cloze","group":"Livraisons regroupées"},{"number":17,"points":1,"passage":"ACHATS RESPONSABLES\nLe fournisseur propose un tarif réduit pour des commandes ________ (1) sur une seule livraison. Le client souhaite cependant s'assurer que la qualité restera ________ (2) d'un lot à l'autre.","question":"Quel adjectif convient à l'espace (2) ?","options":["imprévisible","différente","constante","occasionnelle"],"correct":"C","explanation":"La demande porte sur une qualité stable entre différents lots.","semantic":{"concept":"supplier-stable-quality-batches","evidence":"consistent-lots"},"section":"paired-cloze","group":"Livraisons regroupées"},{"number":18,"points":1,"passage":"","question":"Quelle mission conviendrait à un candidat bilingue qui préfère travailler à domicile, uniquement en semaine, sans être disponible le soir ?","options":["Offre 1","Offre 2","Offre 3","Offre 4"],"correct":"D","explanation":"L'offre 4 combine le travail écrit bilingue, le télétravail et les horaires de semaine en journée.","semantic":{"concept":"bilingual-remote-weekday-daytime","evidence":"all-constraints-remote-bilingual"},"section":"offers","media":{"kind":"offers","heading":"Missions · Service à distance","items":["Assistance bilingue : télétravail, roulement le soir et le week-end.","Traduction écrite : télétravail, disponibilité imposée le samedi.","Accueil touristique bilingue : présence en boutique du lundi au vendredi.","Support client écrit bilingue : télétravail, lundi-vendredi, 9 h–17 h."]}},{"number":19,"points":1,"passage":"","question":"Quelle offre permet à un titulaire d'un certificat de conduite de machine d'obtenir un poste stable, sans déplacements professionnels ?","options":["Offre 1","Offre 2","Offre 3","Offre 4"],"correct":"B","explanation":"La deuxième offre est permanente, sur un site unique, avec la certification demandée.","semantic":{"concept":"licensed-machine-operator-single-site-permanent","evidence":"certificate-cdi-not-itinerant"},"section":"offers","media":{"kind":"offers","heading":"Offres d'emploi · Fabrication","items":["Maintenance itinérante : certificat exigé, contrat long, visites de plusieurs usines.","Atelier de fabrication : opérateur certifié, CDI sur un seul établissement.","Transport régional : conducteur certifié, CDI, déplacements fréquents.","Entrepôt saisonnier : conduite de machine, six mois, un seul site."]}},{"number":20,"points":1,"passage":"MESURES DE PRODUCTION\nChaque courbe comporte cinq valeurs successives.","question":"Quel graphique affiche deux baisses suivies d'une hausse puis d'une dernière baisse, la valeur finale restant supérieure au minimum atteint ?","options":["Graphique 2","Graphique 1","Graphique 3","Graphique 4"],"correct":"A","explanation":"La série 2 va de 28 à 19 puis 11, remonte à 24 et redescend à 16, au-dessus du minimum.","semantic":{"concept":"chart-fall-fall-rise-fall-above-trough","evidence":"28-19-11-24-16"},"section":"charts","media":{"kind":"chart-grid","heading":"Production de petites pièces","unit":"en centaines","years":["A","B","C","D","E"],"series":[[11,17,21,25,29],[28,19,11,24,16],[19,16,23,18,23],[14,14,19,24,24]]}},{"number":21,"points":1,"passage":"INDICATEURS SOCIAUX\nComparez les changements de période.","question":"Quel graphique augmente pendant deux périodes, puis reste constant une période avant de retomber sous son niveau de départ ?","options":["Graphique 1","Graphique 2","Graphique 3","Graphique 4"],"correct":"C","explanation":"La troisième série indique 12, 19, 26, 26, 8 : montée, palier et forte chute.","semantic":{"concept":"chart-two-increases-flat-drop-under-start","evidence":"12-19-26-26-8"},"section":"charts","media":{"kind":"chart-grid","heading":"Demandes traitées","unit":"en dizaines","years":["S1","S2","S3","S4","S5"],"series":[[21,17,12,18,23],[11,14,19,24,29],[12,19,26,26,8],[26,23,21,16,13]]}},{"number":22,"points":1,"passage":"CINQ PÉRIODES DE SUIVI\nLes évolutions sont comparées sur la même échelle.","question":"Quel graphique connaît un sommet à la troisième période et finit au même niveau que la deuxième, après un recul marqué ?","options":["Graphique 2","Graphique 3","Graphique 1","Graphique 4"],"correct":"C","explanation":"La série 1 culmine à 31 au milieu, baisse à 16 et finit à 20, exactement la deuxième valeur.","semantic":{"concept":"chart-third-peak-last-equals-second","evidence":"13-20-31-16-20"},"section":"charts","media":{"kind":"chart-grid","heading":"Participation à des ateliers","unit":"en centaines","years":["P1","P2","P3","P4","P5"],"series":[[13,20,31,16,20],[10,14,17,22,27],[25,19,14,11,7],[15,26,14,23,17]]}},{"number":23,"points":1,"passage":"Objet : Consultation des archives familiales\nBonjour,\nLa consultation des photographies de votre famille pourra se faire à la salle de recherche sur rendez-vous. Certaines images étant encore en cours d'inventaire, nous ne pouvons pas garantir que toutes seront disponibles lors de votre visite. Les reproductions destinées à un usage strictement personnel sont autorisées sans frais, à condition de conserver la référence d'archive. Si vous envisagez d'utiliser les images dans un ouvrage commercial, merci d'envoyer une demande spécifique décrivant le projet. Nous vous recommandons de nous communiquer au préalable les dates et noms recherchés pour faciliter l'identification des dossiers.\nLe service des archives.","question":"Quelle précaution l'institution formule-t-elle concernant l'accès aux photos ?","options":["La consultation sera remplacée par un envoi automatique","L'ensemble de la collection est définitivement inaccessible","Une partie des documents pourrait encore être indisponible","Les images ne sont consultables que par les éditeurs"],"correct":"C","explanation":"L'inventaire incomplet rend incertaine la disponibilité de certaines photos.","semantic":{"concept":"family-photos-not-all-inventoried","evidence":"availability-not-guaranteed"},"section":"email","group":"Archives familiales"},{"number":24,"points":1,"passage":"Objet : Consultation des archives familiales\nBonjour,\nLa consultation des photographies de votre famille pourra se faire à la salle de recherche sur rendez-vous. Certaines images étant encore en cours d'inventaire, nous ne pouvons pas garantir que toutes seront disponibles lors de votre visite. Les reproductions destinées à un usage strictement personnel sont autorisées sans frais, à condition de conserver la référence d'archive. Si vous envisagez d'utiliser les images dans un ouvrage commercial, merci d'envoyer une demande spécifique décrivant le projet. Nous vous recommandons de nous communiquer au préalable les dates et noms recherchés pour faciliter l'identification des dossiers.\nLe service des archives.","question":"Quelle utilisation nécessite une demande distincte ?","options":["La consultation des images dans la salle prévue","La reproduction des images dans une publication vendue","L'enregistrement de références pour ses propres recherches","La copie personnelle gardant la référence d'archive"],"correct":"B","explanation":"L'usage commercial demande une autorisation, contrairement à la copie personnelle.","semantic":{"concept":"family-archives-commercial-image-rights","evidence":"commercial-book-specific-request"},"section":"email","group":"Archives familiales"},{"number":25,"points":1,"passage":"Communiqué — Mesures de pluie participatives\nLa commune met des pluviomètres à disposition de volontaires souhaitant relever les précipitations dans leur quartier. Chaque appareil doit être placé à distance des murs et des grands arbres afin de limiter les mesures faussées. Les données seront saisies chaque lundi sur une plateforme protégée ; une synthèse anonymisée sera publiée en fin de mois. Les habitants ne doivent pas déplacer les appareils pendant la campagne sans prévenir le coordinateur. Les résultats contribueront à identifier des différences locales, mais ne remplaceront pas les stations météorologiques officielles.","question":"Pourquoi le lieu d'installation du pluviomètre est-il encadré ?","options":["Pour rendre l'appareil plus visible depuis les habitations","Pour faciliter sa connexion directe aux stations nationales","Pour réduire les influences extérieures sur la quantité recueillie","Pour éviter de transmettre des résultats à la plateforme"],"correct":"C","explanation":"Les murs et arbres voisins peuvent perturber la quantité de pluie collectée.","semantic":{"concept":"rain-gauge-placement-bias","evidence":"walls-and-trees-influence-collection"},"section":"email","group":"Pluviomètres participatifs"},{"number":26,"points":1,"passage":"Communiqué — Mesures de pluie participatives\nLa commune met des pluviomètres à disposition de volontaires souhaitant relever les précipitations dans leur quartier. Chaque appareil doit être placé à distance des murs et des grands arbres afin de limiter les mesures faussées. Les données seront saisies chaque lundi sur une plateforme protégée ; une synthèse anonymisée sera publiée en fin de mois. Les habitants ne doivent pas déplacer les appareils pendant la campagne sans prévenir le coordinateur. Les résultats contribueront à identifier des différences locales, mais ne remplaceront pas les stations météorologiques officielles.","question":"Quelle place ces mesures occuperont-elles dans l'information météorologique ?","options":["Une substitution complète aux stations météorologiques existantes","Une mesure réservée à la validation des demandes d'assurance","Un classement nominatif du niveau d'effort des participants","Un complément local aux dispositifs officiels de mesure"],"correct":"D","explanation":"Les relevés citoyens complètent les stations officielles et restent agrégés anonymement.","semantic":{"concept":"rain-volunteers-complement-official-measurements","evidence":"citizen-local-adds-data-not-replace"},"section":"email","group":"Pluviomètres participatifs"},{"number":27,"points":1,"passage":"Message aux professionnels — Formation à la simulation médicale\nLes inscriptions sont ouvertes pour deux journées de formation fondées sur des scénarios cliniques simulés. Les participants devront avoir suivi le module de préparation en ligne avant le premier jour. Les exercices seront filmés pour permettre une analyse collective des décisions prises, mais les vidéos ne seront pas utilisées pour l'évaluation individuelle des salariés ni diffusées en dehors du groupe sans accord. Une attestation sera délivrée à tous les présents ; elle ne constituera pas une autorisation d'exercer une nouvelle spécialité. Les équipes interprofessionnelles sont admises si leurs rôles sont communiqués à l'avance.","question":"Dans quel objectif les exercices sont-ils enregistrés ?","options":["Constituer un dossier permanent d'évaluation du personnel","Partager librement les vidéos avec des établissements extérieurs","Remplacer entièrement le module préparatoire en ligne","Discuter collectivement des choix réalisés pendant les simulations"],"correct":"D","explanation":"Les vidéos servent à un débriefing collectif et non à noter les salariés.","semantic":{"concept":"clinical-simulation-recordings-for-debrief","evidence":"group-analysis-not-individual-performance"},"section":"email","group":"Simulation médicale"},{"number":28,"points":1,"passage":"Message aux professionnels — Formation à la simulation médicale\nLes inscriptions sont ouvertes pour deux journées de formation fondées sur des scénarios cliniques simulés. Les participants devront avoir suivi le module de préparation en ligne avant le premier jour. Les exercices seront filmés pour permettre une analyse collective des décisions prises, mais les vidéos ne seront pas utilisées pour l'évaluation individuelle des salariés ni diffusées en dehors du groupe sans accord. Une attestation sera délivrée à tous les présents ; elle ne constituera pas une autorisation d'exercer une nouvelle spécialité. Les équipes interprofessionnelles sont admises si leurs rôles sont communiqués à l'avance.","question":"Quelle limite concerne l'attestation remise aux participants ?","options":["Elle n'est remise qu'aux responsables d'équipes","Elle autorise l'exercice d'une spécialité sans autres démarches","Elle remplace toute exigence de formation préalable","Elle ne confère pas une nouvelle habilitation professionnelle"],"correct":"D","explanation":"Une attestation de présence ne vaut pas autorisation d'exercer une spécialité.","semantic":{"concept":"clinical-training-certificate-not-licence","evidence":"attendance-not-practice-rights"},"section":"email","group":"Simulation médicale"},{"number":29,"points":1,"passage":"Annonce — Scène ouverte du centre culturel\nLe centre organise une soirée de lectures théâtrales le 22 juin. Les groupes amateurs pourront proposer un extrait de dix minutes maximum. Les textes originaux sont acceptés ; les œuvres protégées par des droits nécessiteront une autorisation de représentation avant leur sélection. Une répétition collective est prévue le matin même, sans public. Le centre fournira un éclairage simple et deux micros ; tout matériel supplémentaire reste soumis à disponibilité. Les organisateurs choisiront les propositions en tenant compte de la durée totale de la soirée et de la diversité des genres.","question":"Que doivent fournir les groupes souhaitant jouer un texte protégé ?","options":["Une preuve que l'auteur assiste à la répétition","Une autorisation concernant sa représentation publique","Une promesse de publier le texte après le spectacle","Un devis pour l'achat des micros de la salle"],"correct":"B","explanation":"Une œuvre protégée nécessite une autorisation de représentation avant sélection.","semantic":{"concept":"amateur-theater-protected-text-permission","evidence":"copyrighted-script-performance-rights"},"section":"email","group":"Lectures théâtrales"},{"number":30,"points":1,"passage":"Annonce — Scène ouverte du centre culturel\nLe centre organise une soirée de lectures théâtrales le 22 juin. Les groupes amateurs pourront proposer un extrait de dix minutes maximum. Les textes originaux sont acceptés ; les œuvres protégées par des droits nécessiteront une autorisation de représentation avant leur sélection. Une répétition collective est prévue le matin même, sans public. Le centre fournira un éclairage simple et deux micros ; tout matériel supplémentaire reste soumis à disponibilité. Les organisateurs choisiront les propositions en tenant compte de la durée totale de la soirée et de la diversité des genres.","question":"Quel facteur pourrait conduire à écarter une proposition pourtant conforme ?","options":["L'absence de texte original lorsqu'une autorisation existe","Le fait de demander les deux micros déjà fournis","Le choix d'une répétition sans spectateurs","Le besoin d'équilibrer les genres et le temps total de la soirée"],"correct":"D","explanation":"La programmation est limitée par le temps total et la variété des genres.","semantic":{"concept":"amateur-theater-curatorial-time-genre-balance","evidence":"even-valid-entry-may-not-fit-program"},"section":"email","group":"Lectures théâtrales"},{"number":31,"points":1,"passage":"Note aux voyageurs — Correspondance en gare de Cormont\nÀ partir de décembre, les trains de l'ouest arriveront généralement sur la voie 4 plutôt que la voie 2. La correspondance pour les petites communes restera sur la voie 6, accessible par passage souterrain. Les voyageurs pressés pourront demander une aide à l'orientation, mais aucun retard ne sera garanti pour attendre une arrivée tardive. Les horaires publiés reposent sur des temps de marche moyens. Les personnes se déplaçant lentement sont invitées à choisir une correspondance plus longue.","question":"Quelle précaution est recommandée aux voyageurs ayant besoin de plus de temps pour marcher ?","options":["Compter sur un retard volontaire du train de correspondance","Attendre sur l'ancien quai d'arrivée sans se déplacer","Choisir un itinéraire offrant une correspondance plus longue","Éviter de demander des informations au personnel"],"correct":"C","explanation":"Les temps moyens de déplacement entre quais peuvent être insuffisants pour certains.","semantic":{"concept":"rail-change-station-transfer-time-margin","evidence":"timetable-assumes-average-walking"},"section":"email","group":"Correspondance ferroviaire"},{"number":32,"points":1,"passage":"Note aux voyageurs — Correspondance en gare de Cormont\nÀ partir de décembre, les trains de l'ouest arriveront généralement sur la voie 4 plutôt que la voie 2. La correspondance pour les petites communes restera sur la voie 6, accessible par passage souterrain. Les voyageurs pressés pourront demander une aide à l'orientation, mais aucun retard ne sera garanti pour attendre une arrivée tardive. Les horaires publiés reposent sur des temps de marche moyens. Les personnes se déplaçant lentement sont invitées à choisir une correspondance plus longue.","question":"Quelle limite s'applique à l'assistance offerte en gare ?","options":["Elle est réservée uniquement aux voyageurs avec fauteuil roulant","Elle aide à s'orienter sans assurer l'attente d'un autre train","Elle permet de changer gratuitement l'horaire de tous les trains","Elle garantit automatiquement le maintien des correspondances"],"correct":"B","explanation":"L'assistance à l'orientation n'entraîne aucune garantie de retard du train suivant.","semantic":{"concept":"rail-transfer-assistance-not-held-train","evidence":"orientation-does-not-guarantee-connection"},"section":"email","group":"Correspondance ferroviaire"},{"number":33,"points":1,"passage":"REPRODUIRE UNE EXPÉRIENCE : UN DÉFI SCIENTIFIQUE\nDans plusieurs disciplines, les chercheurs s'efforcent de reproduire les résultats publiés par d'autres équipes. Lorsqu'une observation ne se répète pas à l'identique, la conclusion n'est pas forcément que la première étude était erronée. Les conditions d'expérience, la composition des groupes examinés ou la manière de mesurer un phénomène peuvent avoir changé. En revanche, un résultat qui ne se retrouve pas malgré des procédures équivalentes appelle de nouvelles vérifications et parfois une révision des hypothèses de départ.\n\nUn institut a récemment commencé à financer ces travaux de reproduction, moins spectaculaires que la découverte d'un phénomène inédit. Les jeunes chercheurs craignent parfois que ces projets soient jugés peu originaux dans leur parcours professionnel. La direction souhaite donc valoriser explicitement les comptes rendus méthodologiques détaillés, y compris ceux qui aboutissent à une absence de confirmation. Cette politique ne vise pas à discréditer les premières équipes, mais à mieux distinguer ce qui dépend d'un contexte particulier de ce qui paraît général. Elle suppose aussi que les données nécessaires soient accessibles dans des conditions respectueuses de la vie privée et des engagements pris envers les participants.","question":"Pourquoi l'absence de reproduction ne suffit-elle pas toujours à invalider une première étude ?","options":["Des différences de protocole ou de population peuvent expliquer l'écart","La reproduction ne doit jamais être utilisée pour vérifier des résultats publiés","Les premiers résultats sont automatiquement considérés définitifs","Les chercheurs ne peuvent pas mesurer deux fois un même phénomène"],"correct":"A","explanation":"Le texte distingue des conditions différentes et une absence réelle de confirmation avec protocole équivalent.","semantic":{"concept":"replication-protocol-differences-not-falsification","evidence":"changes-in-sample-or-measurement"},"section":"long","group":"Reproduction scientifique"},{"number":34,"points":1,"passage":"REPRODUIRE UNE EXPÉRIENCE : UN DÉFI SCIENTIFIQUE\nDans plusieurs disciplines, les chercheurs s'efforcent de reproduire les résultats publiés par d'autres équipes. Lorsqu'une observation ne se répète pas à l'identique, la conclusion n'est pas forcément que la première étude était erronée. Les conditions d'expérience, la composition des groupes examinés ou la manière de mesurer un phénomène peuvent avoir changé. En revanche, un résultat qui ne se retrouve pas malgré des procédures équivalentes appelle de nouvelles vérifications et parfois une révision des hypothèses de départ.\n\nUn institut a récemment commencé à financer ces travaux de reproduction, moins spectaculaires que la découverte d'un phénomène inédit. Les jeunes chercheurs craignent parfois que ces projets soient jugés peu originaux dans leur parcours professionnel. La direction souhaite donc valoriser explicitement les comptes rendus méthodologiques détaillés, y compris ceux qui aboutissent à une absence de confirmation. Cette politique ne vise pas à discréditer les premières équipes, mais à mieux distinguer ce qui dépend d'un contexte particulier de ce qui paraît général. Elle suppose aussi que les données nécessaires soient accessibles dans des conditions respectueuses de la vie privée et des engagements pris envers les participants.","question":"Quel changement institutionnel cherche à encourager ces travaux ?","options":["Réserver tous les financements à des découvertes inédites","Reconnaître la valeur scientifique de vérifications même non concluantes","Supprimer les comptes rendus de méthodes détaillées","Éviter d'examiner les résultats qui ne sont pas confirmés"],"correct":"B","explanation":"Le financement et la reconnaissance des résultats négatifs valorisent les reproductions scientifiques.","semantic":{"concept":"replication-recognize-negative-findings","evidence":"fund-and-value-detailed-null-outcomes"},"section":"long","group":"Reproduction scientifique"},{"number":35,"points":1,"passage":"L'ENSEIGNEMENT À DISTANCE DANS LES TERRITOIRES ISOLÉS\nPour les petites communes éloignées des établissements de formation, les cours à distance semblent offrir une solution économique. Les organismes peuvent rassembler des élèves dispersés et proposer des matières qui ne seraient pas enseignées localement. Pourtant, plusieurs enquêtes montrent que l'accès au contenu ne suffit pas : les apprenants ont parfois besoin d'un lieu calme, d'une connexion stable et de personnes capables de les aider à organiser leur travail. Lorsque ces conditions font défaut, la souplesse annoncée peut se traduire par un décrochage progressif.\n\nUne région a donc choisi de financer des espaces d'étude partagés, ouverts quelques jours par semaine, plutôt que de distribuer uniquement des ordinateurs individuels. Ces lieux disposent de connexions fiables et accueillent des accompagnateurs qui ne remplacent pas les enseignants : ils facilitent l'accès aux cours et orientent les élèves lorsqu'une difficulté persiste. Les premiers retours mettent en évidence une assiduité plus régulière chez les participants, sans encore démontrer une hausse durable des résultats aux examens. Les responsables veulent comparer plusieurs cohortes avant de généraliser le dispositif. Leur objectif est de combiner l'accès numérique avec un soutien de proximité, au lieu de considérer que l'équipement matériel constitue à lui seul une politique éducative complète.","question":"Quelle limite d'une simple distribution d'ordinateurs est mise en avant ?","options":["Elle rend impossible l'accès aux matières enseignées en ligne","Elle supprime les besoins en formation pour tous les enseignants","Elle entraîne forcément une baisse immédiate de l'assiduité","Elle ne garantit ni un cadre d'étude favorable ni un accompagnement quotidien"],"correct":"D","explanation":"Un ordinateur seul ne garantit pas l'environnement ou le soutien nécessaires à l'apprentissage.","semantic":{"concept":"rural-online-education-device-insufficient","evidence":"quiet-space-reliable-connection-and-mentoring"},"section":"long","group":"Formation à distance rurale"},{"number":36,"points":1,"passage":"L'ENSEIGNEMENT À DISTANCE DANS LES TERRITOIRES ISOLÉS\nPour les petites communes éloignées des établissements de formation, les cours à distance semblent offrir une solution économique. Les organismes peuvent rassembler des élèves dispersés et proposer des matières qui ne seraient pas enseignées localement. Pourtant, plusieurs enquêtes montrent que l'accès au contenu ne suffit pas : les apprenants ont parfois besoin d'un lieu calme, d'une connexion stable et de personnes capables de les aider à organiser leur travail. Lorsque ces conditions font défaut, la souplesse annoncée peut se traduire par un décrochage progressif.\n\nUne région a donc choisi de financer des espaces d'étude partagés, ouverts quelques jours par semaine, plutôt que de distribuer uniquement des ordinateurs individuels. Ces lieux disposent de connexions fiables et accueillent des accompagnateurs qui ne remplacent pas les enseignants : ils facilitent l'accès aux cours et orientent les élèves lorsqu'une difficulté persiste. Les premiers retours mettent en évidence une assiduité plus régulière chez les participants, sans encore démontrer une hausse durable des résultats aux examens. Les responsables veulent comparer plusieurs cohortes avant de généraliser le dispositif. Leur objectif est de combiner l'accès numérique avec un soutien de proximité, au lieu de considérer que l'équipement matériel constitue à lui seul une politique éducative complète.","question":"Pourquoi les responsables refusent-ils de conclure déjà à une amélioration scolaire ?","options":["Les accompagnateurs ont remplacé les enseignants dans tous les cours","La régularité accrue ne prouve pas encore un gain durable aux examens","La région a supprimé les évaluations des formations en ligne","Les élèves ne fréquentent jamais les lieux d'étude partagés"],"correct":"B","explanation":"Les signes d'assiduité sont positifs, mais les résultats aux examens n'ont pas encore été confirmés.","semantic":{"concept":"rural-education-attendance-vs-exam-outcomes","evidence":"engagement-not-yet-grades"},"section":"long","group":"Formation à distance rurale"},{"number":37,"points":1,"passage":"LES AVIS EN LIGNE SONT-ILS TOUJOURS UTILES ?\nLes plateformes d'avis offrent un moyen rapide de connaître l'expérience d'autres clients. Une moyenne élevée peut cependant dissimuler des situations différentes : quelques évaluations excellentes ne décrivent pas la même réalité qu'un grand nombre de notes régulièrement positives. Les recherches suggèrent également que les personnes très satisfaites ou très déçues publient plus volontiers un commentaire que celles dont l'expérience a été ordinaire. L'échantillon visible ne correspond donc pas nécessairement à l'ensemble des utilisateurs.\n\nUne association de consommateurs a expérimenté une présentation mettant en avant l'évolution des notes dans le temps, leur répartition et les motifs récurrents des critiques. Certains professionnels regrettent que cette information demande davantage d'attention à la lecture. L'association répond qu'un seul chiffre peut donner une impression de précision trompeuse. Elle n'affirme pas qu'un avis négatif est nécessairement plus fiable qu'un avis favorable : elle cherche à replacer les témoignages dans un ensemble et à signaler les incertitudes liées au faible nombre d'observations. L'objectif est de permettre un jugement nuancé plutôt que de désigner automatiquement les meilleurs établissements.","question":"Quel biais peut affecter les notes publiées ?","options":["Les clients vivant des expériences extrêmes s'expriment plus souvent","Les commentaires proviennent toujours de clients rémunérés","Les consommateurs ne lisent que les avis négatifs récents","Les notes élevées sont automatiquement retirées des plateformes"],"correct":"A","explanation":"L'échantillon est biaisé parce que les clients très satisfaits ou mécontents répondent plus souvent.","semantic":{"concept":"online-rating-self-selection-extreme","evidence":"extremely-happy-unhappy-overrepresent"},"section":"long","group":"Avis en ligne"},{"number":38,"points":1,"passage":"LES AVIS EN LIGNE SONT-ILS TOUJOURS UTILES ?\nLes plateformes d'avis offrent un moyen rapide de connaître l'expérience d'autres clients. Une moyenne élevée peut cependant dissimuler des situations différentes : quelques évaluations excellentes ne décrivent pas la même réalité qu'un grand nombre de notes régulièrement positives. Les recherches suggèrent également que les personnes très satisfaites ou très déçues publient plus volontiers un commentaire que celles dont l'expérience a été ordinaire. L'échantillon visible ne correspond donc pas nécessairement à l'ensemble des utilisateurs.\n\nUne association de consommateurs a expérimenté une présentation mettant en avant l'évolution des notes dans le temps, leur répartition et les motifs récurrents des critiques. Certains professionnels regrettent que cette information demande davantage d'attention à la lecture. L'association répond qu'un seul chiffre peut donner une impression de précision trompeuse. Elle n'affirme pas qu'un avis négatif est nécessairement plus fiable qu'un avis favorable : elle cherche à replacer les témoignages dans un ensemble et à signaler les incertitudes liées au faible nombre d'observations. L'objectif est de permettre un jugement nuancé plutôt que de désigner automatiquement les meilleurs établissements.","question":"Pourquoi l'association veut-elle afficher la distribution et l'évolution des avis ?","options":["Pour imposer exactement le même classement à tous les lecteurs","Pour éviter qu'une moyenne unique masque des situations contrastées","Pour donner systématiquement plus de poids aux critiques négatives","Pour remplacer les témoignages par une recommandation unique"],"correct":"B","explanation":"La moyenne seule peut masquer la répartition et l'évolution des expériences.","semantic":{"concept":"online-rating-mean-obscures-variability","evidence":"trend-and-count-distribution-needed"},"section":"long","group":"Avis en ligne"},{"number":39,"points":1,"passage":"LA PLACE DE L'EAU DANS LA RÉNOVATION DES RUES\nDe plus en plus de communes souhaitent remplacer certaines surfaces imperméables par des matériaux qui laissent infiltrer l'eau de pluie. L'objectif est de limiter les ruissellements vers les réseaux d'évacuation. Pourtant, ces aménagements n'offrent pas les mêmes résultats partout : le type de sol, la pente et l'entretien des surfaces déterminent la quantité d'eau réellement absorbée. Installer un revêtement perméable sur un terrain déjà saturé peut avoir un effet limité lors d'un orage violent.\n\nDans une ville moyenne, une équipe a commencé par expérimenter plusieurs matériaux sur des rues présentant des conditions différentes. Les premières mesures montrent des résultats prometteurs dans certains secteurs, mais une diminution rapide de l'efficacité là où les pores du revêtement se bouchent avec des sédiments. La municipalité étudie alors la fréquence et le coût des nettoyages nécessaires. Quelques élus souhaitent généraliser rapidement les aménagements, car ils sont visibles et populaires. Les ingénieurs recommandent plutôt de comparer les performances sur plusieurs saisons et de réserver les projets les plus ambitieux aux lieux où le sol et les usages rendent l'infiltration réellement possible. Ils insistent sur le fait que la durabilité dépend autant de l'entretien que du matériau choisi.","question":"Pourquoi un revêtement perméable ne garantit-il pas partout le même résultat ?","options":["Il ne peut absorber que l'eau des pluies faibles par définition","Il fonctionne uniquement sur les voies réservées aux voitures","Son efficacité dépend notamment du sol et de son entretien","La pente n'a aucune influence sur le ruissellement des eaux"],"correct":"C","explanation":"Le sol, la pente et le colmatage des matériaux influencent la capacité d'infiltration.","semantic":{"concept":"street-permeability-needs-maintenance-and-soil","evidence":"soil-slope-clogging"},"section":"long","group":"Voirie perméable"},{"number":40,"points":1,"passage":"LA PLACE DE L'EAU DANS LA RÉNOVATION DES RUES\nDe plus en plus de communes souhaitent remplacer certaines surfaces imperméables par des matériaux qui laissent infiltrer l'eau de pluie. L'objectif est de limiter les ruissellements vers les réseaux d'évacuation. Pourtant, ces aménagements n'offrent pas les mêmes résultats partout : le type de sol, la pente et l'entretien des surfaces déterminent la quantité d'eau réellement absorbée. Installer un revêtement perméable sur un terrain déjà saturé peut avoir un effet limité lors d'un orage violent.\n\nDans une ville moyenne, une équipe a commencé par expérimenter plusieurs matériaux sur des rues présentant des conditions différentes. Les premières mesures montrent des résultats prometteurs dans certains secteurs, mais une diminution rapide de l'efficacité là où les pores du revêtement se bouchent avec des sédiments. La municipalité étudie alors la fréquence et le coût des nettoyages nécessaires. Quelques élus souhaitent généraliser rapidement les aménagements, car ils sont visibles et populaires. Les ingénieurs recommandent plutôt de comparer les performances sur plusieurs saisons et de réserver les projets les plus ambitieux aux lieux où le sol et les usages rendent l'infiltration réellement possible. Ils insistent sur le fait que la durabilité dépend autant de l'entretien que du matériau choisi.","question":"Quelle approche les ingénieurs préconisent-ils avant une généralisation ?","options":["Installer les mêmes matériaux sur chaque rue au plus vite","Observer les performances sur plusieurs saisons et choisir les lieux adaptés","Décider uniquement selon la popularité visuelle des aménagements","Abandonner toute comparaison des frais d'entretien à long terme"],"correct":"B","explanation":"Les ingénieurs demandent des observations sur la durée avant l'extension.","semantic":{"concept":"street-materials-multi-season-site-specific-rollout","evidence":"test-long-term-and-select-streets"},"section":"long","group":"Voirie perméable"}]}$bank6$::jsonb;
 if exists(select 1 from academy_tef_reading.papers where id='tef-reading-06' and version='tef-reading-2026-11-original-06-v1' and content<>paper) then raise exception 'Cannot modify published TEF Reading paper version tef-reading-06';end if;
 insert into academy_tef_reading.papers(id,version,content) values('tef-reading-06','tef-reading-2026-11-original-06-v1',paper) on conflict do nothing;
