do $audit$
declare count_tests integer;count_questions integer;
begin
 select count(*) into count_tests from academy_tef_reading.current_papers;
 if count_tests<>6 then raise exception 'Expected 6 current TEF Reading tests, found %',count_tests;end if;
 select sum(jsonb_array_length(p.content->'questions')) into count_questions
 from academy_tef_reading.current_papers c join academy_tef_reading.papers p
  on p.id=c.id and p.version=c.version;
 if count_questions<>240 then raise exception 'Expected 240 questions, found %',count_questions;end if;
